const DELEGATION_RESULTS_READY_OUTCOME: &str = "delegation_results_ready";
/// When this process started, for the recovery sweep's ownership rule: a
/// runnable row last touched before this instant belongs to an owner that
/// died with the previous process.
static PROCESS_STARTED_AT_MS: once_cell::sync::Lazy<i64> =
    once_cell::sync::Lazy::new(|| chrono::Utc::now().timestamp_millis());
const MAX_PLANNING_ELICITATION_ITERATIONS: usize =
    crate::magician_v2::pipeline::agent::MAX_REFINEMENT_ROUNDS as usize;
/// Operator redirects are compact next-turn guidance, not an alternate prompt
/// transport. Bound both dimensions so a stalled execution cannot retain an
/// unbounded amount of user-controlled text.
pub const MAX_STEER_MESSAGE_BYTES: usize = 4 * 1024;
pub const MAX_PENDING_STEERS: usize = 16;
const MANUAL_PAUSE_READY_TIMEOUT: Duration = Duration::from_secs(30);
const MANUAL_PAUSE_READY_POLL: Duration = Duration::from_millis(25);
/// Give a timed-out pipeline stage a short opportunity to observe its
/// cancellation token and finish its own cleanup before the scheduler aborts
/// the task. Both waits are bounded; an uncooperative task cannot keep the
/// pipeline owner installed indefinitely.
const PIPELINE_STAGE_CANCELLATION_GRACE: Duration = Duration::from_secs(2);
const PIPELINE_STAGE_ABORT_GRACE: Duration = Duration::from_millis(250);
const SERVER_OWNED_FRESH_LAUNCH_MAX_AGE_MS: i64 = 60 * 60 * 1_000;
const SERVER_OWNED_FRESH_LAUNCH_MAX_ENTRIES: usize = 4_096;

#[derive(Clone, Debug)]
enum ParentReconciliationRetryTarget {
    Parent(String),
    TerminalChild(String),
}

impl ParentReconciliationRetryTarget {
    fn key(&self) -> String {
        match self {
            Self::Parent(execution_id) => format!("parent:{execution_id}"),
            Self::TerminalChild(execution_id) => format!("child:{execution_id}"),
        }
    }
}

#[derive(Clone, Debug)]
struct ParentReconciliationRetryCandidate {
    target: ParentReconciliationRetryTarget,
    retry_attempt: u32,
    next_attempt_at_ms: i64,
}
/// A scheduler retry is a re-entry into this one durable logical attempt. It
/// must not mint a new loop/effect-ledger address: an earlier invocation may
/// have completed an outward effect before losing the following state commit.
pub(crate) const PIPELINE_STAGE_LOGICAL_ATTEMPT: usize = 1;
const PIPELINE_RECOVERED_DELIVERABLE_LOSS_PREFIX: &str = "[pipeline_recovery_deliverable_lost] ";
enum PipelineStageTaskWait<T> {
    Completed(Option<std::result::Result<T, tokio::task::JoinError>>),
    TimedOut,
}

/// Result of consuming the exact checkpoint of a parent parked on delegated
/// children. A fixed-roster stage is distinct from an ordinary root: once its
/// resumed inner segment settles, the durable outer cursor owns the result and
/// the caller must not project that inner outcome as the root execution.
pub(crate) enum DelegationCheckpointResume {
    Missing,
    /// Cancellation or another terminal owner won before exact continuation
    /// admission. The checkpoint must not be restored or cold-reconstructed.
    Superseded,
    /// Another process still owns the exact successor segment. The caller must
    /// preserve the handoff descriptor and perform no Runtime/Artifact
    /// projection; the durable wake retries after this bounded owner expires.
    Deferred {
        retry_at_ms: i64,
    },
    Outcome(crate::magician_v2::execution::AgenticOutcome),
    PipelineOwned,
}

/// Admission returned for an exact inner resume owned by a durable fixed-roster
/// pipeline stage. The absolute wall-clock deadline is retained across async
/// authority/tool-resolution work; callers derive the remaining runtime only
/// immediately before dispatch so setup latency cannot mint a fresh budget.
pub struct PipelineExactResumeAdmission {
    pub expired_outcome: Option<crate::magician_v2::execution::AgenticOutcome>,
    pub runtime_deadline_at_ms: Option<i64>,
}

impl PipelineExactResumeAdmission {
    pub fn remaining_runtime_ceiling_ms(&self) -> Option<u64> {
        self.runtime_deadline_at_ms.map(|deadline_at_ms| {
            u64::try_from(
                deadline_at_ms
                    .saturating_sub(chrono::Utc::now().timestamp_millis())
                    .max(0),
            )
            .unwrap_or(u64::MAX)
        })
    }
}

