/// Refreshed durable pause admission retained under the exact execution
/// lifecycle fence. Orphan and destructive lifecycle callers keep this value
/// alive through their mutation so terminal publication cannot invalidate the
/// decision between the durable scan and the state write.
pub struct ResumablePauseLifecycleAdmission {
    _execution_id: String,
    resumable: bool,
    staged: bool,
    canonical_diff_approval: bool,
    _execution_exclusion: StatelessTerminalExecutionLifecycleExclusion,
}

impl ResumablePauseLifecycleAdmission {
    pub fn resumable(&self) -> bool {
        self.resumable
    }

    pub fn staged(&self) -> bool {
        self.staged
    }

    pub fn canonical_diff_approval(&self) -> bool {
        self.canonical_diff_approval
    }
}

/// Recovery admission acquired in the global control-tree -> exact execution
/// order. It lets a delegated-child recovery retain both authorities through
/// subtype classification, forced terminality, and projection without
/// inverting ordinary tree cancellation's lock order.
pub struct DelegatedRecoveryPauseLifecycleAdmission {
    execution_id: String,
    pause: ResumablePauseLifecycleAdmission,
    orchestrator: Weak<MagicianV2Orchestrator>,
    control_root_id: String,
    control_lock: Arc<tokio::sync::Mutex<()>>,
    control_guard: Option<tokio::sync::OwnedMutexGuard<()>>,
}

impl DelegatedRecoveryPauseLifecycleAdmission {
    pub fn resumable(&self) -> bool {
        self.pause.resumable()
    }

    pub fn staged(&self) -> bool {
        self.pause.staged()
    }

    pub fn canonical_diff_approval(&self) -> bool {
        self.pause.canonical_diff_approval()
    }
}

impl Drop for DelegatedRecoveryPauseLifecycleAdmission {
    fn drop(&mut self) {
        self.control_guard.take();
        if let Some(orchestrator) = self.orchestrator.upgrade() {
            orchestrator
                .prune_execution_control_tree_lock(&self.control_root_id, &self.control_lock);
        }
    }
}

