fn operator_execution_driver(
    resident: Option<crate::magician_v2::execution::agentic::run_loop::ExecutionDriver>,
    has_durable_stateless_epoch: bool,
    process_default: impl FnOnce() -> crate::magician_v2::execution::agentic::run_loop::ExecutionDriver,
) -> crate::magician_v2::execution::agentic::run_loop::ExecutionDriver {
    resident.unwrap_or_else(|| {
        if has_durable_stateless_epoch {
            crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::Stateless
        } else {
            process_default()
        }
    })
}

