struct ResumeTransactionHeartbeatGuard {
    stop: Option<CancellationToken>,
}

impl ResumeTransactionHeartbeatGuard {
    fn new(stop: Option<CancellationToken>) -> Self {
        Self { stop }
    }

    fn disarm(&mut self) -> Option<CancellationToken> {
        self.stop.take()
    }
}

impl Drop for ResumeTransactionHeartbeatGuard {
    fn drop(&mut self) {
        if let Some(stop) = self.stop.take() {
            stop.cancel();
        }
    }
}

#[derive(Default)]
struct ResumeClaimHeartbeatGuards(Vec<CancellationToken>);

impl ResumeClaimHeartbeatGuards {
    fn push(&mut self, stop: CancellationToken) {
        self.0.push(stop);
    }

    fn cancel_all(&mut self) {
        for stop in self.0.drain(..) {
            stop.cancel();
        }
    }
}

impl Drop for ResumeClaimHeartbeatGuards {
    fn drop(&mut self) {
        self.cancel_all();
    }
}

struct CancelTokenOnDrop(CancellationToken);

impl Drop for CancelTokenOnDrop {
    fn drop(&mut self) {
        self.0.cancel();
    }
}

