fn spawn_api_mining_startup_cleanup(
    workspace_layout: crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace,
    cleanup_config: crate::magician_v2::api_mining::maintenance::CleanupConfig,
) {
    let cleanup = move || run_api_mining_startup_cleanup(workspace_layout, cleanup_config);
    match tokio::runtime::Handle::try_current() {
        Ok(handle) => {
            handle.spawn(async move {
                tokio::time::sleep(Duration::from_secs(30)).await;
                match tokio::task::spawn_blocking(cleanup).await {
                    Ok(()) => {},
                    Err(error) => warn!(
                        error = %error,
                        "[API_MINING] Startup cleanup task failed to join"
                    ),
                }
            });
        },
        Err(_) => {
            std::thread::spawn(cleanup);
        },
    }
}

fn run_api_mining_startup_cleanup(
    workspace_layout: crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace,
    cleanup_config: crate::magician_v2::api_mining::maintenance::CleanupConfig,
) {
    let scopes_root = workspace_layout.base_root().join("scopes");
    let Ok(principals) = std::fs::read_dir(&scopes_root) else {
        return;
    };
    for principal_entry in principals.flatten() {
        let Ok(file_type) = principal_entry.file_type() else {
            continue;
        };
        if !file_type.is_dir() {
            continue;
        }
        let Some(principal) = principal_entry.file_name().to_str().map(str::to_string) else {
            continue;
        };
        let Ok(workspaces) = std::fs::read_dir(principal_entry.path()) else {
            continue;
        };
        for workspace_entry in workspaces.flatten() {
            let Ok(file_type) = workspace_entry.file_type() else {
                continue;
            };
            if !file_type.is_dir() {
                continue;
            }
            let Some(workspace) = workspace_entry.file_name().to_str().map(str::to_string) else {
                continue;
            };
            let scoped_root = workspace_layout.api_mining_root(&principal, &workspace);
            if !scoped_root.exists() {
                continue;
            }
            let report = crate::magician_v2::api_mining::maintenance::run_cleanup_with_config(
                &scoped_root,
                &cleanup_config,
            );
            for err in &report.errors {
                tracing::warn!(
                    "[API_MINING] Cleanup error for scope {}/{}: {}",
                    principal,
                    workspace,
                    err
                );
            }
        }
    }
}

use runtime_core::{ExecutionContext, RuntimeConfig, ToolCatalog, ToolInfo, ToolMatching};

