/// Normalize a raw observation mode string to a canonical token.
/// Returns `None` for unrecognized modes (closed set — unlike
/// `runtime::normalize_strategy_name` which accepts custom names).

/// Map the resolved strategy name from `agent:strategy_override` metadata to a
/// `StrategyType` enum variant.  Only the two concrete strategies are mapped;
/// unknown names return `None` so the adaptive selector's choice is preserved.
fn parse_agent_strategy_type(name: &str) -> Option<StrategyType> {
    match name {
        "atomic_composition" => Some(StrategyType::AtomicComposition),
        "guided_search" => Some(StrategyType::GuidedSearch),
        _ => None,
    }
}

