fn prompt_identity_for_agent_definition(definition: &AgentDefinition) -> PromptIdentityContext {
    let base_persona = if definition.persona.trim().is_empty() {
        None
    } else {
        Some(definition.persona.trim().to_string())
    };
    PromptIdentityContext {
        agent_kind: Some(match definition.kind {
            AgentKind::Personal => PromptAgentKind::User,
            AgentKind::Worker => PromptAgentKind::System,
        }),
        base_persona: base_persona.clone(),
        source_agent_id: Some(definition.agent_id.clone()),
        source_agent_name: Some(definition.name.trim().to_string()),
        source_agent_aliases: crate::magician_v2::presentation_identity::bounded_agent_aliases(
            &definition.aliases,
        ),
        source_agent_persona: base_persona,
        autonomous_controls: None,
    }
}

fn apply_agent_definition_execution_constraints(
    ctx: &mut AgenticContext,
    definition: &AgentDefinition,
) {
    ctx.max_delegation_depth = definition.constraints.coordination.max_delegation_depth;
    ctx.delegation_timeout_secs = definition
        .constraints
        .coordination
        .delegation_timeout_secs
        .max(1);
    ctx.max_tokens_per_cycle = Some(definition.constraints.max_tokens_per_cycle);
    // The run-start memory retrieval reads the tiers off the context and skips
    // entirely when they are absent, and the seed marks the retrieval
    // checkpoint complete either way — so a context that reaches the seed
    // without tiers gets empty memory sections AND a closed checkpoint, which
    // suppresses the executor's own run-start hydration for the rest of
    // generation zero. The owner profile installs the same value later from
    // the same source, so seeding it here only moves it earlier.
    ctx.tier_definitions = definition.memory_tiers.clone();
}

fn apply_persisted_delegation_depth(ctx: &mut AgenticContext, delegation_chain: &[String]) {
    ctx.depth = ctx.depth.max(delegation_chain.len());
}

