    /// Construct a scoped, recipe-aware auth healer over the same Magicutor
    /// client and encrypted secret store used by normal browser capture.
    pub fn recipe_auth_healer(
        &self,
        principal: &str,
        workspace: &str,
        recipe: &crate::magician_v2::api_mining::recipe::TaskRecipe,
    ) -> Option<Arc<dyn crate::magician_v2::api_mining::recipe_runner::AuthHealer>> {
        use crate::magician_v2::api_mining::auth_refresh::{
            requirements_for_recipe, OrchestratorAuthHealer,
        };
        use crate::magician_v2::execution::primitive_dispatch::browser::AgentBrowserSession;

        let secret_store = self.secret_store_for_scope(principal, workspace)?;
        let cli_path = AgentBrowserSession::resolve_cli_path_for_scope(
            Some(self.durable_artifact_workspace.base_root()),
            Some(principal),
            Some(workspace),
        )
        .map_err(|error| {
            tracing::warn!(
                principal,
                workspace,
                %error,
                "[API_MINING] auth heal unavailable because agent-browser is not installed"
            );
        })
        .ok()?;
        let requirements = recipe
            .current()
            .map(|version| {
                version
                    .origins
                    .iter()
                    .map(|origin| (origin.clone(), requirements_for_recipe(recipe, origin)))
                    .collect()
            })
            .unwrap_or_default();
        Some(Arc::new(OrchestratorAuthHealer {
            cli_path,
            magicutor: Arc::clone(&self.magicutor_client),
            secret_store,
            requirements,
            analytics_root: self.durable_artifact_workspace.base_root().to_path_buf(),
            principal: principal.to_owned(),
            workspace: workspace.to_owned(),
            // Keep room in the default 15s recipe budget for the HTTP retry.
            timeout: std::time::Duration::from_secs(5),
        }))
    }

    pub fn secret_store_for_scope(
        &self,
        principal: &str,
        workspace: &str,
    ) -> Option<Arc<crate::magician_v2::secrets::SecretStore>> {
        self.secret_store_resolver
            .resolve_for_scope(principal, workspace)
            .map_err(|error| {
                tracing::warn!(
                    principal,
                    workspace,
                    %error,
                    "[API_MINING] failed to resolve secret store for recipe replay"
                );
            })
            .ok()
    }

