    /// Configure tool authorization policy from the application config.
    ///
    /// Call this after construction when the full `MagicianConfig` is available.
    /// Sets the unlisted-tool policy ("ask" or "deny") that the
    /// executor factory propagates to each `ActionExecutors` instance.
    pub fn configure_tool_authorization(&self, config: &crate::config::ToolAuthorizationConfig) {
        let normalized_policy = match config.unlisted_policy.trim() {
            "deny" => "deny",
            "ask" | "" => "ask",
            "allow" => {
                tracing::warn!(
                    "[ORCHESTRATOR] Normalizing deprecated tool authorization policy 'allow' to 'ask'"
                );
                "ask"
            },
            other => {
                tracing::warn!(
                    policy = other,
                    "[ORCHESTRATOR] Unknown tool authorization policy; defaulting to 'ask'"
                );
                "ask"
            },
        };
        *self
            .tool_authorization_policy
            .write()
            .expect("tool_authorization_policy lock poisoned") = normalized_policy.to_string();
        *self
            .config_tool_allowlist
            .write()
            .expect("config_tool_allowlist lock poisoned") =
            config.allowlist.iter().cloned().collect();
        *self
            .config_tool_blocklist
            .write()
            .expect("config_tool_blocklist lock poisoned") =
            config.blocklist.iter().cloned().collect();
        let allowlist_len = self
            .config_tool_allowlist
            .read()
            .expect("config_tool_allowlist lock poisoned")
            .len();
        let blocklist_len = self
            .config_tool_blocklist
            .read()
            .expect("config_tool_blocklist lock poisoned")
            .len();
        tracing::info!(
            "[ORCHESTRATOR] Tool authorization: policy='{}', allowlist={} items, blocklist={} items",
            normalized_policy,
            allowlist_len,
            blocklist_len,
        );
    }

