    /// Configure API Mining router from the application config.
    ///
    /// Call this after construction when the full `MagicianConfig` is available.
    /// If `enable_replay` is true, creates and wires the API router for
    /// API-first routing of Navigate actions.
    pub fn configure_api_mining(&mut self, api_mining_config: &crate::config::ApiMiningConfig) {
        // Validate and clamp config values (logs warnings for invalid values)
        let api_mining_config = api_mining_config.clone().validated();

        // Store the validated config for use during post-execution mining trigger
        self.api_mining_config = api_mining_config.clone();
        self.api_mining_switch
            .set_process_enabled(api_mining_config.enabled);

        if api_mining_config.enable_trace_capture {
            self.trace_manager = Some(Arc::new(
                crate::magician_v2::api_mining::trace_manager::TraceManager::with_workspace_root(
                    self.runtime_config.storage_path(),
                ),
            ));
            tracing::info!("[API_MINING] Trace capture enabled under scoped V3 api_mining roots");
        }

        if api_mining_config.enable_replay || api_mining_config.enable_xhr_validation {
            self.api_router = Some(std::sync::Arc::new(std::sync::Mutex::new(
                crate::magician_v2::api_mining::router::ApiRouter::template(&api_mining_config),
            )));
            tracing::info!(
                "[API_MINING] API router template enabled; scoped routers will bind per execution (replay={}, xhr_validation={})",
                api_mining_config.enable_replay,
                api_mining_config.enable_xhr_validation
            );
        }

        self.secret_store_resolver
            .set_captured_max_origins(api_mining_config.max_vault_origins);
        if self
            .secret_store_resolver
            .runtime_capabilities()
            .status_for(crate::magician_v2::secrets::SecretSourceKind::Captured)
            .is_available()
        {
            tracing::info!(
                "[API_MINING] Captured auth store enabled under scoped V3 secrets roots"
            );
        }

        let cleanup_config = crate::magician_v2::api_mining::maintenance::CleanupConfig {
            trace_retention_days: api_mining_config.trace_retention_days as u64,
            max_trace_files_per_task: api_mining_config.max_traces_per_origin,
            ..Default::default()
        };
        spawn_api_mining_startup_cleanup(self.durable_artifact_workspace.clone(), cleanup_config);
    }

    /// Configure capability evolution behavior from the application config.
    ///
    /// This is default-off and must be explicitly enabled in config.
    /// Install per-program concurrency limits for the
    /// `interactive_process` primitive. Called once at boot from the
    /// magician runtime startup path. See
    /// `docs/plans/2026-05-13-developer-mode-workbench.md`.
    pub fn configure_interactive_process(
        &self,
        interactive_process_config: &crate::config::InteractiveProcessConfig,
    ) {
        crate::magician_v2::execution::interactive_process::set_program_concurrency_limits(
            interactive_process_config
                .max_concurrent_per_program
                .clone(),
        );
    }

    pub fn configure_capability_evolution(
        &mut self,
        capability_evolution_config: &crate::config::CapabilityEvolutionConfig,
    ) {
        self.capability_evolution_config = capability_evolution_config.clone().validated();
        let workspace_layout = self.durable_artifact_workspace.clone();
        let scopes = workspace_layout
            .list_scope_segments_sync()
            .unwrap_or_default();
        if self.capability_evolution_config.enabled {
            let mut restored = 0usize;
            let mut removed = 0usize;
            for (principal, workspace) in &scopes {
                let store =
                    crate::magician_v2::execution::CapabilityPackStore::with_workspace_layout(
                        &self.durable_artifact_workspace,
                        principal,
                        workspace,
                    );
                match store.try_load_runtime_pack_defs(
                    self.capability_evolution_config
                        .include_trial_packs_in_runtime,
                    self.capability_evolution_config.max_runtime_generated_packs,
                ) {
                    Ok(Some(packs)) => {
                        for pack in packs {
                            if matches!(
                                pack.implementation,
                                crate::magician_v2::execution::ImplementationType::Compiled { .. }
                            ) {
                                tracing::warn!(
                                    "[CAPABILITY_EVOLUTION] skipping persisted compiled pack '{}' in generated runtime loader for {}/{}",
                                    pack.name,
                                    principal,
                                    workspace
                                );
                                continue;
                            }
                            let _ = self.capability_registry.unregister(pack.name.as_str());
                            let provider =
                                crate::magician_v2::execution::PackCapabilityProvider::new(
                                    pack,
                                    self.capability_registry.clone(),
                                    Some(self.magicutor_client.clone()),
                                );
                            self.capability_registry.register(Arc::new(provider));
                            restored += 1;
                        }
                    },
                    Ok(None) => {
                        tracing::warn!(
                            "[CAPABILITY_EVOLUTION] skipped generated runtime pack restore for {}/{} because the catalog lock is busy",
                            principal,
                            workspace
                        );
                    },
                    Err(err) => {
                        tracing::warn!(
                            "[CAPABILITY_EVOLUTION] failed loading persisted generated packs for {}/{}: {}",
                            principal,
                            workspace,
                            err
                        );
                    },
                }
                match store.try_load_catalog() {
                    Ok(Some(catalog)) => {
                        for record in catalog.packs {
                            if matches!(
                                record.definition.implementation,
                                crate::magician_v2::execution::ImplementationType::Compiled { .. }
                            ) {
                                continue;
                            }
                            let should_register = match record.metadata.status {
                                crate::magician_v2::execution::CapabilityLifecycleStatus::Trial => {
                                    self.capability_evolution_config.include_trial_packs_in_runtime
                                },
                                crate::magician_v2::execution::CapabilityLifecycleStatus::Validated
                                | crate::magician_v2::execution::CapabilityLifecycleStatus::Trusted => true,
                                crate::magician_v2::execution::CapabilityLifecycleStatus::Deprecated => false,
                            };
                            if !should_register
                                && self
                                    .capability_registry
                                    .unregister(record.definition.name.as_str())
                                    .is_some()
                            {
                                removed += 1;
                            }
                        }
                    },
                    Ok(None) => {
                        tracing::warn!(
                            "[CAPABILITY_EVOLUTION] skipped disallowed-provider cleanup for {}/{} because the catalog lock is busy",
                            principal,
                            workspace
                        );
                    },
                    Err(err) => {
                        tracing::warn!(
                            "[CAPABILITY_EVOLUTION] failed loading catalog for disallowed-provider cleanup in {}/{}: {}",
                            principal,
                            workspace,
                            err
                        );
                    },
                }
            }
            tracing::info!(
                "[CAPABILITY_EVOLUTION] restored {} generated packs into runtime registry across {} scopes",
                restored,
                scopes.len()
            );
            if removed > 0 {
                tracing::info!(
                    "[CAPABILITY_EVOLUTION] removed {} disallowed generated providers during configure",
                    removed
                );
            }
        } else {
            let mut removed = 0usize;
            for (principal, workspace) in &scopes {
                let store =
                    crate::magician_v2::execution::CapabilityPackStore::with_workspace_layout(
                        &self.durable_artifact_workspace,
                        principal,
                        workspace,
                    );
                match store.try_load_catalog() {
                    Ok(Some(catalog)) => {
                        for record in catalog.packs {
                            if matches!(
                                record.definition.implementation,
                                crate::magician_v2::execution::ImplementationType::Compiled { .. }
                            ) {
                                continue;
                            }
                            if self
                                .capability_registry
                                .unregister(record.definition.name.as_str())
                                .is_some()
                            {
                                removed += 1;
                            }
                        }
                    },
                    Ok(None) => {
                        tracing::warn!(
                            "[CAPABILITY_EVOLUTION] skipped generated-provider disable cleanup for {}/{} because the catalog lock is busy",
                            principal,
                            workspace
                        );
                    },
                    Err(err) => {
                        tracing::warn!(
                            "[CAPABILITY_EVOLUTION] failed loading catalog for disable cleanup in {}/{}: {}",
                            principal,
                            workspace,
                            err
                        );
                    },
                }
            }
            if removed > 0 {
                tracing::info!(
                    "[CAPABILITY_EVOLUTION] disabled; removed {} generated providers from runtime registry",
                    removed
                );
            }
        }
        tracing::info!(
            "[CAPABILITY_EVOLUTION] configured: enabled={}, api_bridge={}, include_trial_runtime={}",
            self.capability_evolution_config.enabled,
            self.capability_evolution_config.enable_api_mined_bridge,
            self.capability_evolution_config.include_trial_packs_in_runtime
        );
    }

    /// Run the mining pipeline: read stored traces → cluster → create capabilities → register.
    ///
    /// Aggregates traces from ALL recent tasks (not just the current execution) to ensure
    /// low-frequency functional APIs (email view, form responses) that appear once per task
    /// can still cluster together and become capabilities.
    ///
    /// Called after trace flush when `enable_mining` is true.
    /// Failure-safe: all errors are logged as warnings and do not propagate.
    fn run_passive_validation_for_traces(
        &self,
        principal: &str,
        workspace: &str,
        base_path: &std::path::Path,
        traces: &[crate::magician_v2::api_mining::types::NetworkTraceEvent],
        origin_policy: &crate::magician_v2::api_mining::origin_policy::OriginPolicyStore,
        scoped_secret_store: Option<&Arc<crate::magician_v2::secrets::SecretStore>>,
    ) -> crate::magician_v2::api_mining::passive_validation::PassiveValidationSummary {
        if !self.api_mining_config.enable_xhr_validation || traces.is_empty() {
            return crate::magician_v2::api_mining::passive_validation::PassiveValidationSummary::default();
        }

        let metrics = crate::magician_v2::api_mining::passive_validation_metrics_for_scope(
            principal, workspace,
        );
        let base = base_path.to_path_buf();
        let config = self.api_mining_config.clone();
        let session_lookup =
            |origin: &str,
             concrete_url: &str|
             -> Option<crate::magician_v2::api_mining::types::SessionContext> {
                scoped_secret_store
                    .and_then(|store| {
                        store
                            .get_session(origin, concrete_url)
                            .or_else(|| store.get_session(origin, origin))
                    })
                    .map(|(session, _lease)| session)
            };

        let run_validation = async {
            crate::magician_v2::api_mining::passive_validation::run_passive_validation(
                &base,
                &config,
                traces,
                origin_policy,
                session_lookup,
                metrics.as_ref(),
            )
            .await
        };

        let summary = match tokio::runtime::Handle::try_current() {
            Ok(handle)
                if matches!(
                    handle.runtime_flavor(),
                    tokio::runtime::RuntimeFlavor::MultiThread
                ) =>
            {
                tokio::task::block_in_place(|| handle.block_on(run_validation))
            },
            Ok(_) => {
                tracing::warn!(
                    "[API_MINING] passive validation skipped — current-thread runtime detected; \
                     would deadlock if blocked. Switch to MultiThread tokio to enable."
                );
                crate::magician_v2::api_mining::passive_validation::PassiveValidationSummary::default()
            },
            Err(_) => {
                match tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                {
                    Ok(rt) => rt.block_on(run_validation),
                    Err(error) => {
                        tracing::warn!(
                            "[API_MINING] passive validation skipped — failed to build transient runtime: {}",
                            error
                        );
                        crate::magician_v2::api_mining::passive_validation::PassiveValidationSummary::default()
                    },
                }
            },
        };

        if summary.observed_xhr_fetch > 0
            || summary.validations_fired > 0
            || summary.errors > 0
            || summary.budget_exhausted > 0
        {
            tracing::info!(
                target: "magician::api_mining",
                observed_xhr_fetch = summary.observed_xhr_fetch,
                matched_capabilities = summary.matched_capabilities,
                validations_fired = summary.validations_fired,
                validations_passed = summary.validations_passed,
                validations_failed = summary.validations_failed,
                skipped_no_match = summary.skipped_no_match,
                skipped_policy = summary.skipped_policy,
                skipped_not_first_party = summary.skipped_not_first_party,
                errors = summary.errors,
                promoted_to_validated = summary.promoted_to_validated,
                promoted_to_trusted = summary.promoted_to_trusted,
                budget_exhausted = summary.budget_exhausted,
                "api_mining.passive_validation.completed"
            );
        }

        summary
    }

    fn run_mining_pipeline(
        &self,
        principal: &str,
        workspace: &str,
        execution_id: &str,
        base_path: &std::path::Path,
    ) {
        use crate::magician_v2::api_mining::miner::{ApiMiner, ClusteringConfig, GraphqlKnowledge};
        use crate::magician_v2::api_mining::origin_policy::OriginPolicyStore;
        use crate::magician_v2::api_mining::registry::CapabilityRegistry;
        use crate::magician_v2::api_mining::trace_storage::TraceStorage;

        // This work is usually detached from execution settlement. The switch may
        // have changed since the task queued the worker, so enforce it at the
        // worker's actual entry point before reading traces or opening stores.
        if !self.api_mining_effective(principal, workspace) {
            return;
        }

        let storage = TraceStorage::with_base_path(base_path);
        let origin_policy = OriginPolicyStore::open(base_path);

        // Cross-task aggregation: load traces from ALL recent tasks, not just the current one.
        // This is critical for functional APIs (email view, form responses) that appear 1-2x
        // per task but need to aggregate across tasks to pass the clustering threshold.
        let trace_files = match storage
            .list_all_recent_trace_files(self.api_mining_config.trace_retention_days)
        {
            Ok(files) => files,
            Err(e) => {
                tracing::debug!(
                    "[API_MINING] Failed to list trace files for cross-task aggregation: {}",
                    e
                );
                // Fallback: try current execution only
                match storage.list_trace_files(execution_id) {
                    Ok(files) => files,
                    Err(e2) => {
                        tracing::debug!(
                            "[API_MINING] No trace files for execution {}: {}",
                            execution_id,
                            e2
                        );
                        return;
                    },
                }
            },
        };

        if trace_files.is_empty() {
            tracing::debug!("[API_MINING] No trace files to mine (cross-task aggregation)");
            return;
        }

        // Aggregate all traces across tasks
        let mut all_traces = Vec::new();
        for file in &trace_files {
            match storage.read_traces(file) {
                Ok(traces) => all_traces.extend(traces),
                Err(e) => {
                    tracing::warn!("[API_MINING] Failed to read trace file {:?}: {}", file, e);
                },
            }
        }

        all_traces.retain(|trace| {
            let origin = crate::magician_v2::api_mining::router::extract_origin(&trace.url);
            !origin_policy.is_blocked(&origin)
        });

        if all_traces.is_empty() {
            return;
        }

        tracing::info!(
            "[API_MINING] Mining {} traces from {} files across all tasks (triggered by execution {})",
            all_traces.len(),
            trace_files.len(),
            execution_id
        );

        let mut registry = match CapabilityRegistry::with_base_path(base_path) {
            Ok(r) => r.with_max_capabilities(self.api_mining_config.max_capabilities_per_origin),
            Err(e) => {
                tracing::warn!("[API_MINING] Failed to create capability registry: {}", e);
                return;
            },
        };

        let scoped_secret_store = match self
            .secret_store_resolver
            .resolve_for_scope(principal, workspace)
        {
            Ok(store) => Some(store),
            Err(error) => {
                tracing::warn!(
                    "[API_MINING] Failed to resolve scoped secret store for {}/{} during mining: {}",
                    principal,
                    workspace,
                    error
                );
                None
            },
        };

        // Run clustering with previously learned GraphQL knowledge so APQ-only
        // traces can inherit query/mutation kind when the document is omitted.
        let mut noise =
            crate::magician_v2::api_mining::noise_filter::NoiseFilter::load_or_seed(base_path);
        noise
            .whitelist
            .extend(self.api_mining_config.noise_filter_whitelist.clone());
        noise
            .blacklist
            .extend(self.api_mining_config.noise_filter_blacklist.clone());
        let miner = ApiMiner::with_graphql_knowledge_and_noise(
            ClusteringConfig {
                noise_filter_whitelist: self.api_mining_config.noise_filter_whitelist.clone(),
                noise_filter_blacklist: self.api_mining_config.noise_filter_blacklist.clone(),
                // PL Task 7: propagate per-method takeover thresholds
                // so the miner can promote GET/HEAD capabilities at
                // sample 1 (second visit = replay).
                takeover_min_samples_per_method: self
                    .api_mining_config
                    .takeover_min_samples_per_method
                    .clone(),
                takeover_default_min_samples: self.api_mining_config.takeover_default_min_samples,
                ..ClusteringConfig::default()
            },
            GraphqlKnowledge::from_registry(&registry),
            noise,
        );
        let clusters = miner.cluster_traces(&all_traces);

        if clusters.is_empty() {
            let _ = self.run_passive_validation_for_traces(
                principal,
                workspace,
                base_path,
                &all_traces,
                &origin_policy,
                scoped_secret_store.as_ref(),
            );
            tracing::debug!(
                "[API_MINING] No clusters formed from traces for execution {}",
                execution_id
            );
            return;
        }

        tracing::info!(
            "[API_MINING] Found {} clusters from traces for execution {}",
            clusters.len(),
            execution_id
        );

        // Convert clusters to capabilities and register them
        let mut registered = 0usize;
        let mut mined_capabilities = Vec::new();

        for cluster in &clusters {
            let session = scoped_secret_store
                .as_ref()
                .and_then(|store| store.get_session(&cluster.origin, &cluster.origin))
                .map(|(session, _lease)| session);
            let capability =
                miner.cluster_to_capability_with_session_context(cluster, session.as_ref());

            // Register in global index (also saves to per-origin store internally)
            if let Err(e) = registry.register(&capability) {
                tracing::warn!(
                    "[API_MINING] Failed to register capability '{}': {}",
                    capability.name,
                    e
                );
                continue;
            }

            registered += 1;
            // Use canonicalized capability state from the registry (post-merge) so
            // promotion decisions reflect persisted maturity and dedup reconciliation.
            let canonical_for_promotion = registry
                .get_all_for_origin(&capability.origin)
                .ok()
                .and_then(|all| {
                    all.into_iter()
                        .filter(|stored| {
                            stored.method == capability.method
                                && stored.url_template == capability.url_template
                                && stored.body_fingerprint == capability.body_fingerprint
                        })
                        .max_by(|a, b| {
                            a.confidence
                                .cmp(&b.confidence)
                                .then(a.sample_count.cmp(&b.sample_count))
                                .then(a.replay_success_count.cmp(&b.replay_success_count))
                                .then(a.updated_at.cmp(&b.updated_at))
                        })
                })
                .unwrap_or(capability);
            mined_capabilities.push(canonical_for_promotion);
        }

        // PL/CE deferred-work cold-start fix: fire a small number of
        // safety-gated replays per Candidate capability so the
        // attempt counters cross the Validated threshold before the
        // bridge runs. Origin-policy gate (operator-opt-in) wraps the
        // SafetyFilter; defaults to dry-run so dashboards confirm
        // filter behavior before live HTTP fires.
        if self.api_mining_config.auto_replay_validation.enabled && !mined_capabilities.is_empty() {
            let cfg = self.api_mining_config.auto_replay_validation.clone();

            let candidates: Vec<crate::magician_v2::api_mining::capability::ApiCapability> =
                mined_capabilities
                    .iter()
                    .filter(|c| {
                        matches!(
                            c.confidence,
                            crate::magician_v2::api_mining::capability::ConfidenceLevel::Candidate
                        )
                    })
                    .filter(|c| origin_policy.allow_replay_for_origin(&c.origin))
                    .cloned()
                    .collect();

            if !candidates.is_empty() {
                let filter = crate::magician_v2::api_mining::auto_replay::SafetyFilter::from_lists(
                    cfg.allowed_methods.clone(),
                    cfg.url_denylist_substrings.clone(),
                    cfg.opt_in_post_origins.clone(),
                );

                let secret_store_ref = scoped_secret_store.as_ref();
                let session_lookup = |origin: &str| -> Option<
                    crate::magician_v2::api_mining::types::SessionContext,
                > {
                    secret_store_ref
                        .and_then(|store| store.get_session(origin, origin))
                        .map(|(session, _lease)| session)
                };

                let runs = cfg.runs_per_capability;
                let budget = cfg.max_per_pipeline;
                let dry = cfg.dry_run;
                let base = base_path.to_path_buf();
                let candidate_count = candidates.len();

                let run_replay = async {
                    crate::magician_v2::api_mining::auto_replay::run_pipeline_auto_replay(
                        &base,
                        &candidates,
                        session_lookup,
                        &filter,
                        runs,
                        budget,
                        dry,
                    )
                    .await
                };

                // `block_in_place` panics on a current-thread runtime,
                // so we sniff the flavor before using it. Magician's
                // production main is multi-thread (actix-web default),
                // but tests / future entry points might not be.
                let summary = match tokio::runtime::Handle::try_current() {
                    Ok(handle)
                        if matches!(
                            handle.runtime_flavor(),
                            tokio::runtime::RuntimeFlavor::MultiThread
                        ) =>
                    {
                        tokio::task::block_in_place(|| handle.block_on(run_replay))
                    },
                    Ok(_) => {
                        // Current-thread runtime — `block_in_place`
                        // would panic and a fresh runtime can't be
                        // nested. Skip rather than risk deadlock.
                        tracing::warn!(
                            "[API_MINING] auto-replay skipped — current-thread runtime detected; \
                             would deadlock if blocked. Switch to MultiThread tokio to enable."
                        );
                        crate::magician_v2::api_mining::auto_replay::PipelineAutoReplaySummary {
                            dry_run: dry,
                            ..Default::default()
                        }
                    },
                    Err(_) => {
                        match tokio::runtime::Builder::new_current_thread()
                            .enable_all()
                            .build()
                        {
                            Ok(rt) => rt.block_on(run_replay),
                            Err(error) => {
                                tracing::warn!(
                                    "[API_MINING] auto-replay skipped — failed to build transient runtime: {}",
                                    error
                                );
                                crate::magician_v2::api_mining::auto_replay::PipelineAutoReplaySummary {
                                    dry_run: dry,
                                    ..Default::default()
                                }
                            },
                        }
                    },
                };

                tracing::info!(
                    target: "magician::api_mining",
                    candidates = candidate_count,
                    capabilities_touched = summary.capabilities_touched,
                    attempts = summary.attempts,
                    successes = summary.successes,
                    failures = summary.failures,
                    auth_failures = summary.auth_failures,
                    skipped = summary.skipped,
                    budget_exhausted = summary.budget_exhausted,
                    dry_run = summary.dry_run,
                    "api_mining.auto_replay.completed"
                );

                if let Some(error) = summary.error.as_ref() {
                    tracing::warn!(
                        target: "magician::api_mining",
                        error = %error,
                        "api_mining.auto_replay.failed"
                    );
                }

                // Refresh mined_capabilities from registry so the
                // bridge sees every counter update auto-replay just
                // wrote — promotions on success AND demotions on
                // consecutive failures. Only the dry-run path is safe
                // to skip (no disk writes happened).
                let touched_disk = !summary.dry_run
                    && (summary.successes > 0 || summary.failures > 0 || summary.auth_failures > 0);
                if touched_disk {
                    for cap in mined_capabilities.iter_mut() {
                        if let Ok(refreshed) = registry.get_capability(&cap.origin, &cap.id) {
                            *cap = refreshed;
                        }
                    }
                }
            }
        }

        let passive_summary = self.run_passive_validation_for_traces(
            principal,
            workspace,
            base_path,
            &all_traces,
            &origin_policy,
            scoped_secret_store.as_ref(),
        );
        if !passive_summary.touched_capabilities.is_empty() {
            let _ = registry.rebuild();
            for cap in mined_capabilities.iter_mut() {
                if let Ok(refreshed) = registry.get_capability(&cap.origin, &cap.id) {
                    *cap = refreshed;
                }
            }
        }

        if registered > 0 {
            tracing::info!(
                "[API_MINING] Registered {}/{} capabilities from mining for execution {}",
                registered,
                clusters.len(),
                execution_id
            );

            // Capability evolution bridge: promote mined capabilities into generated
            // capability packs and register runtime providers (default-off).
            if self.capability_evolution_config.enabled
                && self.capability_evolution_config.enable_api_mined_bridge
            {
                let _capability_evolution_guard = self
                    .capability_evolution_sync
                    .lock()
                    .expect("capability_evolution_sync lock poisoned");
                let thresholds = self.capability_eval_thresholds();
                let bridge =
                    crate::magician_v2::execution::CapabilityPromotionBridge::with_workspace_layout(
                        &self.durable_artifact_workspace,
                        principal,
                        workspace,
                        thresholds,
                    );

                let bridge_started_at = std::time::Instant::now();
                match bridge.promote_api_capabilities(
                    &mined_capabilities,
                    self.capability_evolution_config
                        .include_trial_packs_in_runtime,
                    self.capability_evolution_config.max_runtime_generated_packs,
                ) {
                    Ok(report) => {
                        // CE Phase 2: structured instrumentation for
                        // the bridge invocation. `examined` covers
                        // every input capability; `promoted`/
                        // `deprecated` are the bridge-reported
                        // transitions; `bridge_duration_ms` lets us
                        // catch latency regressions if the bridge ever
                        // grows expensive work.
                        let bridge_duration_ms = bridge_started_at.elapsed().as_millis() as u64;
                        tracing::info!(
                            target: "magician::capability_evolution",
                            principal = %principal,
                            workspace = %workspace,
                            execution_id = %execution_id,
                            examined = report.examined,
                            promoted = report.promoted,
                            deprecated = report.deprecated,
                            runtime_loaded = report.runtime_loaded,
                            bridge_duration_ms,
                            "capability_evolution.bridge.completed"
                        );
                        let mut runtime_registered = 0usize;
                        let mut runtime_unregistered = 0usize;
                        let runtime_target_defs = report
                            .runtime_pack_defs
                            .iter()
                            .filter(|def| {
                                !matches!(
                                    def.implementation,
                                    crate::magician_v2::execution::ImplementationType::Compiled { .. }
                                )
                            })
                            .map(|def| (def.name.clone(), def.clone()))
                            .collect::<HashMap<_, _>>();

                        // Reconcile runtime providers against the authoritative runtime set
                        // emitted by the promotion bridge. This avoids stale providers under
                        // cap pressure and refreshes changed definitions even when lifecycle
                        // status remains unchanged.
                        match bridge.store().load_catalog() {
                            Ok(catalog) => {
                                let mut catalog_generated_names = HashSet::new();
                                for record in catalog.packs {
                                    if matches!(
                                        record.definition.implementation,
                                        crate::magician_v2::execution::ImplementationType::Compiled { .. }
                                    ) {
                                        continue;
                                    }
                                    let pack_name = record.definition.name;
                                    catalog_generated_names.insert(pack_name.clone());

                                    if let Some(runtime_def) = runtime_target_defs.get(&pack_name) {
                                        let _ =
                                            self.capability_registry.unregister(pack_name.as_str());
                                        let provider = crate::magician_v2::execution::PackCapabilityProvider::new(
                                            runtime_def.clone(),
                                            self.capability_registry.clone(),
                                            Some(self.magicutor_client.clone()),
                                        );
                                        self.capability_registry.register(Arc::new(provider));
                                        runtime_registered += 1;
                                    } else if self
                                        .capability_registry
                                        .unregister(pack_name.as_str())
                                        .is_some()
                                    {
                                        runtime_unregistered += 1;
                                    }
                                }

                                for (pack_name, runtime_def) in &runtime_target_defs {
                                    if catalog_generated_names.contains(pack_name) {
                                        continue;
                                    }
                                    let _ = self.capability_registry.unregister(pack_name.as_str());
                                    let provider =
                                        crate::magician_v2::execution::PackCapabilityProvider::new(
                                            runtime_def.clone(),
                                            self.capability_registry.clone(),
                                            Some(self.magicutor_client.clone()),
                                        );
                                    self.capability_registry.register(Arc::new(provider));
                                    runtime_registered += 1;
                                }
                            },
                            Err(err) => {
                                tracing::warn!(
                                    "[CAPABILITY_EVOLUTION] failed loading catalog for runtime reconciliation (falling back to outcome-only sync): {}",
                                    err
                                );
                                let mut seen = HashSet::new();
                                for outcome in &report.outcomes {
                                    if !seen.insert(outcome.definition.name.clone()) {
                                        continue;
                                    }
                                    let pack_name = outcome.definition.name.as_str();
                                    if let Some(runtime_def) = runtime_target_defs.get(pack_name) {
                                        let _ = self.capability_registry.unregister(pack_name);
                                        let provider = crate::magician_v2::execution::PackCapabilityProvider::new(
                                            runtime_def.clone(),
                                            self.capability_registry.clone(),
                                            Some(self.magicutor_client.clone()),
                                        );
                                        self.capability_registry.register(Arc::new(provider));
                                        runtime_registered += 1;
                                    } else if self
                                        .capability_registry
                                        .unregister(pack_name)
                                        .is_some()
                                    {
                                        runtime_unregistered += 1;
                                    }
                                }
                            },
                        }

                        tracing::info!(
                            "[CAPABILITY_EVOLUTION] bridge report for execution {}: examined={}, promoted={}, deprecated={}, runtime_registered={}, runtime_unregistered={}, runtime_loadable={}",
                            execution_id,
                            report.examined,
                            report.promoted,
                            report.deprecated,
                            runtime_registered,
                            runtime_unregistered,
                            report.runtime_loaded
                        );
                        if let Some(broadcaster) = &self.event_broadcaster {
                            broadcaster.observability_alert(
                                execution_id,
                                "capability_evolution.promotion",
                                serde_json::json!({
                                    "examined": report.examined,
                                    "promoted": report.promoted,
                                    "deprecated": report.deprecated,
                                    "runtime_registered": runtime_registered,
                                    "runtime_unregistered": runtime_unregistered,
                                    "runtime_loadable": report.runtime_loaded,
                                }),
                            );
                        }
                    },
                    Err(err) => {
                        tracing::warn!(
                            "[CAPABILITY_EVOLUTION] bridge failed for execution {}: {}",
                            execution_id,
                            err
                        );
                    },
                }
            }
        }
    }

    fn persist_learned_action_bindings(
        &self,
        principal: &str,
        workspace: &str,
        base_path: &std::path::Path,
        action_events: &[crate::magician_v2::api_mining::correlator::ActionEvent],
        correlations: &[crate::magician_v2::api_mining::correlator::CorrelatedRequest],
    ) {
        use crate::magician_v2::api_mining::action_binding::{
            action_context_from_event, capability_requires_runtime_params, infer_action_binding,
        };
        use crate::magician_v2::api_mining::miner::{
            compute_body_fingerprint_standalone, detect_graphql_request_info_standalone,
        };
        use crate::magician_v2::api_mining::registry::CapabilityRegistry;

        if !self.api_mining_effective(principal, workspace) {
            return;
        }

        let selected = self.select_action_binding_candidates(action_events, correlations);
        if selected.is_empty() {
            return;
        }

        let mut registry = match CapabilityRegistry::with_base_path(base_path) {
            Ok(registry) => registry,
            Err(error) => {
                tracing::warn!(
                    "[API_MINING] Failed to load registry for action binding persistence: {}",
                    error
                );
                return;
            },
        };

        let mut persisted = 0usize;
        let mut persisted_action_ids = std::collections::HashSet::new();
        for (action, correlation) in selected {
            if persisted_action_ids.contains(&action.action_id) {
                continue;
            }
            if action_context_from_event(action).is_none() {
                continue;
            }

            let method = correlation.trace.method.to_uppercase();
            let content_type = correlation
                .trace
                .request_headers
                .iter()
                .find(|(key, _)| key.eq_ignore_ascii_case("content-type"))
                .map(|(_, value)| value.as_str());
            let graphql_info = detect_graphql_request_info_standalone(
                correlation.trace.request_body.as_deref(),
                content_type,
            );
            let body_fingerprint = if !matches!(method.as_str(), "GET" | "HEAD") {
                compute_body_fingerprint_standalone(
                    correlation.trace.request_body.as_deref(),
                    content_type,
                    graphql_info.is_some(),
                )
            } else {
                None
            };

            let summary = match registry.find_by_url_with_request_context(
                &method,
                &correlation.trace.url,
                body_fingerprint.as_deref(),
                graphql_info
                    .as_ref()
                    .map(|info| info.operation_name.as_str()),
                graphql_info
                    .as_ref()
                    .and_then(|info| match info.operation_kind {
                        crate::magician_v2::api_mining::capability::GraphqlOperationKind::Unknown => {
                            None
                        },
                        kind => Some(kind),
                    }),
            ) {
                Some(summary) => summary,
                None => continue,
            };

            let origin = match url::Url::parse(&correlation.trace.url) {
                Ok(parsed) => parsed.origin().unicode_serialization(),
                Err(_) => continue,
            };
            let mut capability = match registry.get_capability(&origin, &summary.id) {
                Ok(capability) => capability,
                Err(error) => {
                    tracing::debug!(
                        "[API_MINING] Failed to load capability '{}' for action binding: {}",
                        summary.id,
                        error
                    );
                    continue;
                },
            };

            let Some(binding) = infer_action_binding(action, &capability, &correlation.trace)
            else {
                continue;
            };

            if binding.param_bindings.is_empty()
                && binding.default_params.is_empty()
                && (!action.action_params.is_empty()
                    || capability_requires_runtime_params(&capability))
            {
                tracing::debug!(
                    "[API_MINING] Skipping action binding for {} because capability '{}' still has unmapped runtime params",
                    action.action_type,
                    capability.name
                );
                continue;
            }

            capability.record_action_binding(binding);
            if let Err(error) = registry.register(&capability) {
                tracing::warn!(
                    "[API_MINING] Failed to persist action binding for capability '{}': {}",
                    capability.name,
                    error
                );
                continue;
            }

            persisted += 1;
            persisted_action_ids.insert(action.action_id.clone());
        }

        if persisted > 0 {
            tracing::info!(
                "[API_MINING] Persisted {} learned action binding(s)",
                persisted
            );
        }
    }

    fn select_action_binding_candidates<'a>(
        &self,
        action_events: &'a [crate::magician_v2::api_mining::correlator::ActionEvent],
        correlations: &'a [crate::magician_v2::api_mining::correlator::CorrelatedRequest],
    ) -> Vec<(
        &'a crate::magician_v2::api_mining::correlator::ActionEvent,
        &'a crate::magician_v2::api_mining::correlator::CorrelatedRequest,
    )> {
        use crate::magician_v2::api_mining::action_binding::action_context_from_event;
        use crate::magician_v2::api_mining::correlator::CorrelatedRequest;
        use std::collections::HashMap;

        let action_lookup = action_events
            .iter()
            .map(|action| (action.action_id.as_str(), action))
            .collect::<HashMap<_, _>>();
        let mut grouped: HashMap<&str, Vec<&CorrelatedRequest>> = HashMap::new();

        for correlation in correlations {
            grouped
                .entry(correlation.action_id.as_str())
                .or_default()
                .push(correlation);
        }

        let mut selected = Vec::new();
        for (action_id, candidates) in grouped {
            let Some(action) = action_lookup.get(action_id).copied() else {
                continue;
            };
            if action_context_from_event(action).is_none() {
                continue;
            }
            for chosen in select_ranked_action_binding_candidates(action, &candidates) {
                selected.push((action, chosen));
            }
        }

        selected
    }

