    /// Install the LLM dispatch-queue cancel bridge (set once at boot, after
    /// the queue is built). Enables `cancel_execution` to tombstone an
    /// execution's queued LLM jobs and abort its in-flight provider call.
    /// Takes `&self` (interior `OnceLock`) because the orchestrator is already
    /// `Arc`-shared by the time the queue exists.
    pub fn set_cancel_bridge(&self, bridge: Arc<crate::magician_v2::dispatch_glue::CancelBridge>) {
        if self.cancel_bridge.set(bridge).is_err() {
            warn!("[MAGICIAN-V2-ORCHESTRATOR] cancel bridge already set; ignoring duplicate");
        }
    }

    /// Set operation LLM router for AtomicComposition strategy
    pub fn with_operation_llm_router(mut self, service: Arc<OperationLlmRouter>) -> Self {
        self.operation_llm_router = Some(service.clone());

        let rewrite_model: Arc<dyn RewriteModel> = Arc::new(MultiLlmRewriteModel::new(
            service.clone(),
            LLMOperation::QuestionRewriting,
        ));
        let curation_model: Arc<dyn RewriteModel> = Arc::new(MultiLlmRewriteModel::new(
            service.clone(),
            LLMOperation::QuestionCuration,
        ));

        let rewriter = Arc::new(QuestionRewriter::with_curation_model(
            rewrite_model,
            curation_model,
            self.prompt_manager.clone(),
            self.rewriter_config.clone(),
        ));

        self.elicitation_service.set_rewriter(Arc::clone(&rewriter));
        info!("[MAGICIAN-V2-ORCHESTRATOR] ✅ Question rewriter configured to use operation LLM router");
        self.rewriter = rewriter;

        let extraction_adapter = Arc::new(MultiLlmExtractionAdapter::new(service));
        let mut extractor = SlotExtractor::new(
            extraction_adapter,
            self.prompt_manager.clone(),
            ExtractionConfig::default(),
        );
        if let Some(broadcaster) = self.event_broadcaster.as_ref() {
            extractor = extractor.with_event_broadcaster(Arc::clone(broadcaster));
        }
        let extractor = Arc::new(extractor);
        self.elicitation_service
            .set_extractor(Arc::clone(&extractor));
        info!(
            "[MAGICIAN-V2-ORCHESTRATOR] ✅ Slot extractor configured to use operation LLM router"
        );
        self
    }

