    async fn dispatch_curated_question_batch(
        &self,
        ask_api: &AskLoopApi,
        workflow_id: &str,
        questions: &[ClarifierQuestion],
        source: &str,
        iteration: Option<usize>,
        complexity: TaskComplexity,
        principal: Option<&str>,
        workspace: Option<&str>,
        task_id: Option<&str>,
    ) -> Result<(String, usize), String> {
        if questions.is_empty() {
            return Err("no questions provided for batch dispatch".to_string());
        }

        let batch_id = format!("batch-{}", Uuid::new_v4());
        let batch_total = questions.len();

        let mut questions_with_batch = Vec::with_capacity(batch_total);
        for question in questions.iter() {
            let mut enriched = question.clone();
            enriched.batch_id = Some(batch_id.clone());
            enriched.batch_total = Some(batch_total);
            questions_with_batch.push(enriched);
        }

        let question_ids: Vec<String> = questions_with_batch.iter().map(|q| q.id.clone()).collect();

        let batch_tracker = ask_api.batch_tracker();
        batch_tracker.clear_workflow_batches(workflow_id);
        let metadata = BatchMetadata {
            source: source.to_string(),
            iteration,
            avg_priority: Some(0.7),
        };
        batch_tracker.register_batch(
            batch_id.clone(),
            workflow_id.to_string(),
            question_ids.clone(),
            Some(metadata),
        );

        if questions_with_batch.is_empty() {
            return Err("batch preparation produced no questions".to_string());
        }

        ask_api
            .enqueue_batch_questions_with_scope(
                workflow_id,
                questions_with_batch,
                complexity,
                principal,
                workspace,
                task_id,
            )
            .await
            .map_err(|err| err.to_string())?;
        Ok((batch_id, batch_total))
    }

    async fn mark_session_collecting(&self, workflow_id: &str) -> Result<(), String> {
        if let Some(api) = &self.ask_loop_api {
            let manager = api.session_manager();
            let mut history_entries = Vec::new();

            match manager.load(workflow_id).await {
                Ok(Some(session)) => {
                    let slot_updates = session.slot_updates.clone();
                    for question in session
                        .pending_questions
                        .iter()
                        .filter(|q| q.status == SessionQuestionStatus::Answered)
                    {
                        let updates = slot_updates
                            .iter()
                            .filter(|update| update.question_id == question.id)
                            .map(|update| ClarificationHistorySlotUpdate {
                                slot_id: update.slot.id.clone(),
                                slot_type: update.slot.slot_type.clone(),
                                value: update.slot.value.clone(),
                                confidence: update.slot.confidence,
                                received_at: update.received_at.timestamp_millis(),
                            })
                            .collect::<Vec<_>>();

                        history_entries.push(ClarificationHistoryEntry {
                            question_id: question.id.clone(),
                            question_text: question.question_text.clone(),
                            source_slot_id: question.source_slot_id.clone(),
                            stage: question.stage,
                            answered_at: question.answered_at.map(|ts| ts.timestamp_millis()),
                            slot_updates: updates,
                        });
                    }
                },
                Ok(None) => {
                    debug!(
                        "[MAGICIAN-V2-ORCHESTRATOR] No clarification session found while resetting {}",
                        workflow_id
                    );
                },
                Err(err) => {
                    return Err(format!(
                        "Failed to load clarification session for {workflow_id}: {err}"
                    ));
                },
            }

            manager
                .mark_state(workflow_id, ClarificationSessionState::CollectingAnswers)
                .await
                .map_err(|err| {
                    format!("Failed to reset clarification session for {workflow_id}: {err}")
                })?;

            if !history_entries.is_empty() {
                crate::magician_v2::storage::V2ConversationStore::append_clarification_history(
                    &*self.conversation_store,
                    workflow_id,
                    history_entries,
                )
                .await
                .map_err(|err| {
                    format!("Failed to append clarification history for {workflow_id}: {err}")
                })?;
            }
        }
        Ok(())
    }

    async fn ask_loop_requires_user(&self, workflow_id: &str) -> Result<bool, V2StorageError> {
        let api = match &self.ask_loop_api {
            Some(api) => api,
            None => return Ok(false),
        };

        match api.enforce_guardrails(workflow_id).await {
            Ok(Some(breach)) => {
                info!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Guardrail {:?} triggered for workflow {}",
                    breach, workflow_id
                );
                return Ok(false);
            },
            Ok(None) => {},
            Err(err) => {
                return Err(V2StorageError::Storage(format!(
                    "guardrail enforcement failed for {workflow_id}: {err}"
                )));
            },
        }

        let manager = api.session_manager();
        match manager.load(workflow_id).await {
            Ok(Some(session)) => Ok(
                session.state == ClarificationSessionState::CollectingAnswers
                    && session.pending_questions.iter().any(|q| {
                        matches!(
                            q.status,
                            SessionQuestionStatus::Queued | SessionQuestionStatus::WaitingOnUser
                        )
                    }),
            ),
            Ok(None) => Ok(false),
            Err(err) => Err(V2StorageError::Storage(format!(
                "failed to load clarification session for {workflow_id}: {err}"
            ))),
        }
    }

    async fn load_pending_recommended_questions(
        &self,
        workflow_id: &str,
    ) -> Vec<RecommendedQuestion> {
        let api = match &self.ask_loop_api {
            Some(api) => api,
            None => return Vec::new(),
        };

        match api
            .get_pending_clarifications_for_execution(workflow_id)
            .await
        {
            Ok(pending) => pending
                .into_iter()
                .map(|clarification| {
                    let clarifier_question: ClarifierQuestion = clarification;
                    RecommendedQuestion::from(&clarifier_question)
                })
                .collect(),
            Err(err) => {
                warn!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Failed to load pending clarifications for {}: {}",
                    workflow_id, err
                );
                Vec::new()
            },
        }
    }

