    /// Set event broadcaster for real-time progress updates
    pub fn with_event_broadcaster(
        mut self,
        broadcaster: Arc<crate::magician_v2::realtime_events::RuntimeTransportBroadcaster>,
    ) -> Self {
        if let Some(api) = &self.ask_loop_api {
            api.attach_event_broadcaster(broadcaster.clone());
        }

        // Also attach to query_analyzer
        // Note: query_analyzer is Arc so we need to reconstruct it with broadcaster
        let new_analyzer = Arc::new(
            UnifiedQueryAnalyzer::new(
                self.llm_service.clone(),
                self.tool_catalog.clone(),
                self.prompt_manager.clone(),
            )
            .with_event_broadcaster(broadcaster.clone()),
        );
        self.query_analyzer = new_analyzer;

        // Also attach to slot_extractor in elicitation_service
        // Get the current extractor to retrieve its LLM service and config
        let current_extractor = {
            let guard = self
                .elicitation_service
                .extractor()
                .read()
                .expect("extractor lock poisoned");
            Arc::clone(&*guard)
        };

        // Reconstruct extractor with broadcaster
        let new_extractor = Arc::new(
            crate::magician_v2::slot_graph::extraction::SlotExtractor::new(
                current_extractor.llm_service().clone(),
                self.prompt_manager.clone(),
                current_extractor.config().clone(),
            )
            .with_event_broadcaster(broadcaster.clone()),
        );
        self.elicitation_service.set_extractor(new_extractor);

        // Also attach to task_decomposer
        let new_decomposer = Arc::new(
            crate::magician_v2::strategy::decomposer::TaskDecomposer::new(
                self.llm_service.clone(),
                self.query_analyzer.clone(),
                self.prompt_manager.clone(),
                self.tool_catalog.clone(),
                None, // Use default limits
            )
            .with_event_broadcaster(broadcaster.clone()),
        );
        self.task_decomposer = new_decomposer;

        self.event_broadcaster = Some(broadcaster);
        self
    }

