    /// Retain a parent whose durable ChildCompleted publication and immediate
    /// inline reconciliation both failed. The registry is process-local by
    /// design: durable wake admission retires it, while V3 startup recovery
    /// reconstructs task-backed stateless authority after process death.
    pub fn retain_parent_reconciliation_retry(&self, parent_execution_id: &str) {
        self.retain_parent_reconciliation_retry_target(ParentReconciliationRetryTarget::Parent(
            parent_execution_id.to_owned(),
        ));
    }

    /// Retain a terminal child when even loading its parent link failed. The
    /// coordinator re-reads the canonical Runtime row instead of guessing a
    /// parent from stale process-local lineage.
    pub fn retain_terminal_child_parent_reconciliation_retry(&self, child_execution_id: &str) {
        self.retain_parent_reconciliation_retry_target(
            ParentReconciliationRetryTarget::TerminalChild(child_execution_id.to_owned()),
        );
    }

    fn retain_parent_reconciliation_retry_target(&self, target: ParentReconciliationRetryTarget) {
        let key = target.key();
        self.parent_reconciliation_retry_queue
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner)
            .entry(key)
            .or_insert_with(|| ParentReconciliationRetryCandidate {
                target,
                retry_attempt: 0,
                next_attempt_at_ms: Utc::now().timestamp_millis(),
            });
        self.parent_reconciliation_retry_wake.notify_one();
        self.ensure_parent_reconciliation_retry_coordinator();
    }

    fn ensure_parent_reconciliation_retry_coordinator(&self) {
        if self
            .parent_reconciliation_retry_coordinator_active
            .swap(true, Ordering::AcqRel)
        {
            return;
        }
        let Some(orchestrator) = self.weak_self.upgrade() else {
            self.parent_reconciliation_retry_coordinator_active
                .store(false, Ordering::Release);
            warn!("parent reconciliation retry retained before orchestrator initialization");
            return;
        };
        crate::magician_v2::execution::runtime_boundary::spawn_execution_job(move || async move {
            orchestrator
                .run_parent_reconciliation_retry_coordinator()
                .await;
        });
    }

    async fn run_parent_reconciliation_retry_coordinator(self: &Arc<Self>) {
        loop {
            let now_ms = Utc::now().timestamp_millis();
            let (candidate, next_due_ms) = {
                let queue = self
                    .parent_reconciliation_retry_queue
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                let due = queue
                    .iter()
                    .filter(|(_, candidate)| candidate.next_attempt_at_ms <= now_ms)
                    .min_by_key(|(_, candidate)| candidate.next_attempt_at_ms)
                    .map(|(key, candidate)| (key.clone(), candidate.clone()));
                let next_due = queue
                    .values()
                    .map(|candidate| candidate.next_attempt_at_ms)
                    .min();
                (due, next_due)
            };

            let Some((key, mut candidate)) = candidate else {
                let Some(next_due_ms) = next_due_ms else {
                    self.parent_reconciliation_retry_coordinator_active
                        .store(false, Ordering::Release);
                    if self
                        .parent_reconciliation_retry_queue
                        .lock()
                        .unwrap_or_else(std::sync::PoisonError::into_inner)
                        .is_empty()
                        || self
                            .parent_reconciliation_retry_coordinator_active
                            .swap(true, Ordering::AcqRel)
                    {
                        return;
                    }
                    continue;
                };
                let delay_ms = next_due_ms.saturating_sub(now_ms).max(1) as u64;
                tokio::select! {
                    _ = tokio::time::sleep(Duration::from_millis(delay_ms)) => {},
                    _ = self.parent_reconciliation_retry_wake.notified() => {},
                }
                continue;
            };

            if self
                .run_parent_reconciliation_retry_candidate(&candidate.target)
                .await
            {
                self.parent_reconciliation_retry_queue
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner)
                    .remove(&key);
                continue;
            }

            candidate.retry_attempt = candidate.retry_attempt.saturating_add(1);
            let delay = match candidate.retry_attempt {
                1 => Duration::from_secs(1),
                2 => Duration::from_secs(5),
                3 => Duration::from_secs(15),
                _ => Duration::from_secs(30),
            };
            candidate.next_attempt_at_ms = Utc::now()
                .timestamp_millis()
                .saturating_add(delay.as_millis().min(i64::MAX as u128) as i64);
            self.parent_reconciliation_retry_queue
                .lock()
                .unwrap_or_else(std::sync::PoisonError::into_inner)
                .insert(key, candidate);
        }
    }

    async fn run_parent_reconciliation_retry_candidate(
        &self,
        target: &ParentReconciliationRetryTarget,
    ) -> bool {
        let parent_execution_id = match target {
            ParentReconciliationRetryTarget::Parent(parent_execution_id) => {
                parent_execution_id.clone()
            },
            ParentReconciliationRetryTarget::TerminalChild(child_execution_id) => {
                match self
                    .conversation_store
                    .get_execution(child_execution_id)
                    .await
                {
                    Ok(child) => match child.parent_execution_id {
                        Some(parent_execution_id) => parent_execution_id,
                        None => return true,
                    },
                    Err(crate::magician_v2::storage::V2StorageError::ExecutionNotFound(_)) => {
                        // This retry target is created only after the child's
                        // terminal transition. Typed absence therefore means a
                        // stale/deleted child, not a pre-publication race.
                        return true;
                    },
                    Err(error) => {
                        warn!(
                            child_execution_id,
                            %error,
                            "terminal-child parent-link retry remains pending"
                        );
                        return false;
                    },
                }
            },
        };

        if let Some(queue) = self.wake_up_queue() {
            match queue
                .schedule_child_completed_wake(&parent_execution_id, Utc::now())
                .await
            {
                Ok(()) => return true,
                Err(error) => warn!(
                    parent_execution_id,
                    %error,
                    "parent reconciliation retry could not enter durable wake queue"
                ),
            }
        }

        match Box::pin(self.reconcile_waiting_children_and_continue(&parent_execution_id)).await {
            Ok(_) => true,
            Err(error) => {
                warn!(
                    parent_execution_id,
                    %error,
                    "parent reconciliation retry remains pending after inline failure"
                );
                false
            },
        }
    }

    /// Reconstruct the process-local parent retry owner for taskless PlanGraph
    /// parents from durable Runtime lineage plus the exact stateless delegation
    /// checkpoint. The surrounding startup scan is already fully paginated and
    /// snapshots ids before mutation, so every matching row is visited once.
    async fn retain_taskless_stateless_waiting_parent_recovery(
        &self,
        parent: &ExecutionRun,
    ) -> Result<bool, String> {
        if parent.task_id.is_some()
            || parent.waiting_state != WaitingState::WaitingChildren
            || crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::from_env()
                != crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::Stateless
        {
            return Ok(false);
        }
        self.require_stateless_scope_activated(&parent.principal, &parent.workspace)
            .await?;
        let Some(checkpoint) = self
            .internal_delegation_checkpoint_scoped(&parent.id, &parent.principal, &parent.workspace)
            .await?
        else {
            return Ok(false);
        };
        if checkpoint.execution_id != parent.id
            || checkpoint.principal.as_deref() != Some(parent.principal.as_str())
            || checkpoint.workspace.as_deref() != Some(parent.workspace.as_str())
            || checkpoint.task_id.is_some()
            || checkpoint.stateless_parked_segment.is_none()
            || checkpoint.stateless_resume_segment.is_none()
        {
            return Err(format!(
                "taskless waiting-child stateless checkpoint identity mismatch:{}",
                parent.id
            ));
        }

        for child_execution_id in &parent.active_delegation_group {
            let child = match self
                .conversation_store
                .get_execution(child_execution_id)
                .await
            {
                Ok(child) => child,
                Err(error) => {
                    warn!(
                        parent_execution_id = %parent.id,
                        child_execution_id,
                        %error,
                        "taskless stateless parent recovery retained after child-lineage read failure"
                    );
                    self.retain_parent_reconciliation_retry(&parent.id);
                    return Ok(true);
                },
            };
            if child.id != *child_execution_id
                || child.parent_execution_id.as_deref() != Some(parent.id.as_str())
                || child.principal != parent.principal
                || child.workspace != parent.workspace
            {
                return Err(format!(
                    "taskless waiting-child lineage mismatch:{}:{child_execution_id}",
                    parent.id
                ));
            }
            if !child.waiting_state.is_terminal() {
                // This child still owns the future producer. Once it becomes
                // terminal, the ordinary notification path either publishes a
                // durable wake or enters this same retained coordinator.
                return Ok(false);
            }
        }

        self.retain_parent_reconciliation_retry(&parent.id);
        Ok(true)
    }

    /// Build `ActionExecutors` with the same factory configuration used by
    /// direct/agent execution paths.
    pub fn build_action_executors(
        &self,
    ) -> crate::magician_v2::execution::agentic::ActionExecutors {
        self.build_action_executors_with_router_override(None)
    }

    /// Build `ActionExecutors` using an optional scoped operation router.
    ///
    /// When `operation_llm_router_override` is `Some`, it is used instead of the
    /// orchestrator's default router for this executor instance.
    pub fn build_action_executors_with_router_override(
        &self,
        operation_llm_router_override: Option<Arc<OperationLlmRouter>>,
    ) -> crate::magician_v2::execution::agentic::ActionExecutors {
        use crate::magician_v2::execution::executor_factory::{self, ExecutorFactoryConfig};

        // Scoped durable artifacts live under the V3 scopes tree.
        let mut file_sandbox = self.runtime_config.file_sandbox();
        file_sandbox.augment_with_scopes_root(self.durable_artifact_workspace.base_root());
        let factory_config = ExecutorFactoryConfig {
            magicutor_client: self.magicutor_client.clone(),
            prompt_manager: self.prompt_manager.clone(),
            screenshot_storage: self.screenshot_storage.clone(),
            shell_sandbox: self.runtime_config.shell_sandbox(),
            file_sandbox,
            browser_engine: self
                .content_acquisition_resolver()
                .and_then(|resolver| resolver.configured_browser_engine()),
            browser_capture_limit_bytes: self
                .content_acquisition_resolver()
                .map(|resolver| resolver.configured_browser_capture_limit_bytes()),
            browser_cdp_url: self
                .content_acquisition_resolver()
                .map(|resolver| resolver.configured_browser_cdp_url())
                .unwrap_or_else(|| {
                    crate::magician_v2::execution::primitive_dispatch::browser::DEFAULT_MAGICUTOR_PROXY_URL.to_string()
                }),
            event_broadcaster: self.event_broadcaster.clone(),
            canonical_event_sink: self
                .runtime_canonical_event_sink
                .read()
                .expect("runtime_canonical_event_sink lock poisoned")
                .clone(),
            operation_llm_router: operation_llm_router_override
                .or_else(|| self.operation_llm_router.clone())
                .expect("operation_llm_router is required for agentic executor construction"),
            trace_manager: self.trace_manager.clone(),
            api_router: None,
            api_mining_base_path:
                crate::magician_v2::artifact_v2::workspace::ArtifactV2Workspace::new(
                    std::path::PathBuf::from(self.runtime_config.storage_path()),
                )
                .api_mining_root("__unbound__", "__unbound__"),
            enable_xhr_validation: self.api_mining_config.enable_xhr_validation,
            capability_registry: self.capability_registry.clone(),
            secret_store: None,
            api_mining_origin_policy: None,
            tool_authorization_policy: self
                .tool_authorization_policy
                .read()
                .expect("tool_authorization_policy lock poisoned")
                .clone(),
            config_tool_allowlist: self
                .config_tool_allowlist
                .read()
                .expect("config_tool_allowlist lock poisoned")
                .clone(),
            config_tool_blocklist: self
                .config_tool_blocklist
                .read()
                .expect("config_tool_blocklist lock poisoned")
                .clone(),
            user_request_service: self
                .user_request_service
                .read()
                .expect("user_request_service lock poisoned")
                .clone(),
            storage_base_path: std::path::PathBuf::from(self.runtime_config.storage_path()),
            repo_root: self.repo_root.clone(),
            secret_store_resolver: Some(self.secret_store_resolver.clone()),
            agent_surface_runtime_config: self
                .agent_surface_runtime_config
                .read()
                .expect("agent_surface_runtime_config lock poisoned")
                .clone(),
            surface_plan_cache: self
                .surface_plan_cache
                .read()
                .expect("surface_plan_cache lock poisoned")
                .clone(),
            surface_working_sets: self
                .surface_working_sets
                .read()
                .expect("surface_working_sets lock poisoned")
                .clone(),
            resource_ledger: None,
            token_store: None,
            system_ceilings: None,
            system_freeze: None,
        };
        let executors = executor_factory::build_action_executors(&factory_config);
        #[cfg(any(test, debug_assertions))]
        let executors = if let Some(queue) = self
            .test_native_responses
            .read()
            .expect("test_native_responses lock poisoned")
            .clone()
        {
            executors.with_native_adapter(Arc::new(
                crate::magician_v2::execution::MultiLlmAgentAdapter::new_with_test_native_queue(
                    queue,
                ),
            ))
        } else {
            executors
        };
        // Wire cross-agent delegation dispatcher if configured.
        let guard = self
            .delegation_dispatcher
            .read()
            .expect("delegation_dispatcher lock poisoned");
        let mut executors = match guard.as_ref() {
            Some(dispatcher) => executors.with_delegation_dispatcher(dispatcher.clone()),
            None => executors,
        };
        if let Some(service) = self
            .artifact_v2_service
            .read()
            .expect("artifact_v2_service lock")
            .clone()
        {
            executors = executors.with_artifact_v2_service(service);
        }
        // Wire definition store for agent kind validation in CreateTask
        if let Some(ds) = self
            .definition_store
            .read()
            .expect("definition_store lock")
            .clone()
        {
            executors = executors.with_definition_store(ds);
        }
        // Override the factory's bare resolver with the fully-wired one
        // (compiled-handler registry + AgentResources installed at boot). The
        // factory builds a resolver via `ScopedCapabilityResolver::new` without
        // those, so its per-scope registries lack providers for handler-backed
        // universals — `tool_search`, `edit_file`, `read_file`, `grep`, … would
        // dispatch to "not a compiled pack". Direct/autonomous executions now
        // share the same wired resolver as chat.
        if let Some(resolver) = self
            .scoped_capability_resolver
            .read()
            .expect("scoped_capability_resolver lock")
            .clone()
        {
            executors = executors.with_capability_scope_resolver(resolver);
        }
        if let Some(orchestrator) = self.weak_self.upgrade() {
            executors = executors.with_ownership_runtime(orchestrator);
        }
        executors = executors.with_artifact_v2_workspace(self.durable_artifact_workspace.clone());
        executors = executors
            .with_taskplan_base_path(std::path::PathBuf::from(self.runtime_config.storage_path()));
        if let Some(authority) = self
            .compiled_dispatch_authority
            .read()
            .expect("compiled_dispatch_authority lock poisoned")
            .clone()
        {
            executors = executors.with_compiled_dispatch_authority(authority);
        }
        executors
    }

    /// Boot-time setter for the `CompiledDispatchAuthority` bundle.
    /// Called from `bin/magician.rs` once the resource-authority
    /// primitives (ledger, token store, system ceilings, freeze state,
    /// spend resolver) are constructed. The bundle is then forwarded
    /// into every `ActionExecutors` built through
    /// `build_action_executors_with_router_override`, so the
    /// autonomous outer loop's inner-loop `CompiledProviderDispatcher`
    /// can charge the same spend ledger the chat fast-path does.
    pub fn set_compiled_dispatch_authority(
        &self,
        authority: crate::magician_v2::execution::compiled_dispatch::CompiledDispatchAuthority,
    ) {
        *self
            .compiled_dispatch_authority
            .write()
            .expect("compiled_dispatch_authority lock poisoned") = Some(authority);
    }

    /// Executors for a paused run rehydrated from disk, with the scope's
    /// secret store attached the way a direct launch attaches it. A resume
    /// vaults the person's answer into `executors.secret_store` before the
    /// context retains a reference (P3); without the scope's store here the
    /// answer is dropped with a warning and every reference it left behind
    /// fails closed at dispatch — which the P7 qualification lane found on
    /// the stateless driver, whose pauses are always rehydrated.
    pub fn build_action_executors_for_resume(
        &self,
        routing_overrides: Option<OperationRoutingOverrides>,
        execution_id: Option<&str>,
        principal: Option<&str>,
        workspace: Option<&str>,
    ) -> crate::magician_v2::execution::agentic::ActionExecutors {
        let mut executors = self.build_action_executors_with_operation_routing_overrides(
            routing_overrides,
            None,
            execution_id,
        );
        if let Some(scope) = execution_id.and_then(|id| self.runtime_canonical_event_scope(id)) {
            executors = executors.with_canonical_event_scope(scope);
        }
        if let (Some(principal), Some(workspace)) = (principal, workspace) {
            match self
                .secret_store_resolver
                .resolve_for_scope(principal, workspace)
            {
                Ok(store) => {
                    store.set_captured_max_origins(self.api_mining_config.max_vault_origins);
                    executors = executors.with_secret_store(store);
                },
                Err(error) => {
                    tracing::warn!(
                        "[SECRETS] Failed to resolve scoped secret store for {}/{} at resume: {}",
                        principal,
                        workspace,
                        error
                    );
                },
            }
        }
        executors
    }

    /// Build `ActionExecutors` with optional per-operation routing overrides and temperature override.
    pub fn build_action_executors_with_operation_routing_overrides(
        &self,
        routing_overrides: Option<OperationRoutingOverrides>,
        temperature_override: Option<f32>,
        execution_id: Option<&str>,
    ) -> crate::magician_v2::execution::agentic::ActionExecutors {
        if routing_overrides.is_some() && self.operation_llm_router.is_none() {
            warn!(
                "Agent LLM routing overrides specified but no base operation_llm_router is \
                 configured; action executor construction requires an operation_llm_router"
            );
        }
        // Always clone the base router for a real execution so we can tag its
        // dispatch jobs with the execution id (PR1b: cancel_execution → cancel
        // the execution's queued + in-flight LLM jobs). The clone shares the
        // dispatch-queue handle and is otherwise identical to the base router,
        // so this is behaviour-preserving even when no routing/temperature
        // override is present.
        let router_override = self.operation_llm_router.as_ref().map(|router| {
            let mut cloned = router.as_ref().clone();
            if let Some(overrides) = routing_overrides {
                cloned = cloned.with_routing_overrides(Some(overrides));
            }
            if let Some(temp) = temperature_override {
                cloned = cloned.with_temperature_override(Some(temp));
            }
            if let Some(execution_id) = execution_id {
                cloned =
                    cloned.with_task_context(Some(magicllm::dispatch::TaskRef::task(execution_id)));
            }
            Arc::new(cloned)
        });
        self.build_action_executors_with_router_override(router_override)
    }

