    /// Classify task ownership from both the reserved namespace and the
    /// authoritative sealed app binding. Only a non-canonical task with no app
    /// binding is ordinary. Missing/corrupt canonical state and an app binding
    /// attached to a non-canonical id are lifecycle corruption and fail closed.
    async fn classify_governed_app_execution(
        &self,
        execution: &ExecutionRun,
    ) -> Result<bool, String> {
        let Some(task_id) = execution.task_id.as_deref() else {
            return Ok(false);
        };
        let canonical = is_canonical_app_workflow_task_id(task_id);
        let Some(service) = self.artifact_v2_service() else {
            return if canonical {
                Err(format!(
                    "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{}",
                    execution.id
                ))
            } else {
                Ok(false)
            };
        };
        let scope = ScopeRef::system_internal_unauthenticated(
            &execution.principal.clone(),
            &execution.workspace.clone(),
        );
        match service
            .app_workflow_service()
            .is_workflow_task(&scope, task_id)
            .await
        {
            Ok(true) if canonical => Ok(true),
            Ok(false) if !canonical => Ok(false),
            Ok(_) | Err(_) => Err(format!(
                "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{}",
                execution.id
            )),
        }
    }

    async fn reject_generic_app_execution(&self, execution: &ExecutionRun) -> Result<(), String> {
        if self.classify_governed_app_execution(execution).await? {
            reject_generic_app_execution_control(execution.task_id.as_deref(), &execution.id)?;
        }
        Ok(())
    }

    /// Read-only authoritative ownership query for adapters that must decide
    /// before touching side state such as a durable pause claim.
    pub async fn is_governed_app_execution(&self, execution_id: &str) -> Result<bool, String> {
        let execution = self
            .conversation_store
            .get_execution(execution_id)
            .await
            .map_err(|error| format!("Failed to load execution ownership: {error}"))?;
        self.classify_governed_app_execution(&execution).await
    }

    /// Install the fully-wired scoped capability resolver (compiled-handler
