    pub async fn resolve_resume_merged_agent_tools(
        &self,
        pause_state: &crate::magician_v2::execution::agentic::AgenticPauseState,
    ) -> Option<Vec<ToolInfo>> {
        let agent_id = pause_state
            .agent_id
            .as_deref()
            .or(pause_state.active_owner_agent_id.as_deref())?;

        let mut tools = self
            .resolve_merged_agent_tools_for_scope(
                agent_id,
                pause_state.principal.as_deref(),
                pause_state.workspace.as_deref(),
            )
            .await;

        // `task_state` is a runtime-owned implicit capability. It is deliberately
        // absent from persisted/declared agent grants, so a resume must recreate
        // it from the trusted task binding instead of relying on the pause blob.
        if pause_state.task_id.is_some()
            && !tools.iter().any(|tool| {
                tool.name
                    == crate::magician_v2::execution::task_state_provider::TASK_STATE_TOOL_NAME
            })
        {
            let mut context = ExecutionContext::default();
            if let Some(principal) = pause_state.principal.as_deref() {
                context.principal = principal.to_string();
            }
            if let Some(workspace) = pause_state.workspace.as_deref() {
                context.workspace = workspace.to_string();
            }
            let requested = [
                crate::magician_v2::execution::task_state_provider::TASK_STATE_TOOL_NAME
                    .to_string(),
            ];
            match tokio::time::timeout(
                std::time::Duration::from_secs(3),
                self.tool_catalog
                    .agent_filtered_tools(&requested, &[], &context),
            )
            .await
            {
                Ok(Ok(mut resolved)) => {
                    if let Some(tool) = resolved.drain(..).find(|tool| {
                        tool.name
                            == crate::magician_v2::execution::task_state_provider::TASK_STATE_TOOL_NAME
                    }) {
                        tools.push(tool);
                    }
                },
                Ok(Err(error)) => warn!(
                    error = %error,
                    agent_id = %agent_id,
                    "[MAGICIAN-V2-ORCHESTRATOR] Failed to restore implicit task-state capability"
                ),
                Err(_) => warn!(
                    agent_id = %agent_id,
                    "[MAGICIAN-V2-ORCHESTRATOR] Timed out restoring implicit task-state capability"
                ),
            }
        }

        if tools.is_empty() {
            warn!(
                agent_id = %agent_id,
                principal = ?pause_state.principal,
                workspace = ?pause_state.workspace,
                "[MAGICIAN-V2-ORCHESTRATOR] Resume tool resolution returned no tools"
            );
            None
        } else {
            Some(tools)
        }
    }

    async fn load_v3_task_record(
        &self,
        task_id: &str,
    ) -> Result<
        Option<(
            ScopeRef,
            crate::magician_v2::artifact_v2::models::TaskRecord,
        )>,
        String,
    > {
        let service = self.artifact_v2_service().ok_or_else(|| {
            format!("artifact_v2_service unavailable while loading V3 task {task_id}")
        })?;
        match service.get_task_by_id(task_id).await {
            Ok(task) => Ok(task),
            Err(crate::magician_v2::artifact_v2::ArtifactV2Error::TaskNotFound(_)) => Ok(None),
            Err(error) => Err(format!("failed to load V3 task {task_id}: {error}")),
        }
    }

