    /// Process message with strategy-based exploration.
    ///
    /// Coordinator that delegates to three focused helpers:
    /// 1. [`Self::prepare_execution_and_turn`] — execution/turn setup
    /// 2. [`Self::build_and_execute_pipeline`] — planning pipeline execution
    ///    (intent classification now happens inside the pipeline as `system:intent-classifier`)
    /// 3. [`Self::handle_pipeline_outcome`] — artifact extraction + result construction
    pub async fn process_with_strategy(
        &self,
        query: &str,
        execution_context: ExecutionContext,
        in_reply_to_slot_id: Option<String>,
        existing_execution_id: Option<String>,
        seed_plan_graph: Option<PlanGraph>,
    ) -> Result<StrategyProcessingResult, String> {
        self.process_with_strategy_inner(
            query,
            execution_context,
            in_reply_to_slot_id,
            existing_execution_id,
            seed_plan_graph,
            None,
        )
        .await
    }

    /// Resume a server-accepted initial planning request without appending a
    /// second user turn. The accepted-launch intent owns the exact turn id;
    /// ordinary message processing cannot opt into this reuse path.
    pub(crate) async fn process_accepted_launch_with_strategy(
        &self,
        query: &str,
        execution_context: ExecutionContext,
        existing_execution_id: String,
        accepted_turn_id: String,
        in_reply_to_slot_id: Option<String>,
    ) -> Result<StrategyProcessingResult, String> {
        self.process_with_strategy_inner(
            query,
            execution_context,
            in_reply_to_slot_id,
            Some(existing_execution_id),
            None,
            Some(accepted_turn_id),
        )
        .await
    }

    /// Process a sealed Artifact task-planning receipt from its exact inbound
    /// turn without ever executing the resulting PlanGraph. A durable turn
    /// completion is adopted as the idempotency receipt; callers must own the
    /// separate cross-process planning lease before entering this seam.
    pub(crate) async fn process_task_planning_receipt_with_strategy(
        &self,
        query: &str,
        execution_context: ExecutionContext,
        existing_execution_id: String,
        accepted_turn_id: String,
    ) -> Result<(), String> {
        if execution_context
            .metadata
            .get("planning_only")
            .map(String::as_str)
            != Some("true")
        {
            return Err(
                "task planning receipt requires planning_only execution context".to_owned(),
            );
        }
        let turn = self
            .conversation_store
            .get_turn(&existing_execution_id, &accepted_turn_id)
            .await
            .map_err(|error| format!("failed to load task planning turn receipt: {error}"))?;
        if turn.execution_id != existing_execution_id
            || turn.direction != TurnDirection::Inbound
            || turn.text != query
            || turn.in_reply_to_slot_id.is_some()
        {
            return Err(format!(
                "task planning turn receipt identity mismatch:{accepted_turn_id}"
            ));
        }
        if let Some(metadata) = turn.processing_metadata.as_ref() {
            if metadata.disposition() == ProcessingDisposition::Completed {
                return Ok(());
            }
            if self
                .ask_loop_requires_user(&existing_execution_id)
                .await
                .map_err(|error| error.to_string())?
            {
                return Err(format!(
                    "task_planning_clarification_still_pending:{existing_execution_id}"
                ));
            }
        }
        self.process_accepted_launch_with_strategy(
            query,
            execution_context,
            existing_execution_id,
            accepted_turn_id,
            None,
        )
        .await?;
        Ok(())
    }

    /// Re-enter an accepted planning launch from its exact durable turn. A
    /// completed turn is the processing receipt: task work adopts its stored
    /// PlanGraph, while a non-task result returns without replaying the
    /// planning pipeline. Only a turn with no completion receipt is planned.
    pub(crate) async fn resume_accepted_launch_with_strategy(
        &self,
        query: &str,
        execution_context: ExecutionContext,
        existing_execution_id: String,
        accepted_turn_id: String,
        in_reply_to_slot_id: Option<String>,
    ) -> Result<(), String> {
        let accepted_turn = self
            .conversation_store
            .get_turn(&existing_execution_id, &accepted_turn_id)
            .await
            .map_err(|error| format!("failed to load accepted planning receipt: {error}"))?;
        if accepted_turn.execution_id != existing_execution_id
            || accepted_turn.direction != TurnDirection::Inbound
            || accepted_turn.text != query
            || accepted_turn.in_reply_to_slot_id != in_reply_to_slot_id
        {
            return Err(format!(
                "accepted planning receipt identity mismatch:{accepted_turn_id}"
            ));
        }
        let durable_plan = accepted_turn
            .strategy_attempts
            .iter()
            .rev()
            .find(|attempt| {
                attempt.failure_reason.is_none()
                    && attempt.exploration_result.strategy_metadata.completed
            })
            .and_then(|attempt| attempt.exploration_result.plan.clone());
        if let Some(plan_graph) = durable_plan {
            if plan_graph.steps.is_empty() {
                // An empty completed plan is an honest non-task processing
                // receipt, not executable composition. Converge it before the
                // accepted envelope can be consumed.
                return self
                    .converge_non_task_processing_receipt(&existing_execution_id)
                    .await;
            }
            let current = self
                .conversation_store
                .get_execution(&existing_execution_id)
                .await
                .map_err(|error| format!("failed to load accepted planned execution: {error}"))?;
            match current.waiting_state {
                WaitingState::Planning => {
                    let next = self
                        .transition_status_from_runtime(
                            &existing_execution_id,
                            WorkflowEvent::ReadyToExecute,
                        )
                        .await?;
                    if next != WaitingState::PlanningComplete {
                        return Err(format!(
                            "accepted planned execution entered unexpected state {next:?}"
                        ));
                    }
                },
                WaitingState::PlanningComplete => {},
                WaitingState::Runnable | WaitingState::Executing => {
                    if crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::from_env()
                        == crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::Inprocess
                    {
                        // The accepted envelope claim is the resident driver's
                        // restart owner. `inprocess` deliberately has no
                        // stateless catalog/token, so replay the exact stored
                        // PlanGraph under the ordinary lifecycle/control fence
                        // and retain its documented resident at-least-once
                        // semantics.
                        return self
                            .execute_plan_graph_with_recovery(
                                &existing_execution_id,
                                &plan_graph,
                                current.task_id.as_deref(),
                                None,
                                true,
                            )
                            .await;
                    }
                    let recovery =
                        match self.claim_interrupted_plan_recovery(&current, None).await? {
                            InterruptedPlanRecoveryAdmission::Admitted(recovery) => recovery,
                            InterruptedPlanRecoveryAdmission::AlreadyOwned => {
                                return Err(format!(
                                    "accepted planned execution recovery is already owned:{}",
                                    current.id
                                ))
                            },
                            InterruptedPlanRecoveryAdmission::Deferred(reason) => {
                                return Err(format!(
                                    "accepted planned execution recovery deferred:{reason}"
                                ))
                            },
                        };
                    return self
                        .execute_plan_graph_with_recovery(
                            &existing_execution_id,
                            &plan_graph,
                            current.task_id.as_deref(),
                            Some(recovery),
                            false,
                        )
                        .await;
                },
                WaitingState::Sleeping
                | WaitingState::WaitingChildren
                | WaitingState::WaitingUser
                | WaitingState::Paused
                | WaitingState::Completed
                | WaitingState::Failed
                | WaitingState::Cancelled => return Ok(()),
            }
            self.execute_plan_graph(
                &existing_execution_id,
                &plan_graph,
                current.task_id.as_deref(),
            )
            .await?;
            return Ok(());
        }
        if let Some(metadata) = accepted_turn.processing_metadata.as_ref() {
            if metadata.disposition() == ProcessingDisposition::ClarificationSuspended {
                let still_waiting = self
                    .ask_loop_requires_user(&existing_execution_id)
                    .await
                    .map_err(|error| error.to_string())?;
                if still_waiting {
                    let state = self.get_execution_status(&existing_execution_id).await?;
                    if !matches!(state, WaitingState::WaitingUser | WaitingState::Paused) {
                        return Err(format!(
                            "accepted clarification receipt has unexpected state {state:?}:{existing_execution_id}"
                        ));
                    }
                    return Err(format!(
                        "accepted_launch_clarification_suspended:{existing_execution_id}"
                    ));
                }
            } else {
                // The pipeline durably completed without a PlanGraph (for example
                // a status response). Replaying it could duplicate LLM work and
                // external message projections, so the receipt is terminal for
                // this accepted request.
                return self
                    .converge_non_task_processing_receipt(&existing_execution_id)
                    .await;
            }
        }
        self.process_accepted_launch_with_strategy(
            query,
            execution_context,
            existing_execution_id.clone(),
            accepted_turn_id.clone(),
            in_reply_to_slot_id,
        )
        .await?;
        let completed_turn = self
            .conversation_store
            .get_turn(&existing_execution_id, &accepted_turn_id)
            .await
            .map_err(|error| format!("failed to reload accepted processing receipt: {error}"))?;
        if completed_turn
            .processing_metadata
            .as_ref()
            .is_some_and(|metadata| {
                metadata.disposition() == ProcessingDisposition::ClarificationSuspended
            })
        {
            return Err(format!(
                "accepted_launch_clarification_suspended:{existing_execution_id}"
            ));
        }
        if completed_turn.processing_metadata.is_some()
            && !completed_turn.strategy_attempts.iter().any(|attempt| {
                attempt.failure_reason.is_none()
                    && attempt.exploration_result.strategy_metadata.completed
                    && attempt
                        .exploration_result
                        .plan
                        .as_ref()
                        .is_some_and(|plan| !plan.steps.is_empty())
            })
        {
            self.converge_non_task_processing_receipt(&existing_execution_id)
                .await?;
        }
        Ok(())
    }

    async fn converge_non_task_processing_receipt(&self, execution_id: &str) -> Result<(), String> {
        let execution = self
            .conversation_store
            .get_execution(execution_id)
            .await
            .map_err(|error| error.to_string())?;
        let _lifecycle = self
            .acquire_resumable_pause_lifecycle_admission_scoped(
                execution_id,
                &execution.principal,
                &execution.workspace,
            )
            .await?;
        let mut state = self.get_execution_status(execution_id).await?;
        if state == WaitingState::Planning {
            state = self
                .transition_status_from_runtime(execution_id, WorkflowEvent::ReadyToExecute)
                .await?;
        }
        if state == WaitingState::PlanningComplete {
            state = self
                .transition_status_from_runtime(execution_id, WorkflowEvent::ExecutionStart)
                .await?;
        }
        if matches!(state, WaitingState::Executing | WaitingState::Runnable) {
            state = self
                .transition_status_from_runtime(execution_id, WorkflowEvent::ExecutionComplete)
                .await?;
        }
        if state != WaitingState::Completed {
            return Err(format!(
                "accepted non-task receipt could not converge from {state:?}:{execution_id}"
            ));
        }
        Ok(())
    }

    async fn process_with_strategy_inner(
        &self,
        query: &str,
        execution_context: ExecutionContext,
        in_reply_to_slot_id: Option<String>,
        existing_execution_id: Option<String>,
        seed_plan_graph: Option<PlanGraph>,
        accepted_turn_id: Option<String>,
    ) -> Result<StrategyProcessingResult, String> {
        info!(
            "[MAGICIAN-V2-ORCHESTRATOR] V2 Enhanced Strategy Processing: Starting for query '{}'",
            query
        );
        let processing_start = std::time::Instant::now();
        self.ensure_initialized()?;
        let mut execution_context = execution_context;

        let ttc = self
            .prepare_execution_and_turn(
                query,
                &mut execution_context,
                in_reply_to_slot_id,
                existing_execution_id.as_deref(),
                accepted_turn_id.as_deref(),
            )
            .await?;

        // Ask-loop gate: if a prior session is still collecting answers, return
        // early and let the pipeline re-run on the next turn.
        if self
            .ask_loop_requires_user(&ttc.execution.id)
            .await
            .map_err(|error| error.to_string())?
        {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Existing clarification session still collecting \
                 answers for execution {}; pausing planning",
                ttc.execution.id
            );
            let pending = self
                .load_pending_recommended_questions(&ttc.execution.id)
                .await;
            let paused_state = self
                .transition_status_from_runtime(&ttc.execution.id, WorkflowEvent::UserPaused)
                .await?;
            if !matches!(
                paused_state,
                WaitingState::WaitingUser | WaitingState::Paused
            ) {
                return Err(format!(
                    "clarification pause entered unexpected state {paused_state:?}:{}",
                    ttc.execution.id
                ));
            }
            let mut processing_metadata = ProcessingMetadata {
                total_duration_ms: processing_start.elapsed().as_millis() as u64,
                strategy_duration_ms: 0,
                strategy_selected: StrategyType::AtomicComposition,
                processed_at: chrono::Utc::now(),
                retry_attempts: 0,
                strategies_attempted: Vec::new(),
                final_strategy: StrategyType::AtomicComposition,
                current_stage: None,
                current_provider: None,
            };
            processing_metadata.mark_clarification_suspended();
            self.conversation_store
                .store_strategy_attempts(
                    &ttc.execution.id,
                    &ttc.user_turn.id,
                    Vec::new(),
                    processing_metadata,
                    None,
                )
                .await
                .map_err(|error| {
                    format!("failed to persist clarification suspension receipt: {error}")
                })?;
            return Ok(StrategyProcessingResult::for_non_pipeline_exit(
                query,
                &execution_context.principal,
                &execution_context.workspace,
                &ttc.execution.id,
                UnifiedQueryAnalysis::minimal_for_pause(query),
                AnalysisMetadata {
                    analysis_duration_ms: 0,
                    llm_provider: String::new(),
                    analyzed_at: chrono::Utc::now(),
                    from_cache: false,
                },
                processing_start,
                pending,
                None,
                Vec::new(),
                None,
                self.consumer_mode,
            ));
        }

        if let Some(seed_plan_graph) = seed_plan_graph {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Reusable PlanGraph found for execution {}; bypassing pipeline planning and executing with runtime plan context",
                ttc.execution.id
            );

            let mut query_analysis = UnifiedQueryAnalysis::minimal_for_pause(query);
            query_analysis.intent = QueryIntent::NewTask;
            let analysis_metadata = AnalysisMetadata {
                analysis_duration_ms: 0,
                llm_provider: "seeded-plan-direct".to_string(),
                analyzed_at: chrono::Utc::now(),
                from_cache: true,
            };

            self.conversation_store
                .store_analysis(
                    &ttc.execution.id,
                    &ttc.user_turn.id,
                    query_analysis.clone(),
                    analysis_metadata.clone(),
                )
                .await
                .map_err(|e| format!("Failed to store seeded-plan analysis: {}", e))?;

            if let Some(broadcaster) = &self.event_broadcaster {
                broadcaster.query_analysis_completed(
                    &ttc.execution.id,
                    &ttc.correlation_id,
                    query_analysis.complexity.score as f64,
                    format!("{:?}", query_analysis.intent),
                    query_analysis.categories.categories.clone(),
                );
            }

            self.execute_plan_graph(&ttc.execution.id, &seed_plan_graph, None)
                .await?;

            return Ok(StrategyProcessingResult::for_non_pipeline_exit(
                query,
                &execution_context.principal,
                &execution_context.workspace,
                &ttc.execution.id,
                query_analysis,
                analysis_metadata,
                processing_start,
                Vec::new(),
                None,
                Vec::new(),
                None,
                self.consumer_mode,
            ));
        }

        let peo = self
            .build_and_execute_pipeline(query, &ttc, &execution_context)
            .await?;

        self.handle_pipeline_outcome(
            query,
            &ttc,
            &execution_context,
            peo.outcome,
            peo.plan_graph_artifact_id,
            processing_start,
            peo.pipeline_duration,
        )
        .await
    }

    // =====================================================================
    // process_with_strategy — helper 1: prepare_execution_and_turn
    // =====================================================================

    /// Create or retrieve the execution, add the user turn, and emit
    /// the `message_started` event.
    async fn prepare_execution_and_turn(
        &self,
        query: &str,
        execution_context: &mut ExecutionContext,
        in_reply_to_slot_id: Option<String>,
        existing_execution_id: Option<&str>,
        accepted_turn_id: Option<&str>,
    ) -> Result<ExecutionTurnContext, String> {
        info!(
            "[MAGICIAN-V2-ORCHESTRATOR] Step 1: Saving message to storage (conversation execution \
             and turn management)"
        );
        let requested_execution_id = existing_execution_id
            .or_else(|| {
                execution_context
                    .metadata
                    .get("runtime_execution_id")
                    .map(String::as_str)
            })
            .or_else(|| {
                execution_context
                    .metadata
                    .get("execution_id")
                    .map(String::as_str)
            })
            .ok_or_else(|| {
                "process_with_strategy requires a pre-provisioned task-backed execution_id"
                    .to_string()
            })?;

        let execution = self
            .conversation_store
            .get_execution(requested_execution_id)
            .await
            .map_err(|e| format!("Failed to get execution: {}", e))?;
        Self::ensure_planning_backed_execution(&execution)?;

        // M-07: The execution was originally created with the agent's declared principal
        // (sourced from AgentDefinition.principal via trigger_goal_awaitable). Copying
        // execution.principal here preserves that identity across pipeline resumptions.
        execution_context.principal = execution.principal.clone();
        execution_context.workspace = execution.workspace.clone();

        // Restore questions from storage for the scoped execution.
        self.restore_execution_questions(&execution.id).await;

        let user_turn = if let Some(accepted_turn_id) = accepted_turn_id {
            self.conversation_store
                .get_turns(&execution.id)
                .await
                .map_err(|e| format!("Failed to load accepted message: {e}"))?
                .into_iter()
                .find(|turn| turn.id == accepted_turn_id)
                .filter(|turn| {
                    turn.execution_id == execution.id
                        && turn.direction == TurnDirection::Inbound
                        && turn.text == query
                        && turn.in_reply_to_slot_id == in_reply_to_slot_id
                })
                .ok_or_else(|| {
                    format!(
                        "accepted launch turn does not match its sealed request:{accepted_turn_id}"
                    )
                })?
        } else {
            self.conversation_store
                .add_turn(
                    &execution.id,
                    TurnDirection::Inbound,
                    query.to_string(),
                    in_reply_to_slot_id,
                )
                .await
                .map_err(|e| format!("Failed to save message: {}", e))?
        };

        info!(
            "[MAGICIAN-V2-ORCHESTRATOR] Message saved as turn {} in execution {}",
            user_turn.id, execution.id
        );

        // Generate correlation_id for request tracing (used throughout processing)
        let correlation_id = format!("msg-{}-{}", execution.id, uuid::Uuid::new_v4());

        // Emit MessageProcessingStarted event
        if let Some(broadcaster) = &self.event_broadcaster {
            broadcaster.message_started(&execution.id, &user_turn.id, &correlation_id);
        }

        Ok(ExecutionTurnContext {
            execution,
            user_turn,
            correlation_id,
        })
    }

    // =====================================================================
    // process_with_strategy — helper 2: build_and_execute_pipeline
    // =====================================================================

    /// Build the artifact store, construct the planning pipeline, and execute it.
    async fn build_and_execute_pipeline(
        &self,
        query: &str,
        ttc: &ExecutionTurnContext,
        execution_context: &ExecutionContext,
    ) -> Result<PipelineExecutionOutcome, String> {
        // ────────────────────────────────────────────────────────────────────────
        // P5.5-D switchover: planning pipeline replaces the manual elicitation
        // + AdaptiveStrategySelector block. Intent classification now happens
        // inside the pipeline as system:intent-classifier (first agent).
        // ────────────────────────────────────────────────────────────────────────
        let pipeline_start = std::time::Instant::now();

        // P5.5-E: Load persisted artifact store (or create fresh).
        //
        // The IntentClassifierAgent purges stale analysis/slot artifacts on
        // NewTask, so we always attempt to load the existing store.  For new
        // tasks the agent clears stale artifacts; for continuations prior-cycle
        // artifacts (SlotGraph, prior answers, etc.) are preserved.
        let seed_store = {
            use crate::magician_v2::artifact_v2::{
                ExecutionPipelineStoreError, FilesystemExecutionPipelineStore, ScopeRef,
            };

            let pipeline_store =
                FilesystemExecutionPipelineStore::new(self.durable_artifact_workspace.clone());
            let scope = ScopeRef::system_internal_unauthenticated(
                &execution_context.principal.clone(),
                &execution_context.workspace.clone(),
            );

            let mut store = match pipeline_store
                .load_store(&scope, ttc.execution.task_id.as_deref(), &ttc.execution.id)
                .await
            {
                Ok(existing) => existing,
                Err(ExecutionPipelineStoreError::NotFound(_)) => {
                    crate::magician_v2::pipeline::artifact::ArtifactStore::new(
                        ttc.execution.id.clone(),
                    )
                },
                Err(error @ ExecutionPipelineStoreError::Serialization(_))
                | Err(error @ ExecutionPipelineStoreError::InvalidData(_)) => {
                    error!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Corrupt V3 pipeline store for '{}': {:?} — \
                         revalidating under the mutation lock before recovery",
                        ttc.execution.id, error
                    );
                    match pipeline_store
                        .recover_corrupt_store(
                            &scope,
                            ttc.execution.task_id.as_deref(),
                            &ttc.execution.id,
                        )
                        .await
                    {
                        Ok(recovered) => recovered,
                        Err(recovery_err) => {
                            warn!(
                                "[MAGICIAN-V2-ORCHESTRATOR] Failed to recover corrupt V3 pipeline store for '{}': {:?}",
                                ttc.execution.id, recovery_err
                            );
                            crate::magician_v2::pipeline::artifact::ArtifactStore::new(
                                ttc.execution.id.clone(),
                            )
                        },
                    }
                },
                Err(error) => {
                    error!(
                        "[MAGICIAN-V2-ORCHESTRATOR] IO error reading V3 pipeline store for '{}': {:?} — \
                         file is likely healthy; falling back to fresh store without backup",
                        ttc.execution.id, error
                    );
                    crate::magician_v2::pipeline::artifact::ArtifactStore::new(
                        ttc.execution.id.clone(),
                    )
                },
            };

            // Seed persisted execution artifacts from the scoped V3 execution index so
            // delegated child inputs and prior downloaded files remain available even
            // after the legacy artifact-chain store is retired from the active path.
            if let Some(task_id) = ttc.execution.task_id.as_deref() {
                let scope =
                    crate::magician_v2::artifact_v2::ScopeRef::system_internal_unauthenticated(
                        &execution_context.principal.clone(),
                        &execution_context.workspace.clone(),
                    );
                let execution_artifact_store =
                    crate::magician_v2::artifact_v2::FilesystemExecutionArtifactIndexStore::new(
                        self.durable_artifact_workspace.clone(),
                    );
                match execution_artifact_store
                    .list_artifacts(&scope, task_id, &ttc.execution.id)
                    .await
                {
                    Ok(records) => {
                        for record in records {
                            let produced_at =
                                chrono::DateTime::parse_from_rfc3339(&record.produced_at)
                                    .map(|value| value.with_timezone(&chrono::Utc))
                                    .unwrap_or_else(|_| chrono::Utc::now());
                            store.put(crate::magician_v2::pipeline::artifact::AgentArtifact {
                                artifact_id: record.artifact_id,
                                artifact_type:
                                    crate::magician_v2::pipeline::artifact::ArtifactType::Custom(
                                        record.artifact_type,
                                    ),
                                producer_agent_id: ttc.execution.active_owner_agent_id.clone(),
                                producer_cycle_id: ttc.execution.id.clone(),
                                content: record.payload,
                                schema_version:
                                    crate::magician_v2::pipeline::artifact::ARTIFACT_SCHEMA_VERSION,
                                produced_at,
                                render_hints: None,
                            });
                        }
                    },
                    Err(error) => {
                        warn!(
                            execution_id = %ttc.execution.id,
                            task_id = %task_id,
                            error = %error,
                            "[PIPELINE:delegation-seed] Failed to load scoped execution artifacts"
                        );
                    },
                }
            }

            let prompt_identity_artifact_type =
                crate::magician_v2::pipeline::artifact::ArtifactType::Custom(
                    "prompt_identity_context".to_string(),
                );
            if let Some(prompt_identity) =
                parse_prompt_identity_metadata(&execution_context.metadata)
            {
                // Replace any prior identity context to avoid cross-run leakage when an execution/store
                // is reused across agents.
                store.remove_all_of_type(&prompt_identity_artifact_type);
                if let Ok(content) = serde_json::to_value(&prompt_identity) {
                    store.put(crate::magician_v2::pipeline::artifact::AgentArtifact {
                        artifact_id: Uuid::new_v4().to_string(),
                        artifact_type: prompt_identity_artifact_type.clone(),
                        producer_agent_id: "system:orchestrator-seed".to_string(),
                        producer_cycle_id: Uuid::new_v4().to_string(),
                        content,
                        schema_version: 1,
                        produced_at: chrono::Utc::now(),
                        render_hints: None,
                    });
                }
            } else {
                // No identity metadata for this run: clear any stale seeded identity.
                store.remove_all_of_type(&prompt_identity_artifact_type);
            }

            store
        };

        // user_answer starts as None; the post-agent hook for IntentClassifier
        // populates it from IntentClassificationResult.user_answer if present.
        let owner_agent_id = execution_context
            .metadata
            .get("active_owner_agent_id")
            .or_else(|| execution_context.metadata.get("agent_id"))
            .cloned()
            .or_else(|| Some(ttc.execution.active_owner_agent_id.clone()));

        let mut pipeline_ctx = crate::magician_v2::pipeline::PipelineContext {
            chain_id: ttc.execution.id.clone(),
            cycle_id: Uuid::new_v4().to_string(),
            workflow_id: ttc.execution.id.clone(),
            query: query.to_string(),
            iteration: 0,
            agent_id: owner_agent_id.clone(),
            correlation_id: Some(ttc.correlation_id.clone()),
            user_answer: None,
            run_started_at: None,
            resume_mode: None,
            llm_routing_calls: 0,
            session_id: None,
            agent_kind: None,
            is_autonomous_cycle: execution_context
                .metadata
                .get("is_autonomous_cycle")
                .map(|v| v == "true")
                .unwrap_or(false),
            trust_level: None,
            tier_definitions: Vec::new(),
            observation_mode: None,
            llm_model_override: None,
            max_delegation_depth: execution_context
                .metadata
                .get("agent:max_delegation_depth")
                .and_then(|v| v.parse::<u8>().ok()),
            schedule_context: None,
            question_id: None,
            elicitation_rounds: 0,
            principal: Some(execution_context.principal.clone()),
            workspace: Some(execution_context.workspace.clone()),
            task_id: execution_context.metadata.get("task_id").cloned(),
            execution_id: execution_context
                .metadata
                .get("execution_id")
                .cloned()
                .or_else(|| Some(ttc.execution.id.clone())),
            api_port: execution_context
                .metadata
                .get("api_port")
                .and_then(|v| v.parse::<u16>().ok()),
            // Phase C: refinement loop fields (all start at zero/None)
            refinement_step_id: None,
            original_query: None,
            refinement_rounds: 0,
            refinement_user_pauses: 0,
        };

        if let Some(owner_agent_id) = owner_agent_id.as_deref() {
            match self
                .load_owner_execution_profile(
                    owner_agent_id,
                    Some(&execution_context.principal),
                    Some(&execution_context.workspace),
                )
                .await
            {
                Ok(profile) => {
                    if pipeline_ctx.trust_level.is_none() {
                        pipeline_ctx.trust_level = profile.trust_level;
                    }
                    pipeline_ctx.tier_definitions = profile.tier_definitions;
                },
                Err(error) => {
                    warn!(
                        owner_agent_id = %owner_agent_id,
                        principal = %execution_context.principal,
                        workspace = %execution_context.workspace,
                        error = %error,
                        "process_with_strategy: failed to load owner memory tier definitions for planning"
                    );
                },
            }
        }

        // P5-06: read per-agent metadata injected by trigger_goal_awaitable.
        let planner_strategy_override = execution_context
            .metadata
            .get("agent:strategy_override")
            .and_then(|name| parse_agent_strategy_type(name));
        let pipeline_routing_overrides: Option<OperationRoutingOverrides> = execution_context
            .metadata
            .get("agent:llm_routing")
            .and_then(|json| {
                serde_json::from_str(json).map_err(|e| {
                    tracing::warn!(
                        error = %e,
                        "process_with_strategy: failed to deserialize agent:llm_routing metadata — \
                         routing overrides will not be applied"
                    );
                    e
                }).ok()
            });
        // P6-T1: read per-agent temperature override from metadata.
        let pipeline_temperature_override: Option<f32> = execution_context
            .metadata
            .get("agent:temperature_override")
            .and_then(|s| s.parse::<f32>().ok());
        let planner_backend = {
            let mut backend = MagicianPlannerBackend::new(self.weak_self.clone());
            if let Some(s) = planner_strategy_override {
                backend = backend.with_strategy_override(s);
            }
            if let Some(agent_id) = execution_context
                .metadata
                .get("active_owner_agent_id")
                .or_else(|| execution_context.metadata.get("agent_id"))
                .cloned()
            {
                backend = backend.with_owner_agent_id(agent_id);
            }
            std::sync::Arc::new(backend)
        };
        let pipeline_agents = self.build_pipeline_agents(
            planner_backend,
            pipeline_routing_overrides,
            pipeline_temperature_override,
            execution_context,
        );
        let agent_ids: Vec<String> = pipeline_agents.keys().cloned().collect();
        let pipeline_router = std::sync::Arc::new(
            crate::magician_v2::pipeline::router::TieredRouter::new(None, agent_ids),
        );
        let pipeline_pause_manager = self.ask_loop_api.as_ref().map(|api| api.pause_manager());

        let mut pipeline_orch =
            crate::magician_v2::pipeline::orchestrator::PlanningOrchestrator::new_with_seeded_store(
                pipeline_agents,
                pipeline_router,
                pipeline_ctx,
                PIPELINE_MAX_ITERATIONS,
                pipeline_pause_manager,
                seed_store,
            );

        // M7: wire event broadcaster for pipeline lifecycle events
        if let Some(ref eb) = self.event_broadcaster {
            pipeline_orch.set_event_broadcaster(Arc::clone(eb));
        }

        let outcome = pipeline_orch
            .run()
            .await
            .map_err(|e| format!("Planning pipeline failed: {}", e))?;

        // Extract the PlanGraph artifact ID for I-29 cycle tracking.
        let plan_graph_artifact_id: Option<String> = outcome
            .store
            .latest_of_type(&crate::magician_v2::pipeline::artifact::ArtifactType::PlanGraph)
            .map(|a| a.artifact_id.clone());

        let pipeline_duration = pipeline_start.elapsed();

        Ok(PipelineExecutionOutcome {
            outcome,
            plan_graph_artifact_id,
            pipeline_duration,
        })
    }

    // =====================================================================
    // process_with_strategy — helper 3: handle_pipeline_outcome
    // =====================================================================

    /// Extract artifacts from the pipeline outcome, handle failure/suspension/completion,
    /// and construct the final `StrategyProcessingResult`.
    #[allow(clippy::too_many_arguments)]
    async fn handle_pipeline_outcome(
        &self,
        query: &str,
        ttc: &ExecutionTurnContext,
        execution_context: &ExecutionContext,
        outcome: crate::magician_v2::pipeline::orchestrator::PlanningOutcome,
        plan_graph_artifact_id: Option<String>,
        processing_start: std::time::Instant,
        pipeline_duration: std::time::Duration,
    ) -> Result<StrategyProcessingResult, String> {
        // ────────────────────────────────────────────────────────────────────────
        // Extract IntentClassification + QueryAnalysis from the pipeline store.
        // ────────────────────────────────────────────────────────────────────────
        use crate::magician_v2::pipeline::artifact::ArtifactType as PipelineAT;
        use crate::magician_v2::pipeline::system_agents::intent_classifier::IntentClassificationResult;
        use crate::magician_v2::slot_graph::elicitation::ElicitationResult as PipelineElicitationResult;

        let pipeline_store = crate::magician_v2::artifact_v2::FilesystemExecutionPipelineStore::new(
            self.durable_artifact_workspace.clone(),
        );
        let pipeline_scope =
            crate::magician_v2::artifact_v2::ScopeRef::system_internal_unauthenticated(
                &execution_context.principal.clone(),
                &execution_context.workspace.clone(),
            );

        let ic_artifact = outcome
            .store
            .latest_of_type(&PipelineAT::IntentClassification)
            .ok_or("IntentClassification artifact missing from pipeline store")?;
        let ic_produced_at = ic_artifact.produced_at;
        let intent_classification: IntentClassificationResult =
            ic_artifact
                .deserialize_content()
                .map_err(|e| format!("IntentClassification deserialization failed: {}", e))?;

        let query_analysis: UnifiedQueryAnalysis = outcome
            .store
            .latest_of_type(&PipelineAT::QueryAnalysis)
            .and_then(|a| a.deserialize_content().ok())
            .ok_or("QueryAnalysis artifact missing from pipeline store")?;

        // Persist analysis + emit event.
        let analysis_metadata = AnalysisMetadata {
            analysis_duration_ms: intent_classification.classification_duration_ms,
            llm_provider: self.get_llm_provider_name().await,
            analyzed_at: ic_produced_at,
            from_cache: false,
        };

        self.conversation_store
            .store_analysis(
                &ttc.execution.id,
                &ttc.user_turn.id,
                query_analysis.clone(),
                analysis_metadata.clone(),
            )
            .await
            .map_err(|e| format!("Failed to store analysis: {}", e))?;

        if let Some(broadcaster) = &self.event_broadcaster {
            broadcaster.query_analysis_completed(
                &ttc.execution.id,
                &ttc.correlation_id,
                query_analysis.complexity.score as f64,
                format!("{:?}", query_analysis.intent),
                query_analysis.categories.categories.clone(),
            );
        }

        // Primary extraction: ElicitationResult carries slot_graph + clarified_task.
        let pipeline_elicitation: Option<PipelineElicitationResult> = outcome
            .store
            .latest_of_type(&PipelineAT::ElicitationResult)
            .and_then(|a| {
                a.deserialize_content::<PipelineElicitationResult>()
                    .map_err(|e| {
                        warn!(
                            "[MAGICIAN-V2-ORCHESTRATOR] ElicitationResult deserialize failed \
                             from pipeline store: {}",
                            e
                        );
                        e
                    })
                    .ok()
            });

        let clarified_task: Option<ClarifiedTask> = pipeline_elicitation
            .as_ref()
            .map(|er| er.clarified_task.clone())
            .filter(|ct| !ct.clarified_task.is_empty())
            .or_else(|| {
                outcome
                    .store
                    .latest_of_type(&PipelineAT::ClarifiedTask)
                    .and_then(|a| a.deserialize_content().ok())
            });

        // M-03: fall back to SlotGraph artifact when ElicitationResult absent/empty
        let slot_graph_records: Vec<SlotRecord> = pipeline_elicitation
            .as_ref()
            .filter(|er| !er.slot_graph.is_empty())
            .map(|er| er.slot_graph.clone())
            .or_else(|| {
                outcome
                    .store
                    .latest_of_type(&PipelineAT::SlotGraph)
                    .and_then(|a| {
                        a.deserialize_content::<Vec<SlotRecord>>()
                            .map_err(|e| {
                                warn!(
                                    "[MAGICIAN-V2-ORCHESTRATOR] SlotGraph fallback deserialize failed: {}",
                                    e
                                );
                                e
                            })
                            .ok()
                    })
            })
            .unwrap_or_default();

        // ────────────────────────────────────────────────────────────────────────
        // Handle pipeline failure.
        // ────────────────────────────────────────────────────────────────────────
        if let crate::magician_v2::pipeline::orchestrator::PipelineStatus::Failed(ref reason) =
            outcome.status
        {
            return Err(format!("Planning pipeline failed: {}", reason));
        }

        // Track whether the pipeline suspended (for error diagnostics below).
        let pipeline_was_suspended = matches!(
            outcome.status,
            crate::magician_v2::pipeline::orchestrator::PipelineStatus::Suspended(_)
        );

        // ────────────────────────────────────────────────────────────────────────
        // Handle suspension — dispatch clarification questions.
        // ────────────────────────────────────────────────────────────────────────
        if let crate::magician_v2::pipeline::orchestrator::PipelineStatus::Suspended(
            ref suspension,
        ) = outcome.status
        {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Pipeline suspended (checkpoint {}) for execution {}",
                suspension.checkpoint_id, ttc.execution.id
            );
            let suspension_checkpoint = serde_json::to_value(suspension).map_err(|error| {
                format!(
                    "failed to serialize planning suspension for {}: {error}",
                    ttc.execution.id
                )
            })?;
            self.state_tracker
                .append_stage_checkpoint(
                    &ttc.execution.id,
                    StageContext::PlanningBootstrap,
                    "planning.pipeline.suspended",
                    suspension_checkpoint,
                )
                .await
                .map_err(|error| {
                    format!(
                        "failed to persist planning suspension checkpoint for {}: {error}",
                        ttc.execution.id
                    )
                })?;

            let recommended_questions: Vec<ClarifierQuestion> = pipeline_elicitation
                .as_ref()
                .map(|er| er.recommended_questions.clone())
                .unwrap_or_else(|| {
                    if suspension.question_text.is_empty() {
                        Vec::new()
                    } else {
                        vec![ClarifierQuestion {
                            id: suspension.checkpoint_id.clone(),
                            blocker_type: BlockerType::LowConfidenceSlot,
                            stage: StageContext::PlanningBootstrap,
                            source_slot_id: suspension.slot_ids.first().cloned(),
                            question_text: suspension.question_text.clone(),
                            urgency: 0.7,
                            channel: Channel::InApp,
                            created_at: chrono::Utc::now(),
                            ..ClarifierQuestion::default()
                        }]
                    }
                });

            if let Some(ask_api) = &self.ask_loop_api {
                if !recommended_questions.is_empty() {
                    match self
                        .dispatch_curated_question_batch(
                            ask_api,
                            &ttc.execution.id,
                            &recommended_questions,
                            "planning_elicitation_initial",
                            None,
                            TaskComplexity::Complex,
                            Some(&execution_context.principal),
                            Some(&execution_context.workspace),
                            ttc.execution.task_id.as_deref(),
                        )
                        .await
                    {
                        Ok((batch_id, batch_total)) => {
                            info!(
                                "[MAGICIAN-V2-ORCHESTRATOR] Created batch {} ({} question(s)) \
                                 for pipeline elicitation",
                                batch_id, batch_total
                            );
                            let paused_state = self
                                .transition_status_from_runtime(
                                    &ttc.execution.id,
                                    WorkflowEvent::UserPaused,
                                )
                                .await?;
                            if !matches!(
                                paused_state,
                                WaitingState::WaitingUser | WaitingState::Paused
                            ) {
                                return Err(format!(
                                    "pipeline clarification entered unexpected state {paused_state:?}:{}",
                                    ttc.execution.id
                                ));
                            }
                            self.mark_session_collecting(&ttc.execution.id).await?;
                            if !self
                                .ask_loop_requires_user(&ttc.execution.id)
                                .await
                                .map_err(|error| error.to_string())?
                            {
                                return Err(format!(
                                    "pipeline clarification lacks durable pending session:{}",
                                    ttc.execution.id
                                ));
                            }

                            // Derive strategy from analysis + consumer_mode guard so
                            // persisted metadata reflects the intended strategy.
                            let (mut pause_strategy, _) =
                                AdaptiveStrategySelector::select_strategy_from_analysis(
                                    &query_analysis,
                                );
                            if self.consumer_mode
                                && pause_strategy != StrategyType::AtomicComposition
                            {
                                pause_strategy = StrategyType::AtomicComposition;
                            }

                            let mut processing_metadata = ProcessingMetadata {
                                total_duration_ms: processing_start.elapsed().as_millis() as u64,
                                strategy_duration_ms: 0,
                                strategy_selected: pause_strategy,
                                processed_at: chrono::Utc::now(),
                                retry_attempts: 0,
                                strategies_attempted: vec![pause_strategy],
                                final_strategy: pause_strategy,
                                current_stage: None,
                                current_provider: None,
                            };
                            processing_metadata.mark_clarification_suspended();

                            pipeline_store
                                .save_store(
                                    &pipeline_scope,
                                    ttc.execution.task_id.as_deref(),
                                    &ttc.execution.id,
                                    &outcome.store,
                                )
                                .await
                                .map_err(|error| {
                                    format!(
                                        "failed to persist suspended V3 pipeline store for {}: {error:?}",
                                        ttc.execution.id
                                    )
                                })?;

                            self
                                .conversation_store
                                .store_strategy_attempts(
                                    &ttc.execution.id,
                                    &ttc.user_turn.id,
                                    Vec::new(),
                                    processing_metadata,
                                    None,
                                )
                                .await
                                .map_err(|error| {
                                    format!(
                                        "failed to persist pending clarification receipt for {}: {error}",
                                        ttc.execution.id
                                    )
                                })?;

                            return Ok(StrategyProcessingResult::for_non_pipeline_exit(
                                query,
                                &execution_context.principal,
                                &execution_context.workspace,
                                &ttc.execution.id,
                                query_analysis.clone(),
                                analysis_metadata.clone(),
                                processing_start,
                                recommended_questions
                                    .iter()
                                    .map(RecommendedQuestion::from)
                                    .collect(),
                                clarified_task,
                                slot_graph_records,
                                // Use the already-extracted local: the pipeline may have
                                // produced a PlanGraph before suspending for elicitation.
                                plan_graph_artifact_id,
                                self.consumer_mode,
                            ));
                        },
                        Err(err) => {
                            return Err(format!(
                                "failed to durably dispatch pipeline questions for {}: {err}",
                                ttc.execution.id
                            ));
                        },
                    }
                }
            } else if !recommended_questions.is_empty() {
                if let Err(error) = pipeline_store
                    .save_store(
                        &pipeline_scope,
                        ttc.execution.task_id.as_deref(),
                        &ttc.execution.id,
                        &outcome.store,
                    )
                    .await
                {
                    warn!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Failed to persist suspended V3 pipeline store (no ask-loop) for {}: {:?}",
                        ttc.execution.id, error
                    );
                }
                return Err(format!(
                    "Clarification required but Ask Loop API unavailable for execution {}",
                    ttc.execution.id
                ));
            }
            // Fall through: no questions or dispatch failed.
        }

        // ────────────────────────────────────────────────────────────────────────
        // Completed path — build ExplorationResult from the PlanGraph.
        // ────────────────────────────────────────────────────────────────────────

        // Persist enriched query (clarified task) if the pipeline produced one.
        if let Some(ref ct) = clarified_task {
            if !ct.clarified_task.is_empty() {
                if let Err(err) = self
                    .state_tracker
                    .store_enriched_query(
                        &ttc.execution.id,
                        &ttc.user_turn.id,
                        ct.clarified_task.clone(),
                    )
                    .await
                {
                    warn!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Failed to persist enriched query for {}: {}",
                        ttc.execution.id, err
                    );
                }
            }
        }

        // Update the in-memory slot graph cache.
        if let Some(ref er) = pipeline_elicitation {
            let cache_snapshot = Self::snapshot_from_elicitation(&ttc.execution.id, er);
            let cache_diff = self
                .slot_graph_cache
                .store(&ttc.execution.id, cache_snapshot);
            if !cache_diff.is_noop() {
                self.emit_slot_graph_diff(
                    &ttc.execution.id,
                    "pipeline_planning",
                    &cache_diff,
                    slot_graph_records.len(),
                );
            }
        }

        // P5.5-E: If the pipeline suspended but fell through to here (empty question
        // list, or dispatch failure), save the store so the SlotGraph/ElicitationResult
        // are available on the next continuation turn.
        if let Err(error) = pipeline_store
            .save_store(
                &pipeline_scope,
                ttc.execution.task_id.as_deref(),
                &ttc.execution.id,
                &outcome.store,
            )
            .await
        {
            if pipeline_was_suspended {
                warn!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Failed to persist suspended V3 pipeline store (dispatch fall-through) for {}: {:?}",
                    ttc.execution.id, error
                );
            } else {
                warn!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Failed to persist V3 pipeline store for {}: {:?}",
                    ttc.execution.id, error
                );
            }
        }

        // Non-task intents (StatusResponse, Cancelled, etc.) complete the pipeline
        // without producing a PlanGraph. Return early with the analysis result.
        if !intent_classification.requires_pipeline {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Non-task intent {:?} — returning early from pipeline",
                intent_classification.intent
            );
            // This exact turn mutation is the durable completion receipt used
            // by accepted-launch recovery. No PlanGraph is expected, but an
            // acknowledged restart must not rerun classification indefinitely
            // if the process dies before the outer intent is consumed.
            self.conversation_store
                .store_strategy_attempts(
                    &ttc.execution.id,
                    &ttc.user_turn.id,
                    Vec::new(),
                    ProcessingMetadata {
                        total_duration_ms: processing_start.elapsed().as_millis() as u64,
                        strategy_duration_ms: pipeline_duration.as_millis() as u64,
                        strategy_selected: StrategyType::AtomicComposition,
                        processed_at: chrono::Utc::now(),
                        retry_attempts: 0,
                        strategies_attempted: Vec::new(),
                        final_strategy: StrategyType::AtomicComposition,
                        current_stage: None,
                        current_provider: None,
                    },
                    None,
                )
                .await
                .map_err(|error| {
                    format!("failed to persist non-task processing receipt: {error}")
                })?;
            self.converge_non_task_processing_receipt(&ttc.execution.id)
                .await?;
            return Ok(StrategyProcessingResult::for_non_pipeline_exit(
                query,
                &execution_context.principal,
                &execution_context.workspace,
                &ttc.execution.id,
                query_analysis,
                analysis_metadata,
                processing_start,
                Vec::new(),
                None,
                Vec::new(),
                plan_graph_artifact_id,
                self.consumer_mode,
            ));
        }

        let plan_graph = outcome.plan_graph.ok_or_else(|| {
            if pipeline_was_suspended {
                format!(
                    "Clarification required for execution {} but question dispatch failed",
                    ttc.execution.id
                )
            } else {
                format!(
                    "Planning pipeline completed but produced no PlanGraph for execution {}",
                    ttc.execution.id
                )
            }
        })?;

        let total_duration = processing_start.elapsed();
        // Derive strategy from the pipeline's query analysis + consumer_mode guard.
        let (mut final_strategy, _) =
            AdaptiveStrategySelector::select_strategy_from_analysis(&query_analysis);
        if self.consumer_mode && final_strategy != StrategyType::AtomicComposition {
            final_strategy = StrategyType::AtomicComposition;
        }

        // Build a minimal ExplorationResult that carries the PlanGraph.
        let exploration_result = {
            use crate::magician_v2::strategy::{
                ExplorationNode, ExplorationResult, ParameterStatistics, ResourceUsage,
                StrategyMetadata, TaskContext,
            };
            use std::collections::HashMap as HM;

            let root_node = ExplorationNode {
                id: "pipeline-root".to_string(),
                task: query.to_string(),
                tool_match: None,
                confidence: 1.0,
                visits: 1,
                value: 1.0,
                depth: 0,
                categories: vec![],
                is_terminal: true,
                analysis: None,
                task_context: TaskContext {
                    root_task: query.to_string(),
                    task_path: vec![query.to_string()],
                    parent_context: String::new(),
                    relevant_categories: vec![],
                    parent_metadata: HM::new(),
                },
                dependencies: vec![],
                priority: 1.0,
                extracted_parameters: HM::new(),
                inherited_parameters: HM::new(),
                available_parameters: HM::new(),
                partial_plan: None,
                parent_id: None,
                children: vec![],
            };

            ExplorationResult {
                root_node: root_node.clone(),
                all_nodes: {
                    let mut m = HM::new();
                    m.insert("pipeline-root".to_string(), root_node);
                    m
                },
                best_path: vec!["pipeline-root".to_string()],
                confidence: 1.0,
                plan: Some(plan_graph.clone()),
                resources_consumed: ResourceUsage {
                    llm_calls: 0,
                    time_ms: pipeline_duration.as_millis() as u64,
                    tokens: 0,
                },
                strategy_metadata: StrategyMetadata {
                    strategy_type: final_strategy,
                    iterations: 1,
                    nodes_explored: 1,
                    max_depth: 0,
                    completed: true,
                    termination_reason: Some("Planning pipeline completed".to_string()),
                },
                parameter_statistics: ParameterStatistics::default(),
            }
        };

        let confidence = exploration_result.confidence;

        // ── I-03: ResponseKind dispatch ──────────────────────────────────────────
        let response_override: Option<serde_json::Value> = plan_graph.response_contract.as_ref().and_then(|contract| {
            use crate::magician_v2::strategy::plan::ResponseKind;
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] response_contract: kind={:?}, terminal_step={:?}",
                contract.kind,
                contract.terminal_step
            );
            match &contract.kind {
                ResponseKind::Silent => {
                    tracing::debug!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Silent response contract — returning status ack"
                    );
                    Some(serde_json::json!({"status": "ok"}))
                }
                ResponseKind::Text => {
                    debug!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Text response contracts are resolved after direct execution; planning output falls back to Action"
                    );
                    None
                }
                ResponseKind::SpawnTask => {
                    let sub_goal = contract.terminal_step.as_deref().unwrap_or("<unknown>");
                    warn!(
                        "[MAGICIAN-V2-ORCHESTRATOR] SpawnTask response contract — no agent_runtime available, sub_goal={}, falling back to Action",
                        sub_goal
                    );
                    None
                }
                ResponseKind::Action | ResponseKind::Composite => None,
            }
        });

        // Record the atomic plan snapshot (triggers confidence checks / budget gates).
        let prompt_identity = parse_prompt_identity_metadata(&execution_context.metadata);
        self.record_atomic_plan_snapshot(
            &ttc.execution.id,
            plan_graph.clone(),
            confidence,
            &exploration_result.resources_consumed,
            prompt_identity,
        )
        .await
        .map_err(|error| {
            format!("Failed to persist atomic plan snapshot before planning handoff: {error}")
        })?;

        let result = StrategyProcessingResult {
            query: query.to_string(),
            principal: execution_context.principal.clone(),
            workspace: execution_context.workspace.clone(),
            query_analysis: query_analysis.clone(),
            selected_strategy: final_strategy,
            exploration_result,
            clarified_task,
            slot_graph: slot_graph_records,
            recommended_questions: Vec::new(),
            analysis_metadata: analysis_metadata.clone(),
            processing_metadata: ProcessingMetadata {
                total_duration_ms: total_duration.as_millis() as u64,
                strategy_duration_ms: pipeline_duration.as_millis() as u64,
                strategy_selected: final_strategy,
                processed_at: chrono::Utc::now(),
                retry_attempts: 0,
                strategies_attempted: vec![final_strategy],
                final_strategy,
                current_stage: None,
                current_provider: None,
            },
            response_override,
            execution_id: ttc.execution.id.clone(),
            plan_graph_artifact_id,
        };

        let strategy_attempt = StrategyAttempt {
            strategy_type: final_strategy,
            exploration_result: result.exploration_result.clone(),
            attempt_number: 1,
            failure_reason: None,
            resources_used: result.exploration_result.resources_consumed.clone(),
            attempted_at: chrono::Utc::now().timestamp_millis(),
        };

        // Persist the completed pipeline attempt. Task-plan refresh consumes the
        // plan from turn storage as the canonical handoff.
        self.conversation_store
            .store_strategy_attempts(
                &ttc.execution.id,
                &ttc.user_turn.id,
                vec![strategy_attempt],
                result.processing_metadata.clone(),
                None,
            )
            .await
            .map_err(|e| format!("Failed to store strategy attempts: {}", e))?;

        info!(
            "[MAGICIAN-V2-ORCHESTRATOR] Planning pipeline completed: strategy={:?}, \
             confidence={:.3}, pipeline={}ms, total={}ms",
            final_strategy,
            confidence,
            pipeline_duration.as_millis(),
            total_duration.as_millis(),
        );

        // Every canonical root is born in the durable Planning dormancy state.
        // A dedicated plan-only execution stops at PlanningComplete; ordinary
        // planning roots continue into their PlanGraph. The Runnable arm is a
        // narrow compatibility path for a fresh delegated/legacy shell whose
        // process-local creation identity is still present.
        let planning_only = execution_context
            .metadata
            .get("planning_only")
            .is_some_and(|value| value == "true");
        let current = self
            .conversation_store
            .get_execution(&ttc.execution.id)
            .await
            .map_err(|error| format!("failed to reload planned execution: {error}"))?;
        match current.waiting_state {
            WaitingState::Planning => {
                let next = self
                    .transition_status_from_runtime(
                        &ttc.execution.id,
                        WorkflowEvent::ReadyToExecute,
                    )
                    .await?;
                if next != WaitingState::PlanningComplete {
                    return Err(format!(
                        "planned execution {} entered unexpected state {next:?}",
                        ttc.execution.id
                    ));
                }
            },
            WaitingState::Runnable
                if !planning_only && self.has_server_owned_fresh_launch_identity(&current) => {},
            state => {
                return Err(format!(
                    "planned execution {} cannot hand off from {state:?}",
                    ttc.execution.id
                ))
            },
        }

        if !planning_only {
            self.execute_plan_graph(
                &ttc.execution.id,
                &plan_graph,
                ttc.execution.task_id.as_deref(),
            )
            .await?;
        }

        // Emit MessageCompleted event.
        if let Some(broadcaster) = &self.event_broadcaster {
            broadcaster.message_completed(
                &ttc.execution.id,
                &ttc.user_turn.id,
                &ttc.correlation_id,
                format!("Strategy processing completed with {:?}", final_strategy),
                Some(&result.exploration_result),
            );
        }

        Ok(result)
    }

    async fn cleanup_answered_metadata(
        &self,
        workflow_id: &str,
        turn: &mut V2Turn,
        question_id: &str,
    ) {
        let mut updated_metadata = false;
        let mut filtered = turn.recommended_questions.clone().unwrap_or_default();

        let before_len = filtered.len();
        filtered.retain(|question| question.id != question_id);
        if before_len != filtered.len() {
            updated_metadata = true;
            turn.recommended_questions = if filtered.is_empty() {
                None
            } else {
                Some(filtered.clone())
            };
        }

        // Phase 5: pending_clarification cleanup removed - now tracked in ClarificationSession

        if updated_metadata {
            if let Some(processing_metadata) = turn.processing_metadata.clone() {
                if let Err(err) = self
                    .conversation_store
                    .store_strategy_attempts(
                        workflow_id,
                        &turn.id,
                        turn.strategy_attempts.clone(),
                        processing_metadata,
                        turn.recommended_questions.clone(),
                    )
                    .await
                {
                    warn!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Failed to persist clarification cleanup for {} ({}): {}",
                        workflow_id, question_id, err
                    );
                }
            } else {
                warn!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Missing processing metadata while cleaning answered clarification for {} ({}); skipping persistence",
                    workflow_id, question_id
                );
            }
        }
    }

    /// Restore questions from storage into the in-memory clarifier cache.
    /// Called when accessing an existing execution to restore question state after
    /// page refresh or server restart.
    async fn restore_execution_questions(&self, execution_id: &str) {
        // Only restore if ask_loop_api is available
        let Some(ask_loop_api) = &self.ask_loop_api else {
            return;
        };

        // Load the latest turn from storage
        let turns = match self.conversation_store.get_turns(execution_id).await {
            Ok(turns) => turns,
            Err(e) => {
                if e.to_string().contains("Execution not found") {
                    debug!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Skipping question restoration for missing execution {}: {}",
                        execution_id, e
                    );
                    return;
                }
                warn!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Failed to load turns for question restoration: {}",
                    e
                );
                return;
            },
        };

        // Find the most recent turn with recommended questions
        if let Some(latest_turn) = turns.iter().rev().find(|t| {
            t.recommended_questions
                .as_ref()
                .is_some_and(|q| !q.is_empty())
        }) {
            if let Some(questions) = &latest_turn.recommended_questions {
                let mut to_restore = questions.clone();
                let mut filtered_out = 0usize;
                let mut filtered_ids: Vec<String> = Vec::new();

                let manager = ask_loop_api.session_manager();
                match manager.load(execution_id).await {
                    Ok(Some(session)) => {
                        let answered: HashSet<String> = session
                            .pending_questions
                            .iter()
                            .filter(|q| q.status == SessionQuestionStatus::Answered)
                            .map(|q| q.id.clone())
                            .collect();

                        if !answered.is_empty() {
                            let before = to_restore.len();
                            to_restore.retain(|question| {
                                let keep = !answered.contains(&question.id);
                                if !keep {
                                    filtered_ids.push(question.id.clone());
                                }
                                keep
                            });
                            filtered_out = before.saturating_sub(to_restore.len());
                        }
                    },
                    Ok(None) => {
                        debug!(
                            "[MAGICIAN-V2-ORCHESTRATOR] No clarification session found while restoring questions for {}",
                            execution_id
                        );
                    },
                    Err(err) => {
                        warn!(
                            "[MAGICIAN-V2-ORCHESTRATOR] Failed to load session while restoring questions for {}: {}",
                            execution_id, err
                        );
                    },
                }

                if to_restore.is_empty() {
                    info!(
                        "[MAGICIAN-V2-ORCHESTRATOR] No unanswered questions to restore for execution {} (filtered {})",
                        execution_id, filtered_out
                    );
                    return;
                }

                if filtered_out > 0 {
                    info!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Restoring {} questions for execution {} (filtered answered: {:?})",
                        to_restore.len(),
                        execution_id,
                        filtered_ids
                    );
                } else {
                    info!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Restoring {} questions for execution {}",
                        to_restore.len(),
                        execution_id
                    );
                }

                let pause_manager = ask_loop_api.pause_manager();
                for question in &to_restore {
                    if let Err(e) = pause_manager
                        .pause(
                            execution_id,
                            crate::magician_v2::ask_loop::pause::PauseReason::WaitingOnUser(
                                question.id.clone(),
                            ),
                        )
                        .await
                    {
                        warn!(
                            "[MAGICIAN-V2-ORCHESTRATOR] Failed to restore paused state for question {}: {}",
                            question.id, e
                        );
                    } else {
                        debug!(
                            "[MAGICIAN-V2-ORCHESTRATOR] Restored paused workflow for question {}",
                            question.id
                        );
                    }
                }
            }
        }
    }

    /// Handle a resume notification from the Ask Loop and restart planning.
    ///
    /// Behavior depends on resume_mode:
    /// - LightSlotUpdate: Update slots only, no replanning (cost-effective for incomplete batches)
    /// - PartialReplan: Incremental plan refinement with current answers
    /// - FullReplan: Complete replanning cycle (batch complete or single question)
    pub async fn resume_workflow(&self, notification: ResumeNotification) -> Result<(), String> {
        self.resume_workflow_inner(notification, true).await
    }

    async fn resume_workflow_inner(
        &self,
        notification: ResumeNotification,
        publish_ready: bool,
    ) -> Result<(), String> {
        let workflow_id = notification.workflow_id.clone();
        let resume_mode = if notification.resume_mode == ResumeMode::LightSlotUpdate
            && notification.pending_count == 0
        {
            ResumeMode::FullReplan
        } else {
            notification.resume_mode
        };

        info!(
            "[MAGICIAN-V2-ORCHESTRATOR] 📋 Resume workflow invoked: workflow={} mode={:?}",
            workflow_id, resume_mode
        );

        info!(
            "[MAGICIAN-V2-ORCHESTRATOR] Resume workflow {} with mode {:?}",
            workflow_id, resume_mode
        );

        self.ensure_initialized()?;

        // Handle LightSlotUpdate mode: just update slots without replanning
        if resume_mode == ResumeMode::LightSlotUpdate {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Light slot update for {} - skipping replanning (cost optimization)",
                workflow_id
            );

            if notification.pending_count == 0
                || !self
                    .ask_loop_requires_user(&workflow_id)
                    .await
                    .map_err(|error| error.to_string())?
            {
                return Err(format!(
                    "light_slot_update_without_durable_pending_questions:{workflow_id}"
                ));
            }
            let state = self.get_execution_status(&workflow_id).await?;
            if !matches!(state, WaitingState::WaitingUser | WaitingState::Paused) {
                return Err(format!(
                    "light_slot_update_has_unexpected_state:{state:?}:{workflow_id}"
                ));
            }

            // Emit workflow resumed event
            if let Some(broadcaster) = &self.event_broadcaster {
                broadcaster.workflow_resumed(
                    &workflow_id,
                    notification.question_id.clone(),
                    format!("{:?}", notification.resume_mode),
                    notification.answered_count,
                    notification.pending_count,
                );
            }

            // Return early - no replanning needed for light updates
            // Slots have already been updated in the pause_manager.resume() call
            self.mark_session_collecting(&workflow_id).await?;
            return Ok(());
        }

        // For PartialReplan and FullReplan, continue with planning logic
        info!(
            "[MAGICIAN-V2-ORCHESTRATOR] Triggering {} for workflow {}",
            if resume_mode == ResumeMode::PartialReplan {
                "partial replan"
            } else {
                "full replan"
            },
            workflow_id
        );

        if self
            .ask_loop_requires_user(&workflow_id)
            .await
            .map_err(|error| error.to_string())?
        {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Clarification session still collecting answers for {}; deferring replanning",
                workflow_id
            );
            self.mark_session_collecting(&workflow_id).await?;
            return Ok(());
        }

        self.transition_status_from_runtime(&workflow_id, WorkflowEvent::UserResumed)
            .await?;

        let execution = self
            .conversation_store
            .get_execution(&workflow_id)
            .await
            .map_err(|e| format!("Failed to load execution during resume: {}", e))?;
        Self::ensure_planning_backed_execution(&execution)?;

        let (analysis, _metadata, turn_id) =
            match self.get_latest_turn_analysis(&workflow_id).await? {
                Some(data) => data,
                None => {
                    warn!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Resume triggered for {} but no analysis found",
                        workflow_id
                    );
                    self.mark_session_collecting(&workflow_id).await?;
                    return Ok(());
                },
            };

        let mut turn = self
            .conversation_store
            .get_turn(&workflow_id, &turn_id)
            .await
            .map_err(|e| format!("Failed to load turn for resume: {}", e))?;

        if let Some(question_id) = notification.question_id.as_ref() {
            self.cleanup_answered_metadata(&workflow_id, &mut turn, question_id)
                .await;
        }

        let query = turn.text.clone();

        let execution_context = ExecutionContext {
            principal: execution.principal.clone(),
            workspace: execution.workspace.clone(),
            metadata: HashMap::new(),
        };
        // P5-06: extract strategy_override before execution_context is moved into
        // create_strategy_context.  The metadata is empty here (resume_workflow is a
        // user-reply path), but the wiring is present for future per-turn agent metadata.
        let resume_strategy_override = execution_context
            .metadata
            .get("agent:strategy_override")
            .and_then(|name| parse_agent_strategy_type(name));

        let resume_policy = StageResumePolicy::from_state(&notification.resumed_state);
        let tracker = StateTracker::with_confidence_service(
            self.conversation_store.clone(),
            self.confidence_service.clone(),
        );
        let mut reused_stage_names: Vec<String> = Vec::new();
        let mut mark_reused = |stage: &str| {
            if !reused_stage_names.iter().any(|existing| existing == stage) {
                reused_stage_names.push(stage.to_string());
            }
        };

        let mut clarified_task: Option<ClarifiedTask> = None;
        let (resume_snapshot, mut slot_diff_total) = self
            .load_slot_graph_with_updates(&workflow_id, &notification.slots)
            .await?;
        if !slot_diff_total.is_noop() {
            self.emit_slot_graph_diff(
                &workflow_id,
                "clarification_merge",
                &slot_diff_total,
                resume_snapshot.slots.len(),
            );
        }
        let _resume_conversation_context = Self::context_from_slots(&resume_snapshot.slots);
        let mut slot_graph_records: Vec<SlotRecord> = resume_snapshot.slots.clone();

        let mut planning_snapshot = self
            .build_planning_snapshot(&workflow_id)
            .await
            .map_err(|e| format!("Failed to load planning snapshot: {}", e))?;
        let failed_stage = notification.resumed_state.failed_stage.clone();
        let resume_stage_name = failed_stage.as_ref().map(|info| info.stage_name.clone());
        let resume_stage_context = failed_stage
            .as_ref()
            .map(|info| info.stage_context)
            .filter(|ctx| *ctx != StageContext::Unknown)
            .unwrap_or(notification.resumed_state.stage_context);
        let resume_checkpoint = resume_stage_name.as_ref().and_then(|name| {
            notification
                .resumed_state
                .completed_stages
                .iter()
                .rev()
                .find(|cp| &cp.stage_name == name)
        });

        if let Some(failed) = failed_stage.as_ref() {
            debug!(
                "[MAGICIAN-V2-ORCHESTRATOR] Resume triggered for {} from stage '{}' ({:?}) \
                 retry={}",
                workflow_id, failed.stage_name, failed.stage_context, failed.retry_count
            );
        } else {
            debug!(
                "[MAGICIAN-V2-ORCHESTRATOR] Resume triggered for {} without recorded failed stage",
                workflow_id
            );
        }

        if let Some(checkpoint) = resume_checkpoint {
            let output_hint = match &checkpoint.outputs {
                serde_json::Value::Object(map) => format!("object fields={}", map.len()),
                serde_json::Value::Array(items) => format!("array items={}", items.len()),
                serde_json::Value::Null => "empty".to_string(),
                _ => "scalar".to_string(),
            };
            debug!(
                "[MAGICIAN-V2-ORCHESTRATOR] Found checkpoint '{}'{:?} ({})",
                checkpoint.stage_name, checkpoint.stage_context, output_hint
            );
        }

        let resume_checkpoint_hash = resume_checkpoint.and_then(|checkpoint| {
            if checkpoint.outputs.is_null() {
                None
            } else {
                crate::magician_v2::json_traversal::json_blake3_hex(&checkpoint.outputs).ok()
            }
        });

        if matches!(analysis.intent, QueryIntent::NewTask) {
            // Part 3D: Check if we have an enriched query from batch answer consolidation
            // If batch questions were answered, we use the enriched query that incorporates
            // all answers, bypassing stale elicitation results
            let query_for_planning = self
                .state_tracker
                .load_enriched_query(&workflow_id)
                .await
                .ok()
                .flatten()
                .unwrap_or_else(|| query.clone());

            let has_enriched_query = query_for_planning != query;

            info!("[ORCHESTRATOR] === QUERY CONTEXT ===");
            info!("[ORCHESTRATOR] Customer query: '{}'", query);
            if has_enriched_query {
                info!("[ORCHESTRATOR] Enriched query: '{}'", query_for_planning);
            } else {
                info!("[ORCHESTRATOR] Enriched query: <not available>");
            }
            info!(
                "[ORCHESTRATOR] Query for planning: '{}'",
                query_for_planning
            );
            info!("[ORCHESTRATOR] =======================");

            // FIX: Transition stage context after batch enrichment to prevent checkpoint reuse
            // When enriched query exists (from batch answer consolidation), we transition from
            // PlanningBootstrap to PlanningIteration. This ensures the composite checkpoint key
            // changes, forcing fresh elicitation with the enriched context instead of reusing
            // stale checkpoints from the initial bootstrap phase.
            let _resume_stage_context =
                if has_enriched_query && resume_stage_context == StageContext::PlanningBootstrap {
                    info!("[ORCHESTRATOR] === STAGE CONTEXT TRANSITION ===");
                    info!("[ORCHESTRATOR] Batch enrichment detected - transitioning stage context");
                    info!(
                        "[ORCHESTRATOR] From: {:?} → To: PlanningIteration",
                        resume_stage_context
                    );
                    info!("[ORCHESTRATOR] This will force fresh elicitation with enriched query");
                    info!("[ORCHESTRATOR] ===================================");
                    StageContext::PlanningIteration
                } else {
                    resume_stage_context
                };

            // A-03: If a PipelineSuspension checkpoint exists, use
            // PlanningOrchestrator::from_suspension() to resume the pipeline instead of
            // calling elicitation_service.elicit_and_rewrite() (the pre-pipeline path).
            let pipeline_suspension: Option<
                crate::magician_v2::pipeline::orchestrator::PipelineSuspension,
            > = notification
                .resumed_state
                .completed_stages
                .iter()
                .rev()
                .find(|cp| cp.stage_name == "planning.pipeline.suspended")
                .and_then(|cp| {
                    crate::magician_v2::json_traversal::deserialize_json_bounded(
                        &cp.outputs,
                        1_000_000,
                        crate::magician_v2::json_traversal::MAX_RETAINED_JSON_DEPTH,
                    )
                    .ok()
                });

            let elicitation_result_opt: Option<
                crate::magician_v2::slot_graph::elicitation::ElicitationResult,
            > = if let Some(suspension) = pipeline_suspension {
                info!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Found PipelineSuspension checkpoint for {}; \
                     resuming via PlanningOrchestrator::from_suspension()",
                    workflow_id
                );
                let user_answer_text = notification
                    .slots
                    .first()
                    .map(|s| {
                        s.value
                            .as_str()
                            .map(str::to_string)
                            .unwrap_or_else(|| s.value.to_string())
                    })
                    .unwrap_or_default();

                let resume_mode_str = match resume_mode {
                    ResumeMode::LightSlotUpdate => "light_slot_update",
                    ResumeMode::PartialReplan => "partial_replan",
                    ResumeMode::FullReplan => "full_replan",
                }
                .to_string();

                let planner_backend =
                    std::sync::Arc::new(MagicianPlannerBackend::new(self.weak_self.clone()));
                // Resume path: no routing/temperature overrides, but pass execution_context for IntentClassifierAgent.
                let pipeline_agents =
                    self.build_pipeline_agents(planner_backend, None, None, &execution_context);
                let agent_ids: Vec<String> = pipeline_agents.keys().cloned().collect();
                let pipeline_router = std::sync::Arc::new(
                    crate::magician_v2::pipeline::router::TieredRouter::new(None, agent_ids),
                );
                let pipeline_pause_manager =
                    self.ask_loop_api.as_ref().map(|api| api.pause_manager());

                let mut pipeline_orch =
                    crate::magician_v2::pipeline::orchestrator::PlanningOrchestrator::from_suspension(
                        suspension,
                        pipeline_agents,
                        pipeline_router,
                        user_answer_text,
                        resume_mode_str,
                        PIPELINE_MAX_ITERATIONS,
                        pipeline_pause_manager,
                    );

                // M7: wire event broadcaster for pipeline lifecycle events
                if let Some(ref eb) = self.event_broadcaster {
                    pipeline_orch.set_event_broadcaster(Arc::clone(eb));
                }

                match pipeline_orch.run().await {
                    Ok(outcome) => {
                        use crate::magician_v2::pipeline::artifact::ArtifactType as PipelineAT;
                        use crate::magician_v2::slot_graph::elicitation::ElicitationResult as PipelineER;
                        outcome
                            .store
                            .latest_of_type(&PipelineAT::ElicitationResult)
                            .and_then(|a| a.deserialize_content::<PipelineER>().ok())
                    },
                    Err(e) => {
                        // I-04: The plan doc (Task A-03) explicitly prohibits falling back to
                        // elicitation_service.elicit_and_rewrite() on pipeline error.
                        // The old pre-pipeline elicitation path is architecturally retired;
                        // surface the failure as a hard error instead of silently degrading.
                        return Err(format!(
                            "Pipeline resume failed for {}: {}; \
                             refusing to fall back to retired elicitation path (A-03)",
                            workflow_id, e
                        ));
                    },
                }
            } else {
                None
            };

            let elicitation = if let Some(er) = elicitation_result_opt {
                er
            } else {
                return Err(format!(
                    "Pipeline resume for {} produced no ElicitationResult and no suspension \
                     checkpoint was found; refusing to fall back to retired elicitation path (A-03)",
                    workflow_id
                ));
            };

            slot_graph_records = elicitation.slot_graph.clone();
            let cache_snapshot = Self::snapshot_from_elicitation(&workflow_id, &elicitation);
            let cache_diff = self.slot_graph_cache.store(&workflow_id, cache_snapshot);
            if !cache_diff.is_noop() {
                self.emit_slot_graph_diff(
                    &workflow_id,
                    "elicitation_resume",
                    &cache_diff,
                    slot_graph_records.len(),
                );
            }
            slot_diff_total = Self::accumulate_slot_diffs(slot_diff_total, cache_diff);
            if !elicitation.clarified_task.clarified_task.is_empty() {
                clarified_task = Some(elicitation.clarified_task.clone());

                if let Err(err) = self
                    .state_tracker
                    .store_enriched_query(
                        &workflow_id,
                        &turn_id,
                        elicitation.clarified_task.clarified_task.clone(),
                    )
                    .await
                {
                    warn!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Failed to persist enriched query during resume for {}: {}",
                        workflow_id, err
                    );
                }
            }

            // Phase 5: Check if elicitation generated new questions (Gap #7 fix - simplified)
            // If so, pause and ask them before proceeding to planning
            if !elicitation.recommended_questions.is_empty() {
                // Filter out questions that have already been answered/cancelled based on the session snapshot.
                let mut unanswered_questions = Vec::new();
                let total_questions = elicitation.recommended_questions.len();

                if let Some(ask_api) = self.ask_loop_api.as_ref() {
                    let session_manager = ask_api.session_manager();

                    let mut status_lookup: HashMap<String, SessionQuestionStatus> = HashMap::new();
                    let snapshot = session_manager.load(&workflow_id).await.map_err(|err| {
                        format!(
                            "failed to load clarification session for {}: {}",
                            workflow_id, err
                        )
                    })?;

                    if let Some(snapshot) = snapshot {
                        for question in snapshot.pending_questions {
                            status_lookup.insert(question.id, question.status);
                        }
                    } else {
                        debug!(
                            "[MAGICIAN-ELICITATION-FILTER] No session snapshot available for {}",
                            workflow_id
                        );
                    }

                    for question in &elicitation.recommended_questions {
                        match status_lookup.get(&question.id) {
                            Some(SessionQuestionStatus::Answered) => {
                                info!(
                                    "[MAGICIAN-ELICITATION-FILTER] Skipping already-answered question (session): {}",
                                    question.id
                                );
                            },
                            _ => {
                                unanswered_questions.push(question.clone());
                            },
                        }
                    }

                    let recommended_ids: HashSet<String> = elicitation
                        .recommended_questions
                        .iter()
                        .map(|q| q.id.clone())
                        .collect();

                    let stale_ids: Vec<String> = status_lookup
                        .iter()
                        .filter(|(id, status)| {
                            !recommended_ids.contains(*id)
                                && matches!(
                                    status,
                                    SessionQuestionStatus::WaitingOnUser
                                        | SessionQuestionStatus::Queued
                                )
                        })
                        .map(|(id, _)| id.clone())
                        .collect();

                    if !stale_ids.is_empty() {
                        session_manager
                            .cancel_questions(&workflow_id, &stale_ids)
                            .await
                            .map_err(|err| {
                                format!(
                                    "failed to cancel stale questions for {}: {}",
                                    workflow_id, err
                                )
                            })?;
                    }

                    info!(
                        "[MAGICIAN-ELICITATION-FILTER] Filtered questions: {} total → {} unanswered (filtered out {})",
                        total_questions,
                        unanswered_questions.len(),
                        total_questions - unanswered_questions.len()
                    );
                } else {
                    // No ask API available, use all questions
                    unanswered_questions = elicitation.recommended_questions.clone();
                }

                // Only proceed if there are unanswered questions
                if !unanswered_questions.is_empty() {
                    let low_confidence =
                        elicitation.confidence_summary.overall < LOW_CONFIDENCE_THRESHOLD;

                    if low_confidence {
                        // Phase 6: Check iteration count to prevent infinite loops
                        let current_iteration = *self
                            .elicitation_iterations
                            .entry(workflow_id.clone())
                            .or_insert(0);

                        if current_iteration >= MAX_PLANNING_ELICITATION_ITERATIONS {
                            warn!(
                            "[MAGICIAN-ELICITATION-LOOP] Maximum iteration limit ({}) reached for workflow {} - proceeding to planning despite low confidence ({:.2})",
                            MAX_PLANNING_ELICITATION_ITERATIONS,
                            workflow_id,
                            elicitation.confidence_summary.overall
                        );
                            // Skip question triggering and proceed to planning
                        } else {
                            // Increment iteration counter
                            self.elicitation_iterations
                                .entry(workflow_id.clone())
                                .and_modify(|count| *count += 1)
                                .or_insert(1);

                            info!(
                            "[MAGICIAN-ELICITATION-LOOP] Elicitation iteration {}/{} - generated {} questions with low confidence ({:.2}) - pausing before planning",
                            current_iteration + 1,
                            MAX_PLANNING_ELICITATION_ITERATIONS,
                            unanswered_questions.len(),
                            elicitation.confidence_summary.overall
                        );

                            // Trigger questions via ask loop - this creates the ask-answer-rewrite-plan iteration loop
                            if let Some(ask_api) = self.ask_loop_api.as_ref() {
                                match self
                                    .dispatch_curated_question_batch(
                                        ask_api,
                                        &workflow_id,
                                        &unanswered_questions,
                                        "planning_elicitation_iteration",
                                        Some(current_iteration + 1),
                                        TaskComplexity::Moderate,
                                        None,
                                        None,
                                        None,
                                    )
                                    .await
                                {
                                    Ok((batch_id, batch_total)) => {
                                        info!(
                                            "[MAGICIAN-ELICITATION-LOOP] Question triggered successfully - batch {} (question 1/{}) - workflow paused",
                                            batch_id, batch_total
                                        );
                                        let paused_state = self
                                            .transition_status_from_runtime(
                                                &workflow_id,
                                                WorkflowEvent::UserPaused,
                                            )
                                            .await?;
                                        if !matches!(
                                            paused_state,
                                            WaitingState::WaitingUser | WaitingState::Paused
                                        ) {
                                            return Err(format!(
                                                "resumed clarification entered unexpected state {paused_state:?}:{workflow_id}"
                                            ));
                                        }
                                        self.mark_session_collecting(&workflow_id).await?;
                                        if !self
                                            .ask_loop_requires_user(&workflow_id)
                                            .await
                                            .map_err(|error| error.to_string())?
                                        {
                                            return Err(format!(
                                                "resumed clarification lacks durable pending session:{workflow_id}"
                                            ));
                                        }
                                        return Ok(());
                                    },
                                    Err(err) => {
                                        return Err(format!(
                                            "failed to durably dispatch resumed clarification batch for {workflow_id}: {err}"
                                        ));
                                    },
                                }
                            } else {
                                return Err(format!(
                                    "ask loop unavailable for required resumed clarification:{workflow_id}"
                                ));
                            }
                        }
                    } else {
                        info!(
                        "[MAGICIAN-ELICITATION-LOOP] Questions generated but confidence acceptable ({:.2}) - proceeding",
                        elicitation.confidence_summary.overall
                    );
                    }
                } else {
                    // All questions have been answered - proceed to planning
                    info!(
                        "[MAGICIAN-ELICITATION-FILTER] All {} questions have been answered - proceeding to planning",
                        elicitation.recommended_questions.len()
                    );
                }
            } else {
                info!(
                    "[MAGICIAN-ELICITATION-LOOP] No additional questions needed - confidence={:.2}",
                    elicitation.confidence_summary.overall
                );
            }
        }

        let stage_context = planning_snapshot
            .as_ref()
            .map(|snapshot| {
                if snapshot.stage_context == StageContext::Unknown {
                    resume_stage_context
                } else {
                    snapshot.stage_context
                }
            })
            .unwrap_or(resume_stage_context);
        let stage_context = if stage_context == StageContext::Unknown {
            StageContext::PlanningBootstrap
        } else {
            stage_context
        };

        if let Some(snapshot) = planning_snapshot.as_mut() {
            if snapshot.stage_context == StageContext::Unknown {
                snapshot.stage_context = stage_context;
            }
        }

        let budget_ledger = self.ask_loop_api.as_ref().map(|api| api.budget_ledger());
        if let Some(ledger) = &budget_ledger {
            let ledger_stage_name = format!("{}.ledger_synchronized", stage_context.as_str());
            if resume_policy.should_skip(&ledger_stage_name) {
                debug!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Skipping ledger sync for {} using checkpoint",
                    ledger_stage_name
                );
                mark_reused(ledger_stage_name.as_str());
            } else {
                let complexity_bucket = Self::map_complexity(analysis.complexity.score);
                let mut ledger_synced = true;
                if let Err(err) = ledger.initialize(&workflow_id, complexity_bucket).await {
                    warn!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Failed to initialize ledger during resume: {}",
                        err
                    );
                    ledger_synced = false;
                }

                if let Err(err) = ledger.annotate_stage(&workflow_id, stage_context).await {
                    warn!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Failed to annotate stage context {} during resume: {}",
                        stage_context, err
                    );
                    ledger_synced = false;
                }

                if ledger_synced {
                    if let Err(err) = tracker
                        .append_stage_checkpoint(
                            &workflow_id,
                            stage_context,
                            &ledger_stage_name,
                            serde_json::json!({
                                "stage_context": stage_context.as_str(),
                                "complexity": analysis.complexity.score,
                            }),
                        )
                        .await
                    {
                        warn!(
                            "[MAGICIAN-V2-ORCHESTRATOR] Failed to append ledger checkpoint {}: {}",
                            ledger_stage_name, err
                        );
                    }
                }
            }
        }

        // If clarification answers did not change any slots, skip replanning.
        if slot_diff_total.is_noop() {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] No slot changes detected after clarification for {}; adopting an existing runtime plan or re-driving plan-only composition",
                workflow_id,
            );
            if publish_ready && !workflow_id.starts_with("planexec_") {
                let existing_plan = match self.ask_loop_api.as_ref() {
                    Some(api) => api
                        .get_plan_for_execution(&workflow_id)
                        .await
                        .map_err(|error| error.to_string())?,
                    None => None,
                };
                let plan = existing_plan
                    .filter(|plan| !plan.steps.is_empty())
                    .ok_or_else(|| {
                        format!("resume_has_no_slot_delta_or_durable_plan:{workflow_id}")
                    })?;
                let state = self
                    .transition_status_from_runtime(&workflow_id, WorkflowEvent::ReadyToExecute)
                    .await?;
                if state != WaitingState::PlanningComplete {
                    return Err(format!(
                        "resume existing plan entered unexpected state {state:?}:{workflow_id}"
                    ));
                }
                self.execute_plan_graph(&workflow_id, &plan, execution.task_id.as_deref())
                    .await?;
                return Ok(());
            }
        }

        let resume_stage_label = resume_stage_name
            .clone()
            .unwrap_or_else(|| resume_stage_context.as_str().to_string());
        let context_stage_name = format!("{}.context_rehydrated", stage_context.as_str());
        if resume_policy.should_skip(&context_stage_name) {
            debug!(
                "[MAGICIAN-V2-ORCHESTRATOR] Skipping context rehydration for {} using checkpoint",
                context_stage_name
            );
            mark_reused(context_stage_name.as_str());
        } else if let Err(err) = tracker
            .append_stage_checkpoint(
                &workflow_id,
                stage_context,
                &context_stage_name,
                serde_json::json!({
                    "resume_stage": resume_stage_label.clone(),
                    "failed_stage": failed_stage.as_ref().map(|info| info.stage_name.clone()),
                }),
            )
            .await
        {
            warn!(
                "[MAGICIAN-V2-ORCHESTRATOR] Failed to append context checkpoint {}: {}",
                context_stage_name, err
            );
        }

        let reused_checkpoint = resume_checkpoint.is_some();
        let resume_attempt = failed_stage
            .as_ref()
            .map(|info| info.retry_count.saturating_add(1))
            .unwrap_or(0);
        if let Some(broadcaster) = &self.event_broadcaster {
            broadcaster.workflow_stage_resumed(
                &workflow_id,
                resume_stage_label.clone(),
                stage_context,
                resume_attempt,
                reused_checkpoint,
                resume_checkpoint_hash.clone(),
                reused_stage_names.clone(),
            );
        }

        let correlation_id = format!("resume-{}-{}", workflow_id, Uuid::new_v4());

        let elicitation_manager = match ElicitationManagerBuilder::new(
            self.conversation_store.clone(),
            workflow_id.clone(),
        )
        .with_event_broadcaster(self.event_broadcaster.clone())
        .build()
        .await
        {
            Ok(manager) => Some(Arc::new(manager)),
            Err(err) => {
                return Err(format!(
                    "Failed to initialize elicitation manager on resume for {workflow_id}: {err}"
                ))
            },
        };

        // For resume flow, use LLM calls from analysis (already counted during initial processing)
        let initial_llm_calls = analysis.llm_calls_used;

        let slot_diff_for_context = (!slot_diff_total.is_noop()).then_some(slot_diff_total);
        let resume_prompt_identity = parse_prompt_identity_metadata(&execution_context.metadata);

        // Extract per-agent tools and agent_id for tool filtering.
        let (agent_tools, agent_excluded_tools, agent_denied_tools, resume_agent_id) = self
            .resolve_agent_tool_filters(
                Some(execution.active_owner_agent_id.as_str()),
                Some(execution_context.principal.as_str()),
                Some(execution_context.workspace.as_str()),
            )
            .await;

        // Build delegate tool catalog from the agent's delegation_targets.
        let delegate_tool_catalog = if let Some(ref aid) = resume_agent_id {
            self.build_delegate_tool_catalog_for_scope(
                aid,
                Some(execution_context.principal.as_str()),
                Some(execution_context.workspace.as_str()),
            )
            .await
        } else {
            HashMap::new()
        };
        let planner_agent_catalog = if let Some(ref aid) = resume_agent_id {
            self.build_planner_agent_catalog_for_scope(
                aid,
                Some(execution_context.principal.as_str()),
                Some(execution_context.workspace.as_str()),
            )
            .await
        } else {
            Vec::new()
        };
        // Resolved before the call because `agent_tools` moves into it.
        let available_procedure_skills = self.resolve_available_procedure_skills(
            &agent_tools,
            Some(execution_context.principal.as_str()),
            Some(execution_context.workspace.as_str()),
        );

        let strategy_context = AdaptiveStrategySelector::create_strategy_context(
            analysis.clone(),
            self.tool_catalog.clone(),
            self.tool_matching.clone(),
            Some(execution_context),
            self.llm_service.clone(),
            self.prompt_manager.clone(),
            self.v2_tool_matcher.clone(),
            Some(workflow_id.clone()),
            Some(correlation_id.clone()),
            Some(turn_id.clone()),
            Some(self.conversation_store.clone()),
            self.event_broadcaster.clone(),
            elicitation_manager,
            planning_snapshot,
            stage_context,
            budget_ledger.clone(),
            clarified_task.clone(),
            slot_graph_records.clone(),
            slot_diff_for_context,
            resume_policy.clone(),
            initial_llm_calls,        // Pass LLM calls from analysis
            self.allow_consent_slots, // Pass consent slots flag from config
            agent_tools,
            agent_excluded_tools,
            agent_denied_tools,
            delegate_tool_catalog,
            planner_agent_catalog,
            available_procedure_skills,
        );

        let (mut initial_strategy, params) =
            AdaptiveStrategySelector::select_strategy_from_analysis(&analysis);
        let guided_params = params;
        // P5-06: apply per-agent strategy override when present in the execution context.
        if let Some(override_type) = resume_strategy_override {
            initial_strategy = override_type;
        }

        if matches!(
            notification.blocker_type,
            Some(BlockerType::LowConfidenceSlot)
        ) || matches!(
            notification.stage,
            StageContext::PlanningIteration | StageContext::ExecutionCycle
        ) {
            initial_strategy = StrategyType::AtomicComposition;
        }

        // consumer_mode guard: force AtomicComposition regardless of overrides
        if self.consumer_mode && initial_strategy != StrategyType::AtomicComposition {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Consumer mode — overriding {:?} → AtomicComposition",
                initial_strategy
            );
            initial_strategy = StrategyType::AtomicComposition;
        }

        if let Some(broadcaster) = &self.event_broadcaster {
            broadcaster.strategy_selected(
                &workflow_id,
                &correlation_id,
                initial_strategy,
                analysis.complexity.score as f64,
                "Auto-resume after clarification".to_string(),
            );
        }

        let processing_start = std::time::Instant::now();
        let strategy_start = std::time::Instant::now();

        let (
            exploration_result,
            final_strategy,
            strategies_attempted,
            all_attempts,
            retry_attempts,
        ) = match self
            .execute_strategy_with_retry(initial_strategy, guided_params, &strategy_context, &query)
            .await
        {
            Ok(result) => result,
            Err(err) => {
                warn!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Resume processing failed for {}: {}",
                    workflow_id, err
                );
                return Err(err.to_string());
            },
        };

        let strategy_duration = strategy_start.elapsed();
        let total_duration = processing_start.elapsed();
        let confidence = exploration_result.confidence;

        let resumed_plan_graph = exploration_result.plan.clone().ok_or_else(|| {
            format!("resume strategy completed without an executable PlanGraph:{workflow_id}")
        })?;
        self.record_atomic_plan_snapshot(
            &workflow_id,
            resumed_plan_graph,
            confidence,
            &exploration_result.resources_consumed,
            resume_prompt_identity.clone(),
        )
        .await
        .map_err(|error| {
            format!("Failed to persist atomic plan snapshot before resume handoff: {error}")
        })?;

        let processing_metadata = ProcessingMetadata {
            total_duration_ms: total_duration.as_millis() as u64,
            strategy_duration_ms: strategy_duration.as_millis() as u64,
            strategy_selected: initial_strategy,
            processed_at: chrono::Utc::now(),
            retry_attempts,
            strategies_attempted: strategies_attempted.clone(),
            final_strategy,
            current_stage: None,
            current_provider: None,
        };

        self.conversation_store
            .store_strategy_attempts(
                &workflow_id,
                &turn_id,
                all_attempts,
                processing_metadata.clone(),
                None, // No new questions in resume path (user already answered)
            )
            .await
            .map_err(|e| format!("Failed to store strategy attempts after resume: {}", e))?;

        // Publish Ready only after both the canonical snapshot and the
        // successful completed strategy attempt are durable. A receipt owner
        // that dies during provider work therefore leaves Runtime in Planning
        // and can safely re-drive; PlanningComplete always names an adoptable
        // persisted PlanGraph.
        if publish_ready {
            let ready_state = self
                .transition_status_from_runtime(&workflow_id, WorkflowEvent::ReadyToExecute)
                .await?;
            if ready_state != WaitingState::PlanningComplete {
                return Err(format!(
                    "resume planning entered unexpected state {ready_state:?}:{workflow_id}"
                ));
            }
        }

        if let Some(broadcaster) = &self.event_broadcaster {
            broadcaster.message_completed(
                &workflow_id,
                &turn_id,
                &correlation_id,
                format!("Resume processing completed with {:?}", final_strategy),
                Some(&exploration_result),
            );
        }

        self.mark_session_collecting(&workflow_id).await?;
        Ok(())
    }

    /// Advance the exact source WaitingUser/Paused Runtime generation owned by
    /// a sealed resume receipt. The status-revision CAS prevents a stale
    /// rolling peer from consuming a newer pause that happens to have the same
    /// enum value.
    pub(crate) async fn advance_runtime_resume_source_generation(
        &self,
        execution_id: &str,
        expected_status_revision: u64,
    ) -> Result<RuntimeResumeSourceAdvance, String> {
        let status_lock = self
            .execution_status_locks
            .entry(execution_id.to_owned())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone();
        let guard = status_lock.lock().await;
        let (execution, revision) = self
            .load_execution_with_status_revision_unlocked(execution_id)
            .await?;
        if revision > expected_status_revision {
            let state = execution.waiting_state;
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Ok(RuntimeResumeSourceAdvance::AlreadyAdvanced {
                state,
                status_revision: revision,
            });
        }
        if revision != expected_status_revision {
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Err(format!(
                "runtime_resume_source_revision_changed:{execution_id}:{expected_status_revision}:{revision}"
            ));
        }
        let target = match execution.waiting_state {
            WaitingState::WaitingUser => WaitingState::Planning,
            WaitingState::Paused => match execution.paused_from_state.as_ref() {
                Some(
                    WaitingState::WaitingUser
                    | WaitingState::Planning
                    | WaitingState::PlanningComplete,
                ) => WaitingState::Planning,
                Some(other) => {
                    drop(guard);
                    self.prune_execution_status_lock(execution_id, &status_lock);
                    return Err(format!(
                        "runtime_resume_source_is_not_planning_pause:{execution_id}:{other:?}"
                    ));
                },
                None => {
                    drop(guard);
                    self.prune_execution_status_lock(execution_id, &status_lock);
                    return Err(format!(
                        "runtime_resume_source_pause_origin_missing:{execution_id}"
                    ));
                },
            },
            ref other => {
                drop(guard);
                self.prune_execution_status_lock(execution_id, &status_lock);
                return Err(format!(
                    "runtime_resume_source_state_changed:{execution_id}:{other:?}"
                ));
            },
        };
        let changed = self
            .compare_exchange_execution_status_at_unlocked(
                execution_id,
                execution.waiting_state.clone(),
                expected_status_revision,
                target.clone(),
            )
            .await;
        drop(guard);
        self.prune_execution_status_lock(execution_id, &status_lock);
        let changed = changed?;
        if !changed {
            return Err(format!(
                "runtime_resume_source_generation_lost:{execution_id}:{expected_status_revision}"
            ));
        }
        self.finalize_execution_status_change(
            &execution,
            execution.waiting_state.clone(),
            target.clone(),
            "Durable AskLoop resume receipt consumed source pause".to_owned(),
        )
        .await?;
        Ok(RuntimeResumeSourceAdvance::Advanced)
    }

    /// A continuation that still has sealed remaining questions may settle
    /// without changing Runtime's status generation only when the exact new
    /// AskLoop state id and pending session are both durable.
    pub(crate) async fn runtime_resume_successor_pause_is_durable(
        &self,
        preparation: &crate::magician_v2::ask_loop::ResumePreparation,
    ) -> Result<bool, String> {
        let workflow_id = &preparation.notification.workflow_id;
        let latest = self
            .state_tracker
            .latest_state(workflow_id)
            .await
            .map_err(|error| error.to_string())?;
        let Some(latest) = latest else {
            return Ok(false);
        };
        if preparation
            .mutation
            .pause_resume
            .remaining_questions
            .is_empty()
        {
            if latest.state_id == preparation.mutation.pause_resume.source_state_id {
                return Ok(false);
            }
        } else if latest.state_id != preparation.notification.resumed_state.state_id {
            return Ok(false);
        }
        self.ask_loop_requires_user(workflow_id)
            .await
            .map_err(|error| error.to_string())
    }

    /// Drive a legacy/non-envelope AskLoop continuation only from the exact
    /// HMAC-bound Runtime resume receipt owned by Artifact V2. A completed
    /// successful PlanGraph on the sealed source turn is adopted before any
    /// replanning, closing the crash window after plan persistence. Execution
    /// enters through the ordinary server-owned dormant/exact recovery gates;
    /// this method is crate-private so a client cannot mint launch authority.
    pub(crate) async fn resume_runtime_from_durable_receipt(
        &self,
        preparation: crate::magician_v2::ask_loop::ResumePreparation,
        source_turn_id: &str,
        source_turn_sha256: &str,
        source_plan_sha256: Option<&str>,
        sealed_result_plan_sha256: Option<&str>,
        source_status_revision: u64,
    ) -> Result<RuntimeResumeDriveProgress, String> {
        use sha2::{Digest, Sha256};

        fn completed_plan(turn: &V2Turn) -> Option<PlanGraph> {
            turn.strategy_attempts
                .iter()
                .rev()
                .find(|attempt| {
                    attempt.failure_reason.is_none()
                        && attempt.exploration_result.strategy_metadata.completed
                        && attempt
                            .exploration_result
                            .plan
                            .as_ref()
                            .is_some_and(|plan| !plan.steps.is_empty())
                })
                .and_then(|attempt| attempt.exploration_result.plan.clone())
        }

        fn plan_sha256(plan: &PlanGraph) -> Result<String, String> {
            let value = serde_json::to_value(plan)
                .map_err(|error| format!("runtime resume PlanGraph encoding failed: {error}"))?;
            crate::magician_v2::json_traversal::canonical_json_bytes(&value)
                .map(|bytes| hex::encode(Sha256::digest(bytes)))
                .map_err(|error| format!("runtime resume PlanGraph encoding failed: {error}"))
        }

        fn turn_sha256(turn: &V2Turn) -> Result<String, String> {
            let value = serde_json::to_value(turn)
                .map_err(|error| format!("runtime resume source turn encoding failed: {error}"))?;
            crate::magician_v2::json_traversal::canonical_json_bytes(&value)
                .map(|bytes| hex::encode(Sha256::digest(bytes)))
                .map_err(|error| format!("runtime resume source turn encoding failed: {error}"))
        }

        let notification = preparation.notification.clone();
        let execution_id = notification.workflow_id.clone();
        let mut source_turn = self
            .conversation_store
            .get_turn(&execution_id, source_turn_id)
            .await
            .map_err(|error| format!("runtime resume source turn read failed: {error}"))?;
        if source_turn.execution_id != execution_id || source_turn.id != source_turn_id {
            return Err(format!(
                "runtime_resume_source_turn_identity_mismatch:{execution_id}:{source_turn_id}"
            ));
        }
        let mut plan = completed_plan(&source_turn);
        let observed_status_revision = self
            .conversation_store
            .get_execution_status_revision(&execution_id)
            .await
            .map_err(|error| {
                format!("runtime resume source status revision read failed: {error}")
            })?;
        let source_runtime = self
            .conversation_store
            .get_execution(&execution_id)
            .await
            .map_err(|error| format!("runtime resume source execution read failed: {error}"))?;
        let confirmed_status_revision = self
            .conversation_store
            .get_execution_status_revision(&execution_id)
            .await
            .map_err(|error| {
                format!("runtime resume source status revision recheck failed: {error}")
            })?;
        if confirmed_status_revision != observed_status_revision {
            return Err(format!(
                "runtime_resume_source_generation_unstable:{execution_id}:{observed_status_revision}:{confirmed_status_revision}"
            ));
        }
        if observed_status_revision < source_status_revision {
            return Err(format!(
                "runtime_resume_source_revision_regressed:{execution_id}:{source_status_revision}:{observed_status_revision}"
            ));
        }
        if observed_status_revision == source_status_revision
            && turn_sha256(&source_turn)? != source_turn_sha256
        {
            return Err(format!(
                "runtime_resume_source_turn_changed:{execution_id}:{source_turn_id}"
            ));
        }
        if source_plan_sha256.is_none()
            && plan.is_some()
            && observed_status_revision <= source_status_revision
        {
            return Err(format!(
                "runtime_resume_unsealed_source_plan_appeared:{execution_id}:{source_turn_id}"
            ));
        }
        if let Some(expected) = source_plan_sha256 {
            let actual = plan.as_ref().ok_or_else(|| {
                format!("runtime_resume_source_plan_disappeared:{execution_id}:{source_turn_id}")
            })?;
            if plan_sha256(actual)? != expected {
                return Err(format!(
                    "runtime_resume_source_plan_changed:{execution_id}:{source_turn_id}"
                ));
            }
        }

        if self
            .runtime_resume_successor_pause_is_durable(&preparation)
            .await?
        {
            return Ok(RuntimeResumeDriveProgress::DurableHandoff);
        }

        let _generation_state = if observed_status_revision == source_status_revision {
            match self
                .advance_runtime_resume_source_generation(&execution_id, source_status_revision)
                .await?
            {
                RuntimeResumeSourceAdvance::Advanced => WaitingState::Planning,
                RuntimeResumeSourceAdvance::AlreadyAdvanced {
                    state,
                    status_revision,
                } => {
                    return Err(format!(
                        "runtime_resume_source_advanced_during_admission:{execution_id}:{status_revision}:{state:?}"
                    ));
                },
            }
        } else if observed_status_revision == source_status_revision.saturating_add(1)
            && source_runtime.waiting_state == WaitingState::Planning
        {
            WaitingState::Planning
        } else if observed_status_revision == source_status_revision.saturating_add(2)
            && source_runtime.waiting_state == WaitingState::PlanningComplete
        {
            // Compatibility with a receipt owner that durably published Ready
            // immediately before a rolling upgrade or process loss. New code
            // publishes Ready only after the completed plan is durable.
            WaitingState::PlanningComplete
        } else {
            return Err(format!(
                "runtime_resume_source_generation_requires_handoff:{execution_id}:{source_status_revision}:{observed_status_revision}:{:?}",
                source_runtime.waiting_state
            ));
        };

        if plan.is_none() || (source_plan_sha256.is_none() && sealed_result_plan_sha256.is_none()) {
            let latest = self
                .conversation_store
                .get_latest_turn_with_analysis(&execution_id)
                .await
                .map_err(|error| format!("runtime resume latest turn read failed: {error}"))?
                .ok_or_else(|| format!("runtime_resume_latest_turn_missing:{execution_id}"))?;
            if latest.id != source_turn_id {
                return Err(format!(
                    "runtime_resume_source_turn_superseded:{execution_id}:{source_turn_id}:{}",
                    latest.id
                ));
            }
            self.resume_workflow_inner(notification.clone(), false)
                .await?;
            source_turn = self
                .conversation_store
                .get_turn(&execution_id, source_turn_id)
                .await
                .map_err(|error| format!("runtime resume source turn reread failed: {error}"))?;
            plan = completed_plan(&source_turn);
        }

        if source_plan_sha256.is_none() {
            let result_plan = plan.as_ref().ok_or_else(|| {
                format!("runtime_resume_replanning_completed_without_plan:{execution_id}")
            })?;
            let actual_result_sha256 = plan_sha256(result_plan)?;
            match sealed_result_plan_sha256 {
                Some(expected) if expected == actual_result_sha256 => {},
                Some(_) => {
                    return Err(format!(
                        "runtime_resume_result_plan_changed:{execution_id}:{source_turn_id}"
                    ));
                },
                None => {
                    return Ok(RuntimeResumeDriveProgress::PlanRequiresSeal {
                        plan_sha256: actual_result_sha256,
                    });
                },
            }
        }

        let mut runtime = self
            .conversation_store
            .get_execution(&execution_id)
            .await
            .map_err(|error| format!("runtime resume execution reread failed: {error}"))?;
        if runtime.waiting_state == WaitingState::Planning {
            let ready = self
                .transition_status_from_runtime(&execution_id, WorkflowEvent::ReadyToExecute)
                .await?;
            if ready != WaitingState::PlanningComplete {
                return Err(format!(
                    "runtime_resume_sealed_plan_ready_transition_failed:{execution_id}:{ready:?}"
                ));
            }
            runtime.waiting_state = ready;
        }
        match runtime.waiting_state {
            WaitingState::Sleeping
            | WaitingState::WaitingChildren
            | WaitingState::WaitingUser
            | WaitingState::Paused
            | WaitingState::Completed
            | WaitingState::Failed
            | WaitingState::Cancelled => {
                return Ok(RuntimeResumeDriveProgress::DurableHandoff);
            },
            WaitingState::Planning => {
                return Err(format!(
                    "runtime_resume_replanning_did_not_commit:{execution_id}"
                ))
            },
            WaitingState::PlanningComplete => {
                let plan = plan.as_ref().ok_or_else(|| {
                    format!("runtime_resume_completed_without_plan:{execution_id}")
                })?;
                // The plan run is boxed on both exits below: a durable-receipt
                // resume reaches execution from the recovery worker, whose
                // frames already sit beneath this one.
                return Box::pin(self.execute_plan_graph(
                    &execution_id,
                    plan,
                    runtime.task_id.as_deref(),
                ))
                .await
                .map(|()| RuntimeResumeDriveProgress::DurableHandoff);
            },
            WaitingState::Runnable | WaitingState::Executing => {},
        }

        let recovery_authority = self
            .stateless_base_execution_recovery_authority(
                &runtime.principal,
                &runtime.workspace,
                &runtime.id,
            )
            .await
            .map_err(|error| format!("runtime resume recovery authority read failed: {error}"))?;
        if matches!(
            recovery_authority,
            crate::magician_v2::execution::agentic::run_loop::store::fs::BaseExecutionRecoveryAuthority::Live { .. }
                | crate::magician_v2::execution::agentic::run_loop::store::fs::BaseExecutionRecoveryAuthority::RecoverableExact { .. }
                | crate::magician_v2::execution::agentic::run_loop::store::fs::BaseExecutionRecoveryAuthority::SettlementPending { .. }
        ) {
            return Ok(RuntimeResumeDriveProgress::DurableHandoff);
        }
        let plan = plan
            .as_ref()
            .ok_or_else(|| format!("runtime_resume_active_without_durable_plan:{execution_id}"))?;
        match self.claim_interrupted_plan_recovery(&runtime, None).await? {
            InterruptedPlanRecoveryAdmission::Admitted(recovery) => {
                Box::pin(self.execute_plan_graph_with_recovery(
                    &execution_id,
                    plan,
                    runtime.task_id.as_deref(),
                    Some(recovery),
                    false,
                ))
                .await
                .map(|()| RuntimeResumeDriveProgress::DurableHandoff)
            },
            InterruptedPlanRecoveryAdmission::AlreadyOwned => {
                Ok(RuntimeResumeDriveProgress::DurableHandoff)
            },
            InterruptedPlanRecoveryAdmission::Deferred(reason) => Err(format!(
                "runtime_resume_plan_recovery_deferred:{execution_id}:{reason}"
            )),
        }
    }

    pub async fn commit_prepared_resume_mutation(
        &self,
        mutation: &crate::magician_v2::ask_loop::PreparedResumeMutation,
    ) -> Result<(), String> {
        let ask_loop = self.ask_loop_api.as_ref().ok_or_else(|| {
            format!(
                "ask_loop_unavailable_for_prepared_resume:{}",
                mutation.pause_resume.workflow_id
            )
        })?;
        ask_loop
            .commit_prepared_resume_mutation(mutation)
            .await
            .map(|_| ())
            .map_err(|error| error.to_string())
    }

    /// Deprecated: use [`resume_workflow`] instead.
    pub async fn handle_resume_notification(
        &self,
        notification: ResumeNotification,
    ) -> Result<(), String> {
        self.resume_workflow(notification).await
    }

    /// Execute strategy with retry loop, failure detection, and automatic
    /// escalation
    ///
    /// This method implements the core strategy escalation mechanism:
    /// 1. Execute the given strategy
    /// 2. Check result quality (confidence threshold, terminal status)
    /// 3. If insufficient, classify the failure
    /// 4. Call strategy's handle_failure() to get NextAction
    /// 5. Process NextAction (Escalate, Simplify, or Abort)
    /// 6. Retry with new strategy if appropriate
    /// 7. Limit retries to prevent infinite loops
    ///
    /// # Returns
    /// Tuple of: (ExplorationResult, final_strategy, all_strategies_attempted,
    /// retry_count)
    async fn execute_strategy_with_retry(
        &self,
        initial_strategy: StrategyType,
        guided_params: GuidedSearchParams,
        context: &StrategyContext,
        query: &str,
    ) -> Result<
        (
            crate::magician_v2::strategy::ExplorationResult,
            StrategyType,
            Vec<StrategyType>,
            Vec<StrategyAttempt>,
            u32,
        ),
        anyhow::Error,
    > {
        const MAX_RETRIES: u32 = 3;
        let mut current_strategy = initial_strategy;

        let mut strategies_attempted = vec![current_strategy];
        let mut all_attempts = Vec::new(); // Collect ALL attempts for frontend tree view
        let mut retry_count = 0;

        loop {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Attempting strategy: {:?} (attempt {}/{})",
                current_strategy,
                retry_count + 1,
                MAX_RETRIES + 1
            );

            let attempt_start = std::time::Instant::now();

            // Execute the current strategy
            let exploration_result = self
                .execute_single_strategy(current_strategy, &guided_params, context, query)
                .await?;

            let _attempt_duration = attempt_start.elapsed();

            // Check if result is acceptable
            let is_terminal = exploration_result.root_node.is_terminal;
            let confidence = exploration_result.confidence;

            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Strategy {:?} completed: confidence={:.3}, \
                 terminal={}, nodes_explored={}",
                current_strategy,
                confidence,
                is_terminal,
                exploration_result.all_nodes.len()
            );

            // Determine if this attempt succeeded or failed
            let (failure_reason, should_continue) =
                if confidence >= CONFIDENCE_THRESHOLD && is_terminal {
                    info!(
                    "[MAGICIAN-V2-ORCHESTRATOR] ✓ Strategy {:?} succeeded with confidence {:.3}",
                    current_strategy, confidence
                );
                    (None, false) // Success - no failure reason, don't continue
                } else if retry_count >= MAX_RETRIES {
                    info!(
                    "[MAGICIAN-V2-ORCHESTRATOR] ⚠ Max retries ({}) reached. Returning best result \
                     from {:?} with confidence {:.3}",
                    MAX_RETRIES, current_strategy, confidence
                );
                    (Some(StrategyFailure::LowConfidence(confidence)), false) // Failed but exhausted retries
                } else {
                    // Classify the failure
                    let failure = self.classify_failure(&exploration_result, context);
                    info!(
                        "[MAGICIAN-V2-ORCHESTRATOR] Classified failure: {:?}",
                        failure
                    );
                    (Some(failure), true) // Failed and should retry
                };

            // Record this attempt
            // Use time from exploration_result which already includes total time (query analysis + elicitation + strategy)
            let attempt = StrategyAttempt {
                strategy_type: current_strategy,
                exploration_result: exploration_result.clone(),
                attempt_number: retry_count + 1,
                failure_reason: failure_reason.clone(),
                resources_used: ResourceUsage {
                    llm_calls: exploration_result.resources_consumed.llm_calls, // Total LLM calls
                    time_ms: exploration_result.resources_consumed.time_ms,     /* Total time from
                                                                                 * strategy (consistent
                                                                                 * with LLM calls) */
                    tokens: exploration_result.resources_consumed.tokens,
                },
                attempted_at: chrono::Utc::now().timestamp_millis(),
            };
            all_attempts.push(attempt);

            // If succeeded or exhausted retries, return
            if !should_continue {
                return Ok((
                    exploration_result,
                    current_strategy,
                    strategies_attempted,
                    all_attempts,
                    retry_count,
                ));
            }

            // Use rule-based strategy selection (escalates to AtomicComposition)
            let next_action = AdaptiveStrategySelector::handle_strategy_failure(
                current_strategy,
                failure_reason.expect("failure_reason is always Some when should_continue == true; invariant broken by control flow change"),
                &context.resource_budget,
            );

            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] NextAction selected: {:?}",
                next_action
            );

            match next_action {
                // consumer_mode guard: block escalation/simplification to non-AtomicComposition
                NextAction::Escalate(s) | NextAction::Simplify(s)
                    if self.consumer_mode && s != StrategyType::AtomicComposition =>
                {
                    // Loud on purpose. Consumer mode leaves AtomicComposition
                    // with nowhere to fall back to, so this returns an empty
                    // exploration result, `trigger_execution` finds no
                    // PlanGraph, and the run silently drops to
                    // `trigger_execution_direct` with `skip_planning`. The task
                    // still completes on the agentic loop, which is exactly why
                    // a degraded planning tier can go unnoticed for weeks — at
                    // INFO this never surfaced in the runtime activity view.
                    warn!(
                        blocked_strategy = ?s,
                        failed_strategy = ?current_strategy,
                        "[MAGICIAN-V2-ORCHESTRATOR] Consumer mode — {:?} failed and the fallback to \
                         {:?} is blocked; no PlanGraph will be produced and execution will fall \
                         back to direct runtime-context (skip_planning)",
                        current_strategy,
                        s
                    );
                    return Ok((
                        exploration_result,
                        current_strategy,
                        strategies_attempted,
                        all_attempts,
                        retry_count,
                    ));
                },
                NextAction::Escalate(new_strategy) => {
                    info!(
                        "[MAGICIAN-V2-ORCHESTRATOR] → Escalating from {:?} to {:?}",
                        current_strategy, new_strategy
                    );
                    current_strategy = new_strategy;
                    if strategies_attempted.last().copied() != Some(new_strategy) {
                        strategies_attempted.push(new_strategy);
                    }
                    retry_count += 1;
                    // Continue loop to retry with escalated strategy
                },
                NextAction::Simplify(new_strategy) => {
                    info!(
                        "[MAGICIAN-V2-ORCHESTRATOR] → Simplifying from {:?} to {:?}",
                        current_strategy, new_strategy
                    );
                    current_strategy = new_strategy;
                    if strategies_attempted.last().copied() != Some(new_strategy) {
                        strategies_attempted.push(new_strategy);
                    }
                    retry_count += 1;
                    // Continue loop to retry with simplified strategy
                },
                NextAction::Abort(reason) => {
                    info!(
                        "[MAGICIAN-V2-ORCHESTRATOR] ✗ Strategy {:?} recommends abort: {}",
                        current_strategy, reason
                    );
                    // Return the current result even though it's not ideal
                    return Ok((
                        exploration_result,
                        current_strategy,
                        strategies_attempted,
                        all_attempts,
                        retry_count,
                    ));
                },
            }
        }
    }

    /// Execute a single strategy without retry logic
    async fn execute_single_strategy(
        &self,
        strategy: StrategyType,
        guided_params: &GuidedSearchParams,
        context: &StrategyContext,
        query: &str,
    ) -> Result<crate::magician_v2::strategy::ExplorationResult, anyhow::Error> {
        let effective_query = context
            .clarified_task
            .as_ref()
            .filter(|ct| !ct.clarified_task.is_empty())
            .map(|ct| ct.clarified_task.as_str())
            .unwrap_or(query);

        if effective_query != query {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Using clarified query for strategy execution:\n\
                 Original: \"{}\"\n\
                 Clarified: \"{}\"",
                query, effective_query
            );
        } else if context.clarified_task.is_some() {
            warn!(
                "[MAGICIAN-V2-ORCHESTRATOR] Clarified task exists but is empty, using original query: \"{}\"",
                query
            );
        } else {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] No clarified task available, using original query: \"{}\"",
                query
            );
        }

        // consumer_mode guard: redirect GuidedSearch → AtomicComposition
        let strategy = if self.consumer_mode && strategy == StrategyType::GuidedSearch {
            info!("[MAGICIAN-V2-ORCHESTRATOR] Consumer mode — redirecting GuidedSearch → AtomicComposition");
            StrategyType::AtomicComposition
        } else {
            strategy
        };

        match strategy {
            StrategyType::GuidedSearch => {
                info!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Creating adaptive GuidedSearch: iterations={}, \
                     depth={}, beam={}",
                    guided_params.max_iterations, guided_params.max_depth, guided_params.beam_width
                );
                let mut guided = GuidedSearchStrategy::with_adaptive_params(
                    guided_params.clone(),
                    self.task_decomposer.clone(),
                );
                guided.explore(context, effective_query).await
            },
            StrategyType::AtomicComposition => {
                // Create AtomicComposition with operation LLM router if available
                let atomic = if let Some(ref operation_llm_router) = self.operation_llm_router {
                    let operation_llm_router = Arc::new(operation_llm_router.with_scope_context(
                        Some(magicllm::LlmScope::new(
                            context.execution_context.principal.clone(),
                            context.execution_context.workspace.clone(),
                        )),
                    ));
                    AtomicCompositionStrategy::with_services(
                        operation_llm_router,
                        self.prompt_manager.clone(),
                    )
                } else {
                    warn!(
                        "[MAGICIAN-V2-ORCHESTRATOR] AtomicComposition: operation LLM router not \
                         configured, using default (will fail)"
                    );
                    AtomicCompositionStrategy::new()
                };

                // Wire up progressive elicitation services if available via ElicitationManager
                let mut atomic = if let Some(ref elicitation_mgr) = context.elicitation_manager {
                    let inference_service = elicitation_mgr.get_inference_service();
                    let discovery_service = elicitation_mgr.get_discovery_service();

                    if inference_service.is_some() || discovery_service.is_some() {
                        info!(
                            "[MAGICIAN-V2-ORCHESTRATOR] Wiring progressive elicitation services to AtomicComposition (inference: {}, discovery: {})",
                            inference_service.is_some(),
                            discovery_service.is_some()
                        );
                        atomic.with_elicitation_services(inference_service, discovery_service)
                    } else {
                        debug!(
                            "[MAGICIAN-V2-ORCHESTRATOR] ElicitationManager present but no progressive services configured"
                        );
                        atomic
                    }
                } else {
                    debug!(
                        "[MAGICIAN-V2-ORCHESTRATOR] No ElicitationManager available for progressive resolution"
                    );
                    atomic
                };

                atomic.explore(context, effective_query).await
            },
        }
    }

    /// Classify exploration result into a StrategyFailure type
    fn classify_failure(
        &self,
        result: &crate::magician_v2::strategy::ExplorationResult,
        context: &StrategyContext,
    ) -> StrategyFailure {
        // For atomic composition: check plan.steps instead of tool_match
        // Atomic composition generates plans with steps, not tool matches
        if let Some(ref plan) = result.plan {
            if !plan.steps.is_empty() {
                // Plan was successfully generated with steps
                // Plans with unresolved inputs are not failures - they're awaiting user input
                // Return LowConfidence to trigger proper flow, but not NoToolsFound
                debug!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Atomic composition plan generated with {} steps, {} unresolved inputs",
                    plan.steps.len(),
                    plan.unresolved_inputs.len()
                );
                return StrategyFailure::LowConfidence(result.confidence);
            }
        }

        // Check for no tools found (for tool-matching strategies like guided search)
        if result.root_node.tool_match.is_none()
            || result
                .root_node
                .tool_match
                .as_ref()
                .map(|m| m.primary_match.is_none())
                .unwrap_or(true)
        {
            return StrategyFailure::NoToolsFound;
        }

        // Check for low confidence (composite score)
        // Note: result.confidence is composite of tool_confidence AND
        // parameter_compatibility Both must be >= threshold for terminal
        // solution

        // Extract individual scores for better debugging using MAPPED parameters
        let (tool_conf, param_compat) = if let Some(ref tool_match) = result.root_node.tool_match {
            (
                tool_match.match_confidence,
                if let Some(ref primary) = tool_match.primary_match {
                    crate::magician_v2::strategy::parameter_utils::calculate_parameter_compatibility(
                        &primary.tool_metadata.input_schema,
                        &result.root_node.available_parameters, /* Use mapped parameters, not
                                                                 * raw entities */
                    )
                } else {
                    0.0
                },
            )
        } else {
            (0.0, 0.0)
        };

        // Check if either tool confidence OR parameter compatibility is too low
        // This is more accurate than just checking composite score
        if tool_conf < CONFIDENCE_THRESHOLD || param_compat < CONFIDENCE_THRESHOLD {
            debug!(
                "[MAGICIAN-V2-ORCHESTRATOR] Low confidence: tool={:.3}, param_compat={:.3}, \
                 composite={:.3} (threshold={:.3})",
                tool_conf, param_compat, result.confidence, CONFIDENCE_THRESHOLD
            );

            return StrategyFailure::LowConfidence(result.confidence);
        }

        // Check for timeout
        if result.resources_consumed.time_ms > context.resource_budget.max_time_ms {
            return StrategyFailure::TimeoutExceeded;
        }

        // Check for LLM budget exceeded
        if result.resources_consumed.llm_calls > context.resource_budget.max_llm_calls {
            return StrategyFailure::LLMBudgetExceeded;
        }

        // Check if decomposition was attempted but failed
        // Use precise prefix matching instead of substring matching
        if !result.strategy_metadata.completed {
            if let Some(ref reason) = result.strategy_metadata.termination_reason {
                let reason_lower = reason.to_lowercase();
                if reason_lower.starts_with("decomposition") {
                    return StrategyFailure::DecompositionFailed;
                }
            }
        }

        // Default to low confidence if we got here
        StrategyFailure::LowConfidence(result.confidence)
    }

