    // ========================================================================
    // Execution Status Management
    // ========================================================================

    /// Raw generic status mutation. Runtime state-machine owners should use
    /// typed transitions; governed app executions may only be projected
    /// through their exact outcome-settlement owner.
    pub async fn update_execution_status(
        &self,
        execution_id: &str,
        status: WaitingState,
    ) -> Result<(), String> {
        self.ensure_initialized()?;
        let status_lock = self
            .execution_status_locks
            .entry(execution_id.to_string())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone();
        let guard = status_lock.lock().await;
        let execution = match self.conversation_store.get_execution(execution_id).await {
            Ok(execution) => execution,
            Err(error) => {
                drop(guard);
                self.prune_execution_status_lock(execution_id, &status_lock);
                return Err(format!(
                    "Failed to load execution for raw status update: {}",
                    error
                ));
            },
        };
        if let Err(error) = self.reject_generic_app_execution(&execution).await {
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Err(error);
        }
        let result = self
            .compare_exchange_execution_status_unlocked(
                execution_id,
                execution.waiting_state.clone(),
                status.clone(),
            )
            .await;
        drop(guard);
        self.prune_execution_status_lock(execution_id, &status_lock);
        match result {
            Ok(true) => Ok(()),
            Ok(false) => Err(format!(
                "Execution {execution_id} changed from expected state {:?} before raw status update to {status:?}",
                execution.waiting_state
            )),
            Err(error) => Err(error),
        }
    }

    async fn compare_exchange_execution_status_unlocked(
        &self,
        execution_id: &str,
        expected: WaitingState,
        status: WaitingState,
    ) -> Result<bool, String> {
        self.conversation_store
            .compare_exchange_execution_status(execution_id, expected, status)
            .await
            .map_err(|error| error.to_string())
    }

    /// Status CAS for a caller that already holds the execution's task
    /// transaction fence; the store reuses that lock rather than taking it.
    async fn compare_exchange_execution_status_holding_task_lock_unlocked(
        &self,
        execution_id: &str,
        expected: WaitingState,
        status: WaitingState,
    ) -> Result<bool, String> {
        self.conversation_store
            .compare_exchange_execution_status_holding_task_lock(execution_id, expected, status)
            .await
            .map_err(|error| error.to_string())
    }

    async fn compare_exchange_execution_status_at_unlocked(
        &self,
        execution_id: &str,
        expected: WaitingState,
        expected_status_revision: u64,
        status: WaitingState,
    ) -> Result<bool, String> {
        self.conversation_store
            .compare_exchange_execution_status_at(
                execution_id,
                expected,
                expected_status_revision,
                status,
            )
            .await
            .map_err(|error| error.to_string())
    }

    async fn load_execution_with_status_revision_unlocked(
        &self,
        execution_id: &str,
    ) -> Result<(ExecutionRun, u64), String> {
        for _ in 0..3 {
            let before = self
                .conversation_store
                .get_execution_status_revision(execution_id)
                .await
                .map_err(|error| error.to_string())?;
            let execution = self
                .conversation_store
                .get_execution(execution_id)
                .await
                .map_err(|error| error.to_string())?;
            let after = self
                .conversation_store
                .get_execution_status_revision(execution_id)
                .await
                .map_err(|error| error.to_string())?;
            if before == after {
                return Ok((execution, after));
            }
        }
        Err(format!(
            "Execution {execution_id} did not retain one stable status generation"
        ))
    }

    fn prune_execution_status_lock(&self, execution_id: &str, lock: &Arc<tokio::sync::Mutex<()>>) {
        self.execution_status_locks
            .remove_if(execution_id, |_, current| {
                Arc::ptr_eq(current, lock) && Arc::strong_count(current) == 2
            });
    }

    async fn finalize_execution_status_change(
        &self,
        execution: &ExecutionRun,
        previous_status: WaitingState,
        new_status: WaitingState,
        reason: String,
    ) -> Result<(), String> {
        if new_status != WaitingState::Runnable {
            self.retire_server_owned_fresh_launch_capability(&execution.id);
        }
        self.emit_execution_responsibility_changed_for(&execution.id)
            .await;

        let emitted_task_id = execution
            .task_id
            .clone()
            .filter(|_| execution.root_execution_id.as_deref() == Some(execution.id.as_str()));
        let timestamp_ms = chrono::Utc::now().timestamp_millis();
        if let Some(broadcaster) = &self.event_broadcaster {
            broadcaster.emit(
                crate::magician_v2::realtime_events::RuntimeTransportEvent::ExecutionStatusChanged {
                    execution_id: execution.id.clone(),
                    principal: Some(execution.principal.clone()),
                    workspace: Some(execution.workspace.clone()),
                    task_id: emitted_task_id.clone(),
                    root_execution_id: execution.root_execution_id.clone(),
                    previous_status: format!("{:?}", previous_status),
                    new_status: format!("{:?}", new_status),
                    reason: Some(reason.clone()),
                    timestamp: timestamp_ms,
                },
            );
        } else {
            self.emit_runtime_canonical_event(
                &execution.id,
                ArtifactV2EventType::ExecutionStatusChanged,
                serde_json::json!({
                    "task_id": emitted_task_id,
                    "root_execution_id": execution.root_execution_id.clone(),
                    "previous_status": format!("{:?}", previous_status),
                    "new_status": format!("{:?}", new_status),
                    "reason": reason.clone(),
                    "timestamp_ms": timestamp_ms,
                }),
            );
        }
        match new_status {
            WaitingState::WaitingChildren => self.emit_runtime_canonical_event(
                &execution.id,
                ArtifactV2EventType::ExecutionWaitingOnChildren,
                serde_json::json!({
                    "root_execution_id": execution.root_execution_id.clone(),
                    "reason": reason.clone(),
                    "timestamp_ms": timestamp_ms,
                }),
            ),
            WaitingState::WaitingUser | WaitingState::Paused => self.emit_runtime_canonical_event(
                &execution.id,
                ArtifactV2EventType::ExecutionWaitingForUser,
                serde_json::json!({
                    "root_execution_id": execution.root_execution_id.clone(),
                    "reason": reason.clone(),
                    "timestamp_ms": timestamp_ms,
                }),
            ),
            WaitingState::Executing
                if matches!(
                    previous_status,
                    WaitingState::WaitingChildren
                        | WaitingState::WaitingUser
                        | WaitingState::Sleeping
                        | WaitingState::Paused
                ) =>
            {
                self.emit_runtime_canonical_event(
                    &execution.id,
                    ArtifactV2EventType::ExecutionResumed,
                    serde_json::json!({
                        "root_execution_id": execution.root_execution_id.clone(),
                        "reason": reason.clone(),
                        "timestamp_ms": timestamp_ms,
                    }),
                );
            },
            WaitingState::Cancelled => self.emit_runtime_canonical_event(
                &execution.id,
                ArtifactV2EventType::ExecutionCancelled,
                serde_json::json!({
                    "root_execution_id": execution.root_execution_id.clone(),
                    "reason": reason.clone(),
                    "timestamp_ms": timestamp_ms,
                }),
            ),
            _ => {},
        }

        if matches!(
            new_status,
            WaitingState::Completed | WaitingState::Failed | WaitingState::Cancelled
        ) {
            self.retire_server_owned_fresh_launch_capability(&execution.id);
            // Resolve + clear every OUTSTANDING execution-bound HITL so a
            // terminal transition never leaves an attention orphan. Idempotent:
            // no pending pause → both no-op (the normal completion case).
            let hitl_outcome = if matches!(new_status, WaitingState::Cancelled) {
                "cancelled"
            } else {
                "superseded"
            };
            self.resolve_outstanding_hitl_for_execution(&execution.id, hitl_outcome);
            self.clear_pending_pauses_for_execution(&execution.id);
            self.notify_parent_of_terminal_child_transition(execution)
                .await;
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Clearing processing_correlation_id for execution {} (terminal state: {:?})",
                execution.id, new_status
            );
            self.conversation_store
                .update_processing_correlation_id(&execution.id, None)
                .await
                .map_err(|e| format!("Failed to clear processing_correlation_id: {}", e))?;
        }

        Ok(())
    }

    pub async fn set_execution_status_with_side_effects(
        &self,
        execution_id: &str,
        new_status: WaitingState,
        reason: &str,
    ) -> Result<WaitingState, String> {
        self.set_execution_status_with_side_effects_internal(
            execution_id,
            new_status,
            reason,
            false,
        )
        .await
    }

    /// Runtime-only status settlement used when a canonical runtime recovery
    /// decision already owns the transition. Callers must still project the
    /// exact resulting execution outcome into Artifact V2 before reporting
    /// task terminality.
    async fn set_execution_status_with_side_effects_from_runtime(
        &self,
        execution_id: &str,
        new_status: WaitingState,
        reason: &str,
    ) -> Result<WaitingState, String> {
        self.set_execution_status_with_side_effects_internal(execution_id, new_status, reason, true)
            .await
    }

    async fn set_execution_status_with_side_effects_internal(
        &self,
        execution_id: &str,
        new_status: WaitingState,
        reason: &str,
        runtime_owned: bool,
    ) -> Result<WaitingState, String> {
        self.ensure_initialized()?;
        let status_lock = self
            .execution_status_locks
            .entry(execution_id.to_string())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone();
        let guard = status_lock.lock().await;
        let execution = match self.conversation_store.get_execution(execution_id).await {
            Ok(execution) => execution,
            Err(error) => {
                drop(guard);
                self.prune_execution_status_lock(execution_id, &status_lock);
                return Err(format!(
                    "Failed to load execution for status override: {}",
                    error
                ));
            },
        };
        let governed_app = match self.classify_governed_app_execution(&execution).await {
            Ok(governed_app) => governed_app,
            Err(error) => {
                drop(guard);
                self.prune_execution_status_lock(execution_id, &status_lock);
                return Err(error);
            },
        };
        if governed_app && !runtime_owned {
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Err(format!(
                "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{execution_id}"
            ));
        }
        let previous_status = execution.waiting_state.clone();

        if previous_status == new_status {
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Ok(new_status);
        }

        let update_result = self
            .compare_exchange_execution_status_unlocked(
                execution_id,
                previous_status.clone(),
                new_status.clone(),
            )
            .await;
        drop(guard);
        self.prune_execution_status_lock(execution_id, &status_lock);
        if !update_result? {
            return Err(format!(
                "Execution {execution_id} changed from expected state {previous_status:?} before status override to {new_status:?}"
            ));
        }
        self.finalize_execution_status_change(
            &execution,
            previous_status,
            new_status.clone(),
            reason.to_string(),
        )
        .await?;

        Ok(new_status)
    }

    /// Get execution status
    pub async fn get_execution_status(&self, execution_id: &str) -> Result<WaitingState, String> {
        self.ensure_initialized()?;
        self.conversation_store
            .get_execution_status(execution_id)
            .await
            .map_err(|e| e.to_string())
    }

    /// Transition execution status based on workflow events
    /// Implements the V2 status state machine with proper transitions
    pub async fn transition_status(
        &self,
        execution_id: &str,
        event: WorkflowEvent,
    ) -> Result<WaitingState, String> {
        self.transition_status_with_expected(execution_id, None, event, false)
            .await
    }

    /// Transition an execution while consuming the typed authority carried by
    /// an already-taken pause. Ordinary pauses still go through the generic
    /// fence. Protected app pauses must match the exact runtime execution,
    /// task, and scope and pass fresh continuation admission before the
    /// runtime-owned transition is available.
    ///
    /// Returned boxed, like [`Self::transition_status_from_runtime`]: the resume
    /// control surface awaits this helper eight times in one async fn, and an
    /// inline await would embed a separate copy of this whole state machine —
    /// which reaches the status CAS — into that caller's frame for each one.
    pub fn transition_status_for_pause_continuation<'a>(
        &'a self,
        execution_id: &'a str,
        pause_data: &'a FullPauseData,
        event: WorkflowEvent,
    ) -> Pin<Box<dyn Future<Output = Result<WaitingState, String>> + Send + 'a>> {
        Box::pin(self.transition_status_for_pause_continuation_inner(
            execution_id,
            pause_data,
            event,
        ))
    }

    async fn transition_status_for_pause_continuation_inner(
        &self,
        execution_id: &str,
        pause_data: &FullPauseData,
        event: WorkflowEvent,
    ) -> Result<WaitingState, String> {
        if pause_data.pause_state.app_disclosure_checkpoint.is_none() {
            return self.transition_status(execution_id, event).await;
        }

        let execution = self
            .conversation_store
            .get_execution(execution_id)
            .await
            .map_err(|error| format!("Failed to load protected continuation execution: {error}"))?;
        if !self.classify_governed_app_execution(&execution).await?
            || pause_data.pause_state.execution_id.as_deref() != Some(execution_id)
            || pause_data.pause_state.task_id.as_deref() != execution.task_id.as_deref()
            || pause_data.pause_state.principal.as_deref() != Some(execution.principal.as_str())
            || pause_data.pause_state.workspace.as_deref() != Some(execution.workspace.as_str())
        {
            return Err(format!(
                "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{execution_id}"
            ));
        }
        crate::magician_v2::execution::agentic::validate_app_pause_continuation_classified(
            pause_data,
        )
        .await
        .map_err(|_| format!("{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{execution_id}"))?;
        self.transition_status_from_runtime(execution_id, event)
            .await
    }

    /// Apply a transition owned by the running/recovering execution state
    /// machine. Unlike the public generic control surface, this path may
    /// advance a governed app execution because its caller is responsible for
    /// preserving the app disclosure/effect protocol and projecting the exact
    /// resulting runtime outcome.
    fn transition_status_from_runtime<'a>(
        &'a self,
        execution_id: &'a str,
        event: WorkflowEvent,
    ) -> Pin<Box<dyn Future<Output = Result<WaitingState, String>> + Send + 'a>> {
        // This transition participates in the parent-reconciliation/direct-loop
        // async call cycle. Give that cycle one explicit Send boundary so every
        // runtime caller remains spawn-safe without switching to a local future.
        Box::pin(self.transition_status_with_expected(execution_id, None, event, true))
    }

    /// Pipeline cancellation enters with the Artifact task transaction fence
    /// already held. Carry it only through the runtime status CAS, then release
    /// it before ordinary Artifact outcome projection reacquires the same
    /// non-reentrant task flock.
    async fn transition_status_from_runtime_with_pipeline_task_guard(
        &self,
        execution_id: &str,
        event: WorkflowEvent,
        task_guard: Option<crate::magician_v2::artifact_v2::service::CrossProcessTaskGuard>,
    ) -> Result<WaitingState, String> {
        self.transition_status_with_expected_and_task_guard(
            execution_id,
            None,
            event,
            true,
            task_guard,
        )
        .await
    }

    async fn transition_status_if_current(
        &self,
        execution_id: &str,
        expected: &WaitingState,
        event: WorkflowEvent,
    ) -> Result<WaitingState, String> {
        self.transition_status_with_expected(execution_id, Some(expected), event, true)
            .await
    }

    /// Consume one exact placement generation and install cancellation controls
    /// in the same status critical section as Sleeping -> Executing. A cancel or
    /// terminal transition therefore wins either before checkpoint consumption
    /// or after a live token exists; there is no model-admission window between.
    #[allow(clippy::too_many_arguments)]
    async fn admit_exact_placement_retry(
        &self,
        execution_id: &str,
        principal: &str,
        workspace: &str,
        task_id: &str,
        segment: Option<&str>,
        due_at: chrono::DateTime<Utc>,
        claimed_until: chrono::DateTime<Utc>,
        cancellation_token: CancellationToken,
        manual_pause_signal: Arc<AtomicBool>,
        steer_queue: Arc<std::sync::Mutex<Vec<String>>>,
        governed_app: bool,
        recovered_control_generation: Option<Uuid>,
    ) -> Result<(Option<FullPauseData>, Uuid), String> {
        let wake_queue = self
            .wake_up_queue()
            .ok_or_else(|| "exact placement retry queue is unavailable".to_string())?;
        // The detached execution job outlives the dispatcher's original claim
        // guard. Reacquire the same cross-process generation fence here and
        // hold it through checkpoint validation, Sleeping -> Executing, and
        // control publication so an older job cannot admit after a replacement
        // queue generation was published.
        let _retry_generation_guard = wake_queue
            .lock_execution_retry_claim(principal, workspace, task_id, execution_id)
            .await
            .map_err(|error| format!("exact retry generation lock failed: {error}"))?;
        let current_wake = wake_queue
            .execution_retry_wake(principal, workspace, task_id, execution_id)
            .await
            .ok_or_else(|| format!("exact retry queue generation disappeared: {execution_id}"))?;
        if current_wake.wake_at != claimed_until
            || current_wake.execution_retry_due_at != Some(due_at.to_owned())
            || current_wake.stateless_source_segment.as_deref() != segment
            || current_wake.execution_retry_claim_attempt == 0
        {
            return Err(format!(
                "exact placement retry queue generation is stale for {execution_id}"
            ));
        }
        let status_lock = self
            .execution_status_locks
            .entry(execution_id.to_string())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone();
        let guard = status_lock.lock().await;
        let execution = self
            .conversation_store
            .get_execution(execution_id)
            .await
            .map_err(|error| format!("failed to load exact retry execution: {error}"))?;
        if execution.waiting_state != WaitingState::Sleeping
            || execution.principal != principal
            || execution.workspace != workspace
            || execution.task_id.as_deref() != Some(task_id)
        {
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Err(format!(
                "exact placement retry generation is stale for {execution_id}"
            ));
        }
        let pause = match segment {
            Some(segment) => Some(
                self.load_exact_placement_retry_checkpoint(
                    execution_id,
                    principal,
                    workspace,
                    task_id,
                    segment,
                    due_at,
                )
                .await?,
            ),
            None => None,
        };
        let status_admitted = self
            .compare_exchange_execution_status_unlocked(
                execution_id,
                WaitingState::Sleeping,
                WaitingState::Executing,
            )
            .await;
        if !matches!(status_admitted, Ok(true)) {
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Err(match status_admitted {
                Ok(false) => format!(
                    "exact placement retry status changed across processes for {execution_id}"
                ),
                Err(error) => error,
                Ok(true) => unreachable!(),
            });
        }
        let generation = self.register_active_execution_controls_with_generation(
            execution_id.to_string(),
            cancellation_token,
            manual_pause_signal,
            steer_queue,
            governed_app,
            recovered_control_generation.unwrap_or_else(Uuid::new_v4),
        );
        if let Err(error) = self
            .publish_stateless_control_generation(
                execution_id,
                principal,
                workspace,
                generation,
                true,
                false,
                None,
            )
            .await
        {
            self.clear_active_execution_controls(execution_id, generation);
            let rollback_error = match self
                .compare_exchange_execution_status_unlocked(
                    execution_id,
                    WaitingState::Executing,
                    WaitingState::Sleeping,
                )
                .await
            {
                Ok(true) => None,
                Ok(false) => {
                    Some("status changed across processes before exact retry rollback".to_owned())
                },
                Err(rollback_error) => Some(format!(
                    "exact retry status rollback failed: {rollback_error}"
                )),
            };
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Err(match rollback_error {
                Some(rollback_error) => format!(
                    "failed to publish exact retry control generation: {error}; {rollback_error}"
                ),
                None => format!("failed to publish exact retry control generation: {error}"),
            });
        }
        drop(guard);
        self.prune_execution_status_lock(execution_id, &status_lock);
        if let Err(error) = self
            .finalize_execution_status_change(
                &execution,
                WaitingState::Sleeping,
                WaitingState::Executing,
                "Exact placement retry admitted".to_string(),
            )
            .await
        {
            self.clear_active_execution_controls(execution_id, generation);
            let _ = self
                .transition_status_if_current(
                    execution_id,
                    &WaitingState::Executing,
                    WorkflowEvent::ExecutionSleeping,
                )
                .await;
            return Err(error);
        }
        if execution.task_id.is_some() {
            self.maybe_persist_v3_execution_outcome(execution_id, "exact retry admission")
                .await;
        }
        Ok((pause, generation))
    }

    async fn transition_status_with_expected(
        &self,
        execution_id: &str,
        expected: Option<&WaitingState>,
        event: WorkflowEvent,
        runtime_owned: bool,
    ) -> Result<WaitingState, String> {
        self.transition_status_with_expected_and_task_guard(
            execution_id,
            expected,
            event,
            runtime_owned,
            None,
        )
        .await
    }

    async fn transition_status_with_expected_and_task_guard(
        &self,
        execution_id: &str,
        expected: Option<&WaitingState>,
        event: WorkflowEvent,
        runtime_owned: bool,
        mut task_transaction_guard: Option<
            crate::magician_v2::artifact_v2::service::CrossProcessTaskGuard,
        >,
    ) -> Result<WaitingState, String> {
        self.ensure_initialized()?;
        if event == WorkflowEvent::UserCancelled && task_transaction_guard.is_none() {
            let cancellation_execution = self
                .conversation_store
                .get_execution(execution_id)
                .await
                .map_err(|error| {
                    format!("Failed to load execution for cancellation transaction fence: {error}")
                })?;
            if let Some(task_id) = cancellation_execution.task_id.as_deref() {
                task_transaction_guard = Some(
                    crate::magician_v2::artifact_v2::service::acquire_pipeline_task_transaction_guard(
                        &self.durable_artifact_workspace,
                        &cancellation_execution.principal,
                        &cancellation_execution.workspace,
                        task_id,
                    )
                    .await
                    .map_err(|error| {
                        format!(
                            "execution cancellation task transaction fence failed: {error}"
                        )
                    })?,
                );
            }
        }
        let status_lock = self
            .execution_status_locks
            .entry(execution_id.to_string())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone();
        let guard = status_lock.lock().await;
        let execution = match self.conversation_store.get_execution(execution_id).await {
            Ok(execution) => execution,
            Err(error) => {
                drop(guard);
                self.prune_execution_status_lock(execution_id, &status_lock);
                return Err(format!(
                    "Failed to load execution for transition: {}",
                    error
                ));
            },
        };
        let governed_app = match self.classify_governed_app_execution(&execution).await {
            Ok(governed_app) => governed_app,
            Err(error) => {
                drop(guard);
                self.prune_execution_status_lock(execution_id, &status_lock);
                return Err(error);
            },
        };
        if governed_app && !runtime_owned {
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Err(format!(
                "{APP_WORKFLOW_GENERIC_LIFECYCLE_DENIED}:{execution_id}"
            ));
        }
        let current_status = execution.waiting_state.clone();
        if expected.is_some_and(|expected| expected != &current_status) {
            let error = format!(
                "Execution {} changed from expected state {:?} to {:?} before {:?}",
                execution_id, expected, current_status, event
            );
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Err(error);
        }
        if current_status == WaitingState::Paused
            && event == WorkflowEvent::UserResumed
            && execution.paused_from_state.is_none()
        {
            let error = format!(
                "Paused execution {} is missing paused_from_state; refusing heuristic resume",
                execution_id
            );
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            return Err(error);
        }

        let new_status = match (&current_status, event) {
            // Planning -> WaitingUser (when slots need filling)
            (WaitingState::Planning, WorkflowEvent::SlotsCreated) => WaitingState::WaitingUser,

            // WaitingUser -> Planning (when all required slots filled, resume planning)
            (WaitingState::WaitingUser, WorkflowEvent::AllSlotsAnswered) => WaitingState::Planning,

            // Planning -> PlanningComplete (planning finished, execution not yet started)
            (WaitingState::Planning, WorkflowEvent::ReadyToExecute) => {
                WaitingState::PlanningComplete
            },

            // PlanningComplete -> Executing (when execution actually starts - future implementation)
            (WaitingState::PlanningComplete, WorkflowEvent::ExecutionStart) => {
                WaitingState::Executing
            },
            (WaitingState::Runnable, WorkflowEvent::ExecutionStart) => WaitingState::Executing,

            // An execution-bound timer re-enters the same execution id.
            (WaitingState::Sleeping, WorkflowEvent::ExecutionStart) => WaitingState::Executing,

            // WaitingUser -> Executing (when paused execution is continued/resumed)
            (WaitingState::WaitingUser, WorkflowEvent::ExecutionStart) => WaitingState::Executing,

            // Active execution -> WaitingChildren (delegated child executions spawned)
            //
            // Deliberately NOT reachable from `Planning`: an execution there has
            // not been admitted yet, and there is no `(Planning, ExecutionStart)`
            // edge either. A parent delegates only once it is ready, which the
            // launch guarantees by walking `ReadyToExecute` then `ExecutionStart`
            // first — the same ladder the rest of the orchestrator uses.
            (WaitingState::Executing, WorkflowEvent::DelegationChildrenSpawned)
            | (WaitingState::Runnable, WorkflowEvent::DelegationChildrenSpawned)
            | (WaitingState::PlanningComplete, WorkflowEvent::DelegationChildrenSpawned)
            | (WaitingState::WaitingChildren, WorkflowEvent::DelegationChildrenSpawned) => {
                WaitingState::WaitingChildren
            },

            // Active -> Completed (successful execution). Runnable is also
            // accepted for restart convergence: the durable Artifact
            // projection may have committed completion just before the
            // runtime row was reset to Runnable during boot repair.
            (WaitingState::Executing, WorkflowEvent::ExecutionComplete)
            | (WaitingState::Runnable, WorkflowEvent::ExecutionComplete) => WaitingState::Completed,

            // Executing -> WaitingUser (execution paused for user input like login, CAPTCHA)
            (WaitingState::Executing, WorkflowEvent::ExecutionPausedForInput)
            | (WaitingState::Runnable, WorkflowEvent::ExecutionPausedForInput) => {
                WaitingState::WaitingUser
            },

            // Runnable is the restart shape of an interrupted Executing row.
            // It reaches this edge only through exact timer recovery after the
            // scoped queue generation and sealed placement body are verified.
            (WaitingState::Executing, WorkflowEvent::ExecutionSleeping)
            | (WaitingState::Runnable, WorkflowEvent::ExecutionSleeping) => WaitingState::Sleeping,

            // WaitingChildren -> Runnable (all active delegated children reached terminal state)
            (WaitingState::WaitingChildren, WorkflowEvent::ChildCompleted) => {
                WaitingState::Runnable
            },

            // Planning/ready/running -> Failed (execution error at any stage).
            // Direct chat-backed runs can fail during owner/profile setup before
            // the scheduler has claimed the execution, while it is still Runnable.
            (WaitingState::Planning, WorkflowEvent::ExecutionFailed) => WaitingState::Failed,
            (WaitingState::PlanningComplete, WorkflowEvent::ExecutionFailed) => {
                WaitingState::Failed
            },
            (WaitingState::Runnable, WorkflowEvent::ExecutionFailed) => WaitingState::Failed,
            (WaitingState::Executing, WorkflowEvent::ExecutionFailed) => WaitingState::Failed,
            (WaitingState::Sleeping, WorkflowEvent::ExecutionFailed) => WaitingState::Failed,
            (WaitingState::WaitingUser, WorkflowEvent::ExecutionFailed) => WaitingState::Failed,

            // Explicit user pause only applies to active non-terminal states.
            (WaitingState::Planning, WorkflowEvent::UserPaused)
            | (WaitingState::PlanningComplete, WorkflowEvent::UserPaused)
            | (WaitingState::Runnable, WorkflowEvent::UserPaused)
            | (WaitingState::Executing, WorkflowEvent::UserPaused)
            | (WaitingState::WaitingChildren, WorkflowEvent::UserPaused)
            | (WaitingState::WaitingUser, WorkflowEvent::UserPaused) => WaitingState::Paused,
            (WaitingState::Paused, WorkflowEvent::UserPaused) => WaitingState::Paused,

            // Active/paused states -> Cancelled (user cancellation)
            (WaitingState::Planning, WorkflowEvent::UserCancelled) => WaitingState::Cancelled,
            (WaitingState::PlanningComplete, WorkflowEvent::UserCancelled) => {
                WaitingState::Cancelled
            },
            (WaitingState::Runnable, WorkflowEvent::UserCancelled) => WaitingState::Cancelled,
            (WaitingState::Executing, WorkflowEvent::UserCancelled) => WaitingState::Cancelled,
            (WaitingState::WaitingChildren, WorkflowEvent::UserCancelled) => {
                WaitingState::Cancelled
            },
            (WaitingState::WaitingUser, WorkflowEvent::UserCancelled) => WaitingState::Cancelled,
            (WaitingState::Paused, WorkflowEvent::UserCancelled) => WaitingState::Cancelled,
            (WaitingState::Sleeping, WorkflowEvent::UserCancelled) => WaitingState::Cancelled,

            // Terminal -> Executing (re-execution for scheduled/recurring tasks that reuse the same execution)
            (WaitingState::Completed, WorkflowEvent::ExecutionStart) => WaitingState::Executing,
            (WaitingState::Cancelled, WorkflowEvent::ExecutionStart) => WaitingState::Executing,
            (WaitingState::Failed, WorkflowEvent::ExecutionStart) => WaitingState::Executing,

            // Paused -> previous state (resume)
            (WaitingState::Paused, WorkflowEvent::UserResumed) => execution
                .paused_from_state
                .clone()
                .expect("paused_from_state validated above"),

            // Failed -> Planning/ Runnable (retry) depending on how the execution entered.
            (WaitingState::Failed, WorkflowEvent::UserRetry) => {
                if execution.entry_mode.is_direct() {
                    WaitingState::Runnable
                } else {
                    WaitingState::Planning
                }
            },

            // Invalid transitions - keep current status
            (status, _) => {
                debug!(
                    "[MAGICIAN-V2-ORCHESTRATOR] Invalid transition from {:?} with event {:?}, \
                     keeping current status",
                    status, event
                );
                status.clone()
            },
        };

        if new_status != current_status {
            info!(
                "[MAGICIAN-V2-ORCHESTRATOR] Transitioning execution {} from {:?} to {:?}",
                execution_id, current_status, new_status
            );
            // The task transaction fence is still held here, and this store's
            // execution write guard is that same flock for a task-bound
            // execution. Take the CAS that reuses the held fence instead of
            // re-acquiring it on a second descriptor, which would deadlock.
            let update_result = match task_transaction_guard.as_ref() {
                Some(_) => {
                    self.compare_exchange_execution_status_holding_task_lock_unlocked(
                        execution_id,
                        current_status.clone(),
                        new_status.clone(),
                    )
                    .await
                },
                None => {
                    self.compare_exchange_execution_status_unlocked(
                        execution_id,
                        current_status.clone(),
                        new_status.clone(),
                    )
                    .await
                },
            };
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            drop(task_transaction_guard);
            if !update_result? {
                return Err(format!(
                    "Execution {execution_id} changed from expected state {current_status:?} before {event:?}"
                ));
            }
            self.finalize_execution_status_change(
                &execution,
                current_status.clone(),
                new_status.clone(),
                format!("Workflow event: {:?}", event),
            )
            .await?;

            if matches!(
                new_status,
                WaitingState::Completed | WaitingState::Failed | WaitingState::Cancelled
            ) {
                self.drain_captured_tasks_for_execution(execution_id).await;
                self.remove_delegation_round_progress_best_effort(&execution)
                    .await;
            }

            if execution.task_id.is_some() {
                self.maybe_persist_v3_execution_outcome(execution_id, "workflow status transition")
                    .await;
            }
        } else {
            drop(guard);
            self.prune_execution_status_lock(execution_id, &status_lock);
            drop(task_transaction_guard);
        }

        Ok(new_status)
    }

    async fn drain_captured_tasks_for_execution(&self, execution_id: &str) {
        if let Err(error) = self
            .secret_store_resolver
            .drain_captured_tasks_for_execution_and_flush(execution_id)
            .await
        {
            warn!(
                execution_id = %execution_id,
                error = %error,
                "[MAGICIAN-V2-ORCHESTRATOR] Failed to drain captured session tasks for terminal execution"
            );
        }
    }

    fn spawn_captured_task_drain_for_execution(&self, execution_id: &str) {
        let resolver = Arc::clone(&self.secret_store_resolver);
        let execution_id = execution_id.to_string();
        // Explicit-parent settlement cannot await this non-authoritative cleanup
        // while holding the Artifact lifecycle fence. Register it with the owned
        // execution runtime instead of detaching a Tokio task: shutdown quiesces
        // and joins this work before secret stores are torn down.
        crate::magician_v2::execution::runtime_boundary::spawn_execution_job(move || async move {
            if let Err(error) = resolver
                .drain_captured_tasks_for_execution_and_flush(&execution_id)
                .await
            {
                warn!(
                    execution_id = %execution_id,
                    error = %error,
                    "[MAGICIAN-V2-ORCHESTRATOR] Background explicit-parent secret capture drain failed"
                );
            }
        });
    }

    async fn notify_parent_of_terminal_child_transition(&self, execution: &ExecutionRun) {
        let Some(parent_execution_id) = execution.parent_execution_id.as_deref() else {
            return;
        };

        if let Some(queue) = self.wake_up_queue() {
            match queue
                .schedule_child_completed_wake(parent_execution_id, chrono::Utc::now())
                .await
            {
                Ok(()) => return,
                Err(error) => warn!(
                    execution_id = %execution.id,
                    parent_execution_id = %parent_execution_id,
                    %error,
                    "[MAGICIAN-V2-ORCHESTRATOR] Durable ChildCompleted admission failed; reconciling inline"
                ),
            }
        }

        if let Err(error) =
            Box::pin(self.reconcile_waiting_children_and_continue(parent_execution_id)).await
        {
            warn!(
                execution_id = %execution.id,
                parent_execution_id = %parent_execution_id,
                error = %error,
                "[MAGICIAN-V2-ORCHESTRATOR] Failed to reconcile parent after terminal child transition without WakeUpQueue"
            );
            self.retain_parent_reconciliation_retry(parent_execution_id);
        }
    }

