    /// Create a new slot for parameter elicitation
    pub async fn create_slot(
        &self,
        execution_id: &str,
        name: String,
        schema_json: serde_json::Value,
        required: bool,
        asked_turn_id: Option<String>,
    ) -> Result<V2Slot, String> {
        self.ensure_initialized()?;
        self.conversation_store
            .create_slot(execution_id, name, schema_json, required, asked_turn_id)
            .await
            .map_err(|e| e.to_string())
    }

