    fn register_test_controls(
        orchestrator: &MagicianV2Orchestrator,
        execution_id: &str,
        token: CancellationToken,
    ) -> Uuid {
        let generation = orchestrator.register_active_execution_controls(
            execution_id,
            token,
            Arc::new(AtomicBool::new(false)),
            Arc::new(std::sync::Mutex::new(Vec::new())),
        );
        generation
    }

    /// Register in-process controls *and* publish the matching durable steer
    /// generation, which is the pair a real stateless launch always leaves
    /// behind. The stateless pause preflight closes steer admission against the
    /// sealed generation, so controls registered without one look like an
    /// orphaned row. Tests that deliberately exercise that orphan case keep
    /// using [`register_test_controls`].
    async fn register_test_controls_with_sealed_generation(
        orchestrator: &MagicianV2Orchestrator,
        principal: &str,
        workspace: &str,
        execution_id: &str,
        token: CancellationToken,
    ) -> Uuid {
        let generation = register_test_controls(orchestrator, execution_id, token);
        crate::magician_v2::execution::agentic::run_loop::steer_inbox::activate_control_generation(
            &orchestrator.durable_artifact_workspace,
            principal,
            workspace,
            execution_id,
            &generation.to_string(),
        )
        .await
        .expect("seal durable control generation for test controls");
        generation
    }

    /// The periodic sweep drove a freshly admitted delegated child a second
    /// time inside its run-start window. Activity this process produced
    /// within the grace is ownership; activity from before this process
    /// started is an orphan the startup sweep must still recover.
    #[test]
    fn a_row_this_process_touched_moments_ago_is_owned_not_orphaned() {
        let started = 1_000_000;
        let now = started + 60_000;
        assert!(MagicianV2Orchestrator::recently_owned_in_this_process(
            now - 5_000,
            started,
            now
        ));
        assert!(MagicianV2Orchestrator::recently_owned_in_this_process(
            started, started, now
        ));
        assert!(!MagicianV2Orchestrator::recently_owned_in_this_process(
            started - 1,
            started,
            now
        ));
        assert!(!MagicianV2Orchestrator::recently_owned_in_this_process(
            now - 120_000,
            started,
            now
        ));
    }
    #[test]
    fn exact_retry_reclaims_the_queue_generation_before_sleeping_cas_and_controls() {
        let source = include_str!("v2_orchestrator.rs");
        let admission = source
            .split("async fn admit_exact_placement_retry")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn transition_status_with_expected")
                    .next()
            })
            .expect("exact placement admission body");
        let queue_fence = admission
            .find("lock_execution_retry_claim")
            .expect("cross-process queue generation fence");
        let current_generation = admission
            .find("execution_retry_wake")
            .expect("immutable queue generation validation");
        let claimed_lease = admission
            .find("current_wake.wake_at != claimed_until")
            .expect("exact delivery lease validation under the lifecycle lock");
        let sleeping_cas = admission
            .find("compare_exchange_execution_status_unlocked(")
            .expect("Sleeping -> Executing atomic compare transition");
        let controls = admission
            .find("register_active_execution_controls_with_generation")
            .expect("live controls installation");
        assert!(queue_fence < current_generation);
        assert!(current_generation < claimed_lease);
        assert!(claimed_lease < sleeping_cas);
        assert!(sleeping_cas < controls);
    }

