    #[test]
    fn delegate_tool_merge_is_stable_across_catalog_iteration_order() {
        let alpha_tools = vec![
            delegate_merge_test_tool("shared-search", "alpha search"),
            delegate_merge_test_tool("alpha-only", "alpha only"),
        ];
        let zulu_tools = vec![
            delegate_merge_test_tool("shared-search", "zulu search"),
            delegate_merge_test_tool("zulu-only", "zulu only"),
        ];

        let mut forward = Vec::new();
        MagicianV2Orchestrator::merge_delegate_tool_entries(
            &mut forward,
            vec![
                ("alpha-agent", alpha_tools.as_slice()),
                ("zulu-agent", zulu_tools.as_slice()),
            ],
        );
        let mut reversed = Vec::new();
        MagicianV2Orchestrator::merge_delegate_tool_entries(
            &mut reversed,
            vec![
                ("zulu-agent", zulu_tools.as_slice()),
                ("alpha-agent", alpha_tools.as_slice()),
            ],
        );

        let projection = |tools: &[ToolInfo]| {
            tools
                .iter()
                .map(|tool| {
                    (
                        tool.name.clone(),
                        tool.description.clone(),
                        tool.providing_agent_id.clone(),
                    )
                })
                .collect::<Vec<_>>()
        };
        assert_eq!(projection(&forward), projection(&reversed));
        assert_eq!(
            forward
                .iter()
                .find(|tool| tool.name == "shared-search")
                .and_then(|tool| tool.providing_agent_id.as_deref()),
            Some("alpha-agent"),
            "same-named delegate tools must resolve to one stable owner"
        );

        let mut direct = vec![delegate_merge_test_tool("shared-search", "direct search")];
        MagicianV2Orchestrator::merge_delegate_tool_entries(
            &mut direct,
            vec![
                ("zulu-agent", zulu_tools.as_slice()),
                ("alpha-agent", alpha_tools.as_slice()),
            ],
        );
        let shared = direct
            .iter()
            .find(|tool| tool.name == "shared-search")
            .expect("direct tool remains present");
        assert_eq!(shared.description, "direct search");
        assert_eq!(shared.providing_agent_id, None, "direct ownership must win");
    }

