    #[test]
    fn control_tree_validation_rejects_wrong_parent_root_and_scope() {
        let mut root = test_execution_run("root", WaitingState::WaitingChildren);
        root.root_execution_id = Some("root".to_string());
        let mut child = test_execution_run("child", WaitingState::WaitingUser);
        child.parent_execution_id = Some("root".to_string());
        child.root_execution_id = Some("root".to_string());
        assert!(MagicianV2Orchestrator::validate_control_tree_child(&root, &root, &child).is_ok());

        let mut wrong_parent = child.clone();
        wrong_parent.parent_execution_id = Some("other-parent".to_string());
        assert!(
            MagicianV2Orchestrator::validate_control_tree_child(&root, &root, &wrong_parent)
                .expect_err("wrong parent must fail")
                .contains("not linked")
        );

        let mut wrong_root = child.clone();
        wrong_root.root_execution_id = Some("other-root".to_string());
        assert!(
            MagicianV2Orchestrator::validate_control_tree_child(&root, &root, &wrong_root)
                .expect_err("wrong root must fail")
                .contains("belongs to root")
        );

        child.workspace = "other-workspace".to_string();
        assert!(
            MagicianV2Orchestrator::validate_control_tree_child(&root, &root, &child)
                .expect_err("cross-scope child must fail")
                .contains("escapes the authorized scope")
        );
    }

    #[test]
    fn durable_foreign_epoch_precedes_serving_process_driver_default() {
        use crate::magician_v2::execution::agentic::run_loop::ExecutionDriver;

        let fallback_called = std::sync::atomic::AtomicBool::new(false);
        let selected = operator_execution_driver(None, true, || {
            fallback_called.store(true, Ordering::SeqCst);
            ExecutionDriver::Inprocess
        });
        assert_eq!(selected, ExecutionDriver::Stateless);
        assert!(
            !fallback_called.load(Ordering::SeqCst),
            "a foreign sealed epoch must win without consulting this API peer's rollback setting"
        );

        assert_eq!(
            operator_execution_driver(Some(ExecutionDriver::Inprocess), true, || {
                ExecutionDriver::Stateless
            }),
            ExecutionDriver::Inprocess,
            "resident controls remain the exact per-run selection authority"
        );
    }

