    #[tokio::test]
    async fn steer_queue_is_bounded_and_removed_with_active_controls() {
        let Some((orchestrator, _, _)) = build_orchestrator_with_ask_loop().await else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let execution_id = "bounded-steer-controls";
        orchestrator
            .create_execution_with_id(
                "principal",
                "workspace",
                None,
                "test-agent",
                execution_id,
                Some("task-bounded-steer-controls".to_string()),
                Some(execution_id.to_string()),
            )
            .await
            .expect("create steer execution");
        let queue = Arc::new(std::sync::Mutex::new(Vec::<String>::new()));

        let generation = orchestrator.register_active_execution_controls(
            execution_id,
            CancellationToken::new(),
            Arc::new(AtomicBool::new(false)),
            Arc::clone(&queue),
        );
        {
            let mut controls = orchestrator
                .active_execution_controls
                .get_mut(execution_id)
                .expect("registered controls");
            Arc::make_mut(controls.value_mut()).execution_driver =
                crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::Inprocess;
        }

        assert_eq!(
            orchestrator.steer_execution(execution_id, "  ").await,
            Err(SteerExecutionError::EmptyMessage)
        );
        let oversized = "x".repeat(MAX_STEER_MESSAGE_BYTES + 1);
        assert_eq!(
            orchestrator.steer_execution(execution_id, &oversized).await,
            Err(SteerExecutionError::MessageTooLong)
        );

        for index in 0..MAX_PENDING_STEERS {
            assert_eq!(
                orchestrator
                    .steer_execution(execution_id, &format!("redirect {index}"))
                    .await,
                Ok(())
            );
        }
        assert_eq!(
            orchestrator
                .steer_execution(execution_id, "one too many")
                .await,
            Err(SteerExecutionError::QueueFull)
        );
        let pending = queue.lock().expect("steer queue lock");
        assert_eq!(pending.len(), MAX_PENDING_STEERS);
        assert_eq!(pending.first().map(String::as_str), Some("redirect 0"));
        drop(pending);

        orchestrator.clear_active_execution_controls(execution_id, generation);

        assert!(!orchestrator
            .active_execution_controls
            .contains_key(execution_id));
        assert_eq!(
            orchestrator.steer_execution(execution_id, "too late").await,
            Err(SteerExecutionError::NotActive)
        );
    }

    #[tokio::test]
    async fn steer_routes_once_to_the_stateless_inbox_and_not_the_rollback_queue() {
        let Some((orchestrator, _, _)) = build_orchestrator_with_ask_loop().await else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let execution_id = "durable-steer-controls";
        orchestrator
            .create_execution_with_id(
                "principal",
                "workspace",
                None,
                "test-agent",
                execution_id,
                Some("task-durable-steer-controls".to_string()),
                Some(execution_id.to_string()),
            )
            .await
            .expect("create steer execution");
        orchestrator
            .transition_status_from_runtime(execution_id, WorkflowEvent::ReadyToExecute)
            .await
            .expect("ready execution");
        orchestrator
            .transition_status_from_runtime(execution_id, WorkflowEvent::ExecutionStart)
            .await
            .expect("start execution");

        let queue = Arc::new(std::sync::Mutex::new(Vec::<String>::new()));
        let generation = orchestrator.register_active_execution_controls(
            execution_id,
            CancellationToken::new(),
            Arc::new(AtomicBool::new(false)),
            Arc::clone(&queue),
        );
        {
            let mut controls = orchestrator
                .active_execution_controls
                .get_mut(execution_id)
                .expect("registered controls");
            Arc::make_mut(controls.value_mut()).execution_driver =
                crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::Stateless;
        }

        assert_eq!(
            orchestrator
                .steer_execution(execution_id, "follow the durable route")
                .await,
            Ok(())
        );
        assert!(
            queue.lock().expect("rollback queue lock").is_empty(),
            "stateless admission must not dual-publish into the resident queue"
        );
        let claimed = crate::magician_v2::execution::agentic::run_loop::steer_inbox::claim(
            &orchestrator.durable_artifact_workspace,
            "principal",
            "workspace",
            execution_id,
            &generation.to_string(),
            "durable-steer-segment",
            3,
        )
        .await
        .expect("claim durable steer")
        .expect("durable steer batch");
        assert_eq!(claimed.messages, vec!["follow the durable route"]);
        crate::magician_v2::execution::agentic::run_loop::steer_inbox::acknowledge(
            &orchestrator.durable_artifact_workspace,
            "principal",
            "workspace",
            execution_id,
            "durable-steer-segment",
            &claimed.receipt,
        )
        .await
        .expect("ack durable steer");
    }

    #[tokio::test]
    async fn foreign_stateless_epoch_keeps_control_state_and_steer_wired() {
        let Some((orchestrator, _, _)) = build_orchestrator_with_ask_loop().await else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let pause_root = tempfile::TempDir::new().expect("temporary durable pause root");
        orchestrator.set_full_pause_store(Arc::new(FullPauseStore::with_persistence(
            pause_root.path(),
        )));
        let execution_id = "foreign-stateless-operator-controls";
        orchestrator
            .create_execution_with_id(
                "principal",
                "workspace",
                None,
                "test-agent",
                execution_id,
                Some("task-foreign-stateless-controls".to_string()),
                Some(execution_id.to_string()),
            )
            .await
            .expect("create foreign stateless execution");
        orchestrator
            .transition_status_from_runtime(execution_id, WorkflowEvent::ReadyToExecute)
            .await
            .expect("ready foreign execution");
        orchestrator
            .transition_status_from_runtime(execution_id, WorkflowEvent::ExecutionStart)
            .await
            .expect("start foreign execution");

        let generation = Uuid::new_v4();
        crate::magician_v2::execution::agentic::run_loop::steer_inbox::activate_control_generation(
            &orchestrator.durable_artifact_workspace,
            "principal",
            "workspace",
            execution_id,
            &generation.to_string(),
        )
        .await
        .expect("publish foreign durable controls");
        assert!(
            !orchestrator
                .active_execution_controls
                .contains_key(execution_id),
            "the serving process must not need the worker's resident token"
        );

        let snapshot = orchestrator
            .execution_tree_control_snapshot(execution_id)
            .await
            .expect("cross-process control snapshot");
        assert!(snapshot.active, "foreign durable steer must be advertised");
        assert!(
            snapshot.capabilities.can_pause,
            "foreign durable manual pause must be advertised"
        );
        assert_eq!(
            orchestrator
                .steer_execution(execution_id, "route through the shared epoch")
                .await,
            Ok(())
        );
        let claimed = crate::magician_v2::execution::agentic::run_loop::steer_inbox::claim(
            &orchestrator.durable_artifact_workspace,
            "principal",
            "workspace",
            execution_id,
            &generation.to_string(),
            "foreign-steer-segment",
            1,
        )
        .await
        .expect("claim foreign steer")
        .expect("foreign steer batch");
        assert_eq!(claimed.messages, vec!["route through the shared epoch"]);
    }

