    #[tokio::test]
    async fn stale_generation_cleanup_preserves_replacement_controls() {
        let Some((orchestrator, _, _)) = build_orchestrator_with_ask_loop().await else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let execution_id = "replacement-generation-controls";
        orchestrator
            .create_execution_with_id(
                "principal",
                "workspace",
                None,
                "test-agent",
                execution_id,
                Some("task-replacement-generation-controls".to_string()),
                Some(execution_id.to_string()),
            )
            .await
            .expect("create replacement-control execution");
        // A steer is admitted against a *running* row, and on the stateless arm
        // against its sealed generation as well -- the pair a real launch leaves
        // behind. Without both, replacement controls that ARE wired look like an
        // orphaned row and the steer below is refused as NotActive.
        orchestrator
            .transition_status_from_runtime(execution_id, WorkflowEvent::ReadyToExecute)
            .await
            .expect("ready replacement-control execution");
        orchestrator
            .transition_status_from_runtime(execution_id, WorkflowEvent::ExecutionStart)
            .await
            .expect("start replacement-control execution");
        let old_generation =
            register_test_controls(&orchestrator, execution_id, CancellationToken::new());
        let replacement_queue = Arc::new(std::sync::Mutex::new(Vec::new()));
        let replacement_driver =
            crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::from_env();
        let replacement_generation = orchestrator.register_active_execution_controls(
            execution_id,
            CancellationToken::new(),
            Arc::new(AtomicBool::new(false)),
            Arc::clone(&replacement_queue),
        );
        crate::magician_v2::execution::agentic::run_loop::steer_inbox::activate_control_generation(
            &orchestrator.durable_artifact_workspace,
            "principal",
            "workspace",
            execution_id,
            &replacement_generation.to_string(),
        )
        .await
        .expect("seal the replacement control generation");

        assert!(!orchestrator.clear_active_execution_controls(execution_id, old_generation));
        assert!(orchestrator.is_active_control_generation(execution_id, replacement_generation));
        assert_eq!(
            orchestrator
                .steer_execution(execution_id, "replacement steer")
                .await,
            Ok(())
        );
        match replacement_driver {
            crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::Inprocess => {
                assert_eq!(
                    replacement_queue
                        .lock()
                        .expect("replacement queue")
                        .as_slice(),
                    ["replacement steer"]
                );
            },
            crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::Stateless => {
                // On the stateless arm the steer is delivered through the
                // durable inbox, not the process-local queue -- a foreign
                // worker holds the real one. Admission is bound to the control
                // generation, so claiming under the *replacement* generation
                // proves the replacement survived stale-generation cleanup.
                let claimed = crate::magician_v2::execution::agentic::run_loop::steer_inbox::claim(
                    &orchestrator.durable_artifact_workspace,
                    "principal",
                    "workspace",
                    execution_id,
                    &replacement_generation.to_string(),
                    "replacement-control-segment",
                    1,
                )
                .await
                .expect("claim under the replacement generation")
                .expect("the replacement generation holds the steer");
                assert_eq!(claimed.messages, vec!["replacement steer".to_string()]);
                assert!(replacement_queue
                    .lock()
                    .expect("replacement queue")
                    .is_empty());
            },
        }
    }

    #[tokio::test]
    async fn cancellation_keeps_generation_tombstone_until_settlement() {
        let Some((orchestrator, _, _)) = build_orchestrator_with_ask_loop().await else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let execution_id = "cancel-generation-tombstone";
        orchestrator
            .create_execution_with_id(
                "principal",
                "workspace",
                None,
                "test-agent",
                execution_id,
                Some("task-cancel-generation-tombstone".to_string()),
                Some(execution_id.to_string()),
            )
            .await
            .expect("create cancellable execution");
        let cancelled_token = CancellationToken::new();
        let cancelled_generation =
            register_test_controls(&orchestrator, execution_id, cancelled_token.clone());

        assert!(orchestrator
            .cancel_execution(execution_id)
            .await
            .expect("cancellation request should succeed"));
        assert!(cancelled_token.is_cancelled());
        assert!(
            !orchestrator.is_active_control_generation(execution_id, cancelled_generation),
            "the settled cancellation should retire its process-local generation"
        );

        let replacement_generation =
            register_test_controls(&orchestrator, execution_id, CancellationToken::new());
        assert!(!orchestrator.clear_active_execution_controls(execution_id, cancelled_generation));
        assert!(orchestrator.is_active_control_generation(execution_id, replacement_generation));
    }

