    async fn seed_review_task_shell(
        orchestrator: &Arc<MagicianV2Orchestrator>,
        title: &str,
    ) -> (TempDir, Arc<ArtifactV2Service>, String, String) {
        let task_dir = TempDir::new().expect("review task tempdir");
        let service = Arc::new(ArtifactV2Service::with_orchestrator(
            task_dir.path().join("magician_data_v3"),
            Arc::clone(orchestrator),
            crate::magician_v2::gaui::MuijStorage::new(task_dir.path().join("muij")),
        ));
        orchestrator.set_artifact_v2_service(Arc::clone(&service));
        let (task, execution) = service
            .create_task_with_execution_shell(crate::magician_v2::artifact_v2::CreateTaskInput {
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                title: title.to_string(),
                description: title.to_string(),
                agent_id: "manager".to_string(),
                goal_id: None,
                ui_thread_id: crate::magician_v2::storage::task_models::default_ui_thread_id(),
                priority: None,
                due_date: None,
                tags: Vec::new(),
                created_by: "test".to_string(),
                depends_on: Vec::new(),
                approved: true,
                schedule: None,
                output_mode: crate::magician_v2::artifact_v2::models::TaskOutputMode::Accumulate,
                chat_session_id: None,
                lifecycle: crate::magician_v2::artifact_v2::models::TaskLifecycle::default(),
                sync_mode: crate::magician_v2::artifact_v2::models::TaskSyncMode::default(),
            })
            .await
            .expect("create review-backed task shell");
        let scope = ScopeRef::system_internal_unauthenticated(
            &task.manifest.principal,
            &task.manifest.workspace,
        );
        service
            .activate_execution(
                &scope,
                &task.manifest.task_id,
                &execution.state.execution_id,
            )
            .await
            .expect("activate review-backed root shell");
        (
            task_dir,
            service,
            task.manifest.task_id,
            execution.state.execution_id,
        )
    }

    #[tokio::test]
    async fn reconcile_waiting_children_blocks_when_child_review_is_still_open() {
        use crate::magician_v2::execution::file_edit::proposal::CodeChangeProposalStore;
        use crate::magician_v2::execution::file_edit::transaction::TransactionScope;

        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let (_task_dir, v3_service, task_id, parent_id) =
            seed_review_task_shell(&orchestrator, "Pending review parent").await;
        let child_id = "review-open-child";
        let now = Utc::now().timestamp_millis();
        store
            .insert_execution(ExecutionRun {
                id: parent_id.clone(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                task_id: Some(task_id.clone()),
                root_execution_id: Some(parent_id.clone()),
                title: Some("parent".to_string()),
                waiting_state: WaitingState::WaitingChildren,
                created_at: now,
                updated_at: now,
                processing_correlation_id: None,
                current_stage: None,
                current_provider: None,
                escalation_trigger: None,
                parent_execution_id: None,
                child_execution_ids: vec![child_id.to_string()],
                active_owner_agent_id: "manager".to_string(),
                owner_stack: Vec::new(),
                active_delegation_group: vec![child_id.to_string()],
                timeout_secs: None,
                delegation_chain: Vec::new(),
                work_authority: None,
                paused_from_state: None,
                entry_mode: ExecutionEntryMode::PlanningBacked,
            })
            .await;
        store
            .insert_execution(ExecutionRun {
                id: child_id.to_string(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                task_id: Some(task_id.clone()),
                root_execution_id: Some(parent_id.clone()),
                title: Some("Implement change".to_string()),
                waiting_state: WaitingState::Completed,
                created_at: now,
                updated_at: now,
                processing_correlation_id: None,
                current_stage: None,
                current_provider: None,
                escalation_trigger: None,
                parent_execution_id: Some(parent_id.clone()),
                child_execution_ids: Vec::new(),
                active_owner_agent_id: "principal-software-engineer".to_string(),
                owner_stack: Vec::new(),
                active_delegation_group: Vec::new(),
                timeout_secs: None,
                delegation_chain: Vec::new(),
                work_authority: None,
                paused_from_state: None,
                entry_mode: ExecutionEntryMode::PlanningBacked,
            })
            .await;
        assert!(v3_service
            .record_runtime_child_execution_best_effort(
                &parent_id,
                child_id,
                "principal-software-engineer",
                "Implement change",
            )
            .await
            .expect("record review child in Artifact V3"));

        let scope_root = orchestrator
            .durable_artifact_workspace()
            .scope_root("user", "workspace");
        std::fs::create_dir_all(&scope_root).expect("scope root should exist");
        CodeChangeProposalStore::new(&scope_root)
            .stage_patch_with_apply_root(
                TransactionScope {
                    principal: "user".to_string(),
                    workspace: "workspace".to_string(),
                },
                "Pending review",
                "--- a/src/lib.rs\n+++ b/src/lib.rs\n@@ -1 +1 @@\n-old\n+new\n",
                "session-1",
                Vec::new(),
                Some(scope_root.join("repo")),
                Some(task_id.clone()),
                Some(child_id.to_string()),
            )
            .expect("proposal should stage");

        let resumed = orchestrator
            .reconcile_waiting_children(&parent_id)
            .await
            .expect("reconcile should succeed");
        assert!(
            !resumed,
            "a terminal child with an unresolved review should keep the parent blocked"
        );
        let parent = orchestrator
            .get_execution(&parent_id)
            .await
            .expect("parent should load");
        assert_eq!(parent.waiting_state, WaitingState::WaitingChildren);

        let summary = orchestrator
            .load_execution_summary_record(&parent_id)
            .await
            .expect("parent summary should persist before the review gate returns");
        assert!(summary.summary.contains("\"review_open\":true"));
        assert!(!summary.summary.contains("terminal_success"));
    }

    #[tokio::test]
    async fn reject_orphaned_proposals_unblocks_parent_from_review_gate() {
        // Regression: a force-terminated child left an orphaned Pending proposal
        // whose approval channel is gone, and the WaitingChildren review gate had
        // no resolver for it — so the parent stayed parked forever.
        // `reject_orphaned_proposals_for_execution` (invoked from
        // `force_child_failure`) must clear `review_open` so the parent completes.
        use crate::magician_v2::execution::file_edit::proposal::{
            CodeChangeProposalStatus, CodeChangeProposalStore,
        };
        use crate::magician_v2::execution::file_edit::transaction::TransactionScope;

        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let (_task_dir, v3_service, task_id, parent_id) =
            seed_review_task_shell(&orchestrator, "Orphan review parent").await;
        let child_id = "orphan-reject-child";
        let now = Utc::now().timestamp_millis();
        store
            .insert_execution(ExecutionRun {
                id: parent_id.clone(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                task_id: Some(task_id.clone()),
                root_execution_id: Some(parent_id.clone()),
                title: Some("parent".to_string()),
                waiting_state: WaitingState::WaitingChildren,
                created_at: now,
                updated_at: now,
                processing_correlation_id: None,
                current_stage: None,
                current_provider: None,
                escalation_trigger: None,
                parent_execution_id: None,
                child_execution_ids: vec![child_id.to_string()],
                active_owner_agent_id: "manager".to_string(),
                owner_stack: Vec::new(),
                active_delegation_group: vec![child_id.to_string()],
                timeout_secs: None,
                delegation_chain: Vec::new(),
                work_authority: None,
                paused_from_state: None,
                entry_mode: ExecutionEntryMode::PlanningBacked,
            })
            .await;
        store
            .insert_execution(ExecutionRun {
                id: child_id.to_string(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                task_id: Some(task_id.clone()),
                root_execution_id: Some(parent_id.clone()),
                title: Some("Implement change".to_string()),
                // Force-failed child: terminal, but its staged diff was never approved.
                waiting_state: WaitingState::Failed,
                created_at: now,
                updated_at: now,
                processing_correlation_id: None,
                current_stage: None,
                current_provider: None,
                escalation_trigger: None,
                parent_execution_id: Some(parent_id.clone()),
                child_execution_ids: Vec::new(),
                active_owner_agent_id: "principal-software-engineer".to_string(),
                owner_stack: Vec::new(),
                active_delegation_group: Vec::new(),
                timeout_secs: None,
                delegation_chain: Vec::new(),
                work_authority: None,
                paused_from_state: None,
                entry_mode: ExecutionEntryMode::PlanningBacked,
            })
            .await;
        assert!(v3_service
            .record_runtime_child_execution_best_effort(
                &parent_id,
                child_id,
                "principal-software-engineer",
                "Implement change",
            )
            .await
            .expect("record orphaned-review child in Artifact V3"));

        let scope_root = orchestrator
            .durable_artifact_workspace()
            .scope_root("user", "workspace");
        std::fs::create_dir_all(&scope_root).expect("scope root should exist");
        let proposal = CodeChangeProposalStore::new(&scope_root)
            .stage_patch_with_apply_root(
                TransactionScope {
                    principal: "user".to_string(),
                    workspace: "workspace".to_string(),
                },
                "Pending review",
                "--- a/src/lib.rs\n+++ b/src/lib.rs\n@@ -1 +1 @@\n-old\n+new\n",
                "session-1",
                Vec::new(),
                Some(scope_root.join("repo")),
                Some(task_id.clone()),
                Some(child_id.to_string()),
            )
            .expect("proposal should stage");

        // The orphaned Pending review parks the parent.
        assert!(
            !orchestrator
                .reconcile_waiting_children(&parent_id)
                .await
                .expect("reconcile should succeed"),
            "an unresolved review should block the parent"
        );

        // Force-terminal cleanup rejects the orphaned proposal...
        orchestrator
            .reject_orphaned_proposals_for_execution(child_id)
            .await;
        let rejected = CodeChangeProposalStore::new(&scope_root)
            .list_for_task(&task_id)
            .into_iter()
            .find(|candidate| candidate.id == proposal.id)
            .expect("proposal should still be present");
        assert!(
            matches!(rejected.status, CodeChangeProposalStatus::Rejected),
            "the orphaned proposal should be rejected"
        );

        // ...so the parent is no longer stranded behind the review gate.
        assert!(
            orchestrator
                .reconcile_waiting_children(&parent_id)
                .await
                .expect("reconcile should succeed"),
            "the parent should resume once the orphaned review is rejected"
        );
    }

    #[tokio::test]
    async fn apply_task_state_tool_runtime_gating_injects_task_state_for_task_backed_runs() {
        let catalog = MockTaskStateToolCatalog;
        let mut ctx = crate::magician_v2::execution::AgenticContext::new("goal", "criteria");
        ctx.task_id = Some("task-123".to_string());

        apply_task_state_tool_runtime_gating(&catalog, &mut ctx).await;

        assert!(ctx
            .merged_agent_tools
            .iter()
            .any(|tool| tool.name == "task_state"));
    }

    #[tokio::test]
    async fn apply_task_state_tool_runtime_gating_syncs_tool_lane_for_builtin_only_agents() {
        // Regression: a files-only agent enters with allowed_action_types = ["file"]
        // (no "tool" because profile-build time saw no direct pack tools).
        // After injection, "tool" must be present so task_state dispatch isn't
        // rejected by validate_action_against_allowlists.
        let catalog = MockTaskStateToolCatalog;
        let mut ctx = crate::magician_v2::execution::AgenticContext::new("goal", "criteria");
        ctx.task_id = Some("task-123".to_string());
        ctx.allowed_action_types = Some(vec!["file".to_string()]);

        apply_task_state_tool_runtime_gating(&catalog, &mut ctx).await;

        assert!(ctx
            .merged_agent_tools
            .iter()
            .any(|tool| tool.name == "task_state"));
        let allowed = ctx
            .allowed_action_types
            .as_ref()
            .expect("allowed_action_types should remain Some");
        assert!(
            allowed.iter().any(|entry| entry == "tool"),
            "expected 'tool' to be synced into allowed_action_types, got {:?}",
            allowed
        );
    }

    #[tokio::test]
    async fn apply_task_state_tool_runtime_gating_drops_tool_lane_when_stripped() {
        // Mirror case: a non-task execution enters with a leftover task_state
        // tool and "tool" in allowed_action_types. After stripping, if no
        // direct pack tools remain, "tool" should be dropped.
        let catalog = MockTaskStateToolCatalog;
        let mut ctx = crate::magician_v2::execution::AgenticContext::new("goal", "criteria");
        ctx.merged_agent_tools.push(ToolInfo {
            name: "task_state".to_string(),
            description: "Persist task state".to_string(),
            category: "state".to_string(),
            categories: vec!["state".to_string()],
            parameters: Vec::new(),
            enhanced_description: None,
            keywords: vec![],
            use_cases: vec![],
            composition_category: Some("state_management".to_string()),
            providing_agent_id: None,
        });
        ctx.allowed_action_types = Some(vec!["file".to_string(), "tool".to_string()]);

        apply_task_state_tool_runtime_gating(&catalog, &mut ctx).await;

        assert!(ctx.merged_agent_tools.is_empty());
        let allowed = ctx
            .allowed_action_types
            .as_ref()
            .expect("allowed_action_types should remain Some");
        assert!(
            !allowed.iter().any(|entry| entry == "tool"),
            "'tool' should be dropped once no direct pack tools remain, got {:?}",
            allowed
        );
    }

