    #[test]
    fn plan_graph_initial_url_comes_from_url_parameter() {
        let graph = PlanGraph {
            steps: vec![PlanStep {
                id: "browser".to_string(),
                task: "Open the site".to_string(),
                parameters: HashMap::from([(
                    "url".to_string(),
                    serde_json::json!("https://example.com/login"),
                )]),
                ..Default::default()
            }],
            ..Default::default()
        };

        assert_eq!(
            derive_initial_url_for_plan_graph(&graph).as_deref(),
            Some("https://example.com/login")
        );
    }

    #[test]
    fn source_filenames_are_not_inferred_as_initial_urls() {
        for filename in ["hello.py", "util.rs", "main.go", "client.ts", "site.dev"] {
            let goal = format!("Read-only: explain what {filename} does");
            assert_eq!(
                derive_initial_url_for_goal(None, &goal),
                None,
                "source filename must not arm browser navigation: {filename}"
            );
        }
        assert_eq!(
            derive_initial_url_for_goal(None, "Open https://example.com/docs, then summarize it")
                .as_deref(),
            Some("https://example.com/docs")
        );
        assert_eq!(
            derive_initial_url_for_goal(Some(" https://typed.example/path "), "hello.py")
                .as_deref(),
            Some("https://typed.example/path"),
            "a typed orchestration override remains authoritative"
        );
    }

