    #[test]
    fn select_ranked_action_binding_candidates_keeps_noisy_then_useful_matches() {
        let action = crate::magician_v2::api_mining::correlator::ActionEvent {
            action_id: "page-load-1".to_string(),
            action_type: "PageLoad".to_string(),
            timestamp_ms: 1_000,
            frame_id: None,
            user_values: vec!["rust".to_string()],
            page_url: Some("https://hn.algolia.com/?q=rust".to_string()),
            action_signature: Some("https://hn.algolia.com/|query_keys=q".to_string()),
            semantic_signature: Some("page_load:https://hn.algolia.com/?q".to_string()),
            element_metadata: HashMap::new(),
            action_params: HashMap::from([
                ("page_query_q".to_string(), "rust".to_string()),
                ("query".to_string(), "rust".to_string()),
                ("text".to_string(), "rust".to_string()),
            ]),
            page_origin: Some("https://hn.algolia.com".to_string()),
            page_path_template: Some("/".to_string()),
        };

        let make_trace = |request_id: &str,
                          url: &str,
                          request_body: Option<&str>,
                          timestamp: i64|
         -> crate::magician_v2::api_mining::types::NetworkTraceEvent {
            crate::magician_v2::api_mining::types::NetworkTraceEvent {
                request_id: request_id.to_string(),
                method: "POST".to_string(),
                url: url.to_string(),
                resource_type: Some("XHR".to_string()),
                frame_id: None,
                tab_id: None,
                thread_id: None,
                request_headers: HashMap::new(),
                request_body: request_body.map(str::to_string),
                response_headers: HashMap::new(),
                response_body: None,
                body_unavailable_reason: None,
                failure_error_text: None,
                failure_blocked_reason: None,
                failure_canceled: None,
                status: 200,
                timing: crate::magician_v2::api_mining::types::RequestTiming {
                    request_time: timestamp as f64,
                    dns_duration: None,
                    connect_duration: None,
                    ssl_duration: None,
                    ttfb: None,
                    total_duration: 25.0,
                },
                initiator: crate::magician_v2::api_mining::types::RequestInitiator {
                    initiator_type: "script".to_string(),
                    stack: None,
                    url: action.page_url.clone(),
                },
                timestamp,
                request_size: request_body.map(str::len).unwrap_or_default() as u64,
                response_size: 0,
                capture_source: None,
            }
        };

        let noisy_trace = make_trace(
            "ga",
            "https://www.google-analytics.com/j/collect?dl=https%3A%2F%2Fhn.algolia.com%2F%3Fq%3Drust",
            None,
            1_100,
        );
        let useful_trace = make_trace(
            "algolia",
            "https://uj5wyc0l7x-dsn.algolia.net/1/indexes/Item_dev/query",
            Some(r#"{"query":"rust"}"#),
            3_300,
        );
        let noisy = crate::magician_v2::api_mining::correlator::CorrelatedRequest {
            trace: noisy_trace,
            action_id: action.action_id.clone(),
            confidence: 0.75,
            signals: crate::magician_v2::api_mining::correlator::CorrelationSignals {
                timing: true,
                timing_close: true,
                frame_match: false,
                initiator_match: false,
                value_match: true,
                xhr_or_fetch: true,
            },
        };
        let useful = crate::magician_v2::api_mining::correlator::CorrelatedRequest {
            trace: useful_trace,
            action_id: action.action_id.clone(),
            confidence: 0.45,
            signals: crate::magician_v2::api_mining::correlator::CorrelationSignals {
                timing: false,
                timing_close: false,
                frame_match: false,
                initiator_match: false,
                value_match: true,
                xhr_or_fetch: true,
            },
        };

        let ranked = select_ranked_action_binding_candidates(&action, &[&noisy, &useful]);

        assert_eq!(ranked.len(), 2);
        assert_eq!(ranked[0].trace.request_id, "ga");
        assert_eq!(ranked[1].trace.request_id, "algolia");
    }

    #[test]
    fn action_binding_correlation_keeps_useful_request_after_noisy_top_ten() {
        let action = crate::magician_v2::api_mining::correlator::ActionEvent {
            action_id: "page-load-1".to_string(),
            action_type: "PageLoad".to_string(),
            timestamp_ms: 1_000,
            frame_id: None,
            user_values: vec!["rust".to_string()],
            page_url: Some("https://hn.algolia.com/?q=rust".to_string()),
            action_signature: Some("https://hn.algolia.com/|query_keys=q".to_string()),
            semantic_signature: Some("page_load:https://hn.algolia.com/?q".to_string()),
            element_metadata: HashMap::new(),
            action_params: HashMap::from([
                ("page_query_q".to_string(), "rust".to_string()),
                ("query".to_string(), "rust".to_string()),
                ("text".to_string(), "rust".to_string()),
            ]),
            page_origin: Some("https://hn.algolia.com".to_string()),
            page_path_template: Some("/".to_string()),
        };

        let make_trace = |request_id: &str,
                          url: &str,
                          request_body: Option<&str>,
                          timestamp: i64|
         -> crate::magician_v2::api_mining::types::NetworkTraceEvent {
            crate::magician_v2::api_mining::types::NetworkTraceEvent {
                request_id: request_id.to_string(),
                method: "POST".to_string(),
                url: url.to_string(),
                resource_type: Some("XHR".to_string()),
                frame_id: None,
                tab_id: None,
                thread_id: None,
                request_headers: HashMap::new(),
                request_body: request_body.map(str::to_string),
                response_headers: HashMap::new(),
                response_body: None,
                body_unavailable_reason: None,
                failure_error_text: None,
                failure_blocked_reason: None,
                failure_canceled: None,
                status: 200,
                timing: crate::magician_v2::api_mining::types::RequestTiming {
                    request_time: timestamp as f64,
                    dns_duration: None,
                    connect_duration: None,
                    ssl_duration: None,
                    ttfb: None,
                    total_duration: 25.0,
                },
                initiator: crate::magician_v2::api_mining::types::RequestInitiator {
                    initiator_type: "script".to_string(),
                    stack: None,
                    url: action.page_url.clone(),
                },
                timestamp,
                request_size: request_body.map(str::len).unwrap_or_default() as u64,
                response_size: 0,
                capture_source: None,
            }
        };

        let mut traces = (0..12)
            .map(|index| {
                make_trace(
                    &format!("noise-{index}"),
                    &format!("https://metrics.example.com/collect?dl=https%3A%2F%2Fhn.algolia.com%2F%3Fq%3Drust&n={index}"),
                    None,
                    1_010 + index,
                )
            })
            .collect::<Vec<_>>();
        traces.push(make_trace(
            "algolia",
            "https://uj5wyc0l7x-dsn.algolia.net/1/indexes/Item_dev/query",
            Some(r#"{"query":"rust"}"#),
            500,
        ));

        let capped = crate::magician_v2::api_mining::correlator::Correlator::default()
            .correlate_all(&[action.clone()], &traces);
        assert_eq!(capped.len(), 10);
        assert!(
            capped
                .iter()
                .all(|candidate| candidate.trace.request_id != "algolia"),
            "default top-10 correlation should demonstrate the truncation failure"
        );

        let uncapped = crate::magician_v2::api_mining::correlator::Correlator::new(
            action_binding_correlator_config(),
        )
        .correlate_all(&[action.clone()], &traces);
        let refs = uncapped.iter().collect::<Vec<_>>();
        let ranked = select_ranked_action_binding_candidates(&action, &refs);
        assert!(
            ranked
                .iter()
                .any(|candidate| candidate.trace.request_id == "algolia"),
            "binding learning must still see lower-confidence useful API requests"
        );
    }

