    async fn build_orchestrator_with_ask_loop() -> Option<(
        Arc<MagicianV2Orchestrator>,
        Arc<ClarificationSessionManager>,
        Arc<TestStore>,
    )> {
        let store = Arc::new(TestStore::default());
        let store_for_services = Arc::clone(&store) as Arc<dyn V2ConversationStore>;
        let test_broadcaster = Arc::new(RuntimeTransportBroadcaster::new(100));
        let session_manager = Arc::new(ClarificationSessionManager::new(
            Arc::clone(&store_for_services),
            Arc::clone(&test_broadcaster),
        ));
        let confidence_service = Arc::new(ConfidenceService::default());
        let tracker = Arc::new(StateTracker::with_confidence_service(
            store_for_services.clone(),
            confidence_service.clone(),
        ));
        let policy = Arc::new(BudgetPolicy::with_confidence_service(
            BudgetConfig::default(),
            confidence_service.clone(),
        ));
        let ledger = Arc::new(BudgetLedger::new(tracker.clone(), policy));
        let queue_repo: Arc<dyn QueueRepository> = Arc::new(InMemoryQueueRepository::default());
        let waiting_queue = Arc::new(WaitingQueue::new(queue_repo));
        let pause_manager = Arc::new(PauseResumeManager::new(tracker.clone(), waiting_queue));
        let clarifier = Arc::new(ClarifierLibrary::with_default_templates(Arc::new(
            DeterministicClarifier,
        )));
        let history = Arc::new(ClarificationHistory::new());
        let resume_service = Arc::new(ResumeTriggerService::new(
            pause_manager.clone(),
            clarifier.clone(),
            Some(ledger.clone()),
            None,
            history.clone(),
        ));
        let batch_tracker = Arc::new(QuestionBatchTracker::new());
        let confidence_tracker = Arc::new(PlanConfidenceTracker::with_defaults());

        // Real prompt storage (bundled prompts incl. `agentic_decision_system`) so
        // this orchestrator is EXECUTION-capable: the executor builds the decision
        // system prompt before the test native adapter intercepts, and DummyPromptStore
        // would fail that load. Chat ask-loop tests are unaffected (real prompts are a
        // superset of the dummy’s error-on-miss behavior).
        let prompt_store: Arc<dyn PromptStore> = Arc::new(
            crate::magician_v2::prompts::json_storage::JsonPromptStorage::with_default_config()
                .expect("default prompt storage for execution-capable test orchestrator"),
        );
        let prompt_manager = Arc::new(PromptManager::new(prompt_store.clone()));
        let rewrite_model: Arc<dyn RewriteModel> = Arc::new(DeterministicRewriteModel);
        let query_rewriter = Arc::new(QuestionRewriter::new(
            rewrite_model,
            prompt_manager.clone(),
            RewriterConfig::default(),
        ));

        let session_manager_arc: Arc<dyn SessionManager> = session_manager.clone();
        let metrics = Arc::new(ClarificationMetrics::new());

        let ask_loop_api = Arc::new(AskLoopApi::new(
            clarifier,
            pause_manager,
            ledger,
            resume_service,
            history,
            batch_tracker,
            confidence_tracker,
            query_rewriter,
            Arc::clone(&metrics),
            session_manager_arc.clone(),
            store_for_services.clone(),
        ));

        let llm_service = Arc::new(MockQueryAnalysisLLM) as Arc<dyn QueryAnalysisLLM>;
        let tool_discovery = Arc::new(NullToolDiscovery);
        let tool_adapter = Arc::new(crate::magician_v2::tooling::ToolDiscoveryAdapter::new(
            Arc::clone(&tool_discovery) as Arc<dyn crate::ToolDiscovery>,
        ));
        let tool_catalog: Arc<dyn ToolCatalog> = tool_adapter.clone();
        let tool_matching: Arc<dyn ToolMatching> = tool_adapter.clone();
        let runtime_config: Arc<dyn RuntimeConfig> = Arc::new(TestRuntimeConfig::new());
        // The stateless driver -- the default, and the only one selected
        // implicitly -- refuses a scope whose legacy-writer cutover is not
        // sealed. That is a deployment precondition an operator satisfies once
        // per scope, so a fixture that wants a working orchestrator has to
        // satisfy it too. Sealing here rather than switching drivers keeps
        // these tests on the arm production actually runs.
        crate::magician_v2::test_support::activate_conventional_test_scopes_sync(
            std::path::Path::new(runtime_config.storage_path()),
        );
        let magicutor_client = safe_magicutor_client()?;
        let artifact_root =
            std::env::temp_dir().join(format!("magician-v3-test-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&artifact_root).expect("test artifact root");
        let durable_root = artifact_root.join("magician_data_v3");

        let services = MagicianV2Services::new(
            runtime_config,
            store_for_services,
            prompt_manager,
            tool_catalog,
            tool_matching,
            None,
            session_manager_arc,
            magicutor_client,
            Vec::new(),
            durable_root.clone(),
            None,
        );

        let orchestrator = MagicianV2Orchestrator::new_with_secret_runtime(
            services,
            llm_service,
            crate::magician_v2::secrets::in_memory_secret_runtime_bootstrap(),
        )
        .with_confidence_service(confidence_service)
        .with_ask_loop_api(ask_loop_api)
        // A no-config router so the orchestrator is EXECUTION-capable in tests:
        // `build_action_executors` requires `operation_llm_router` to be Some (it
        // panics otherwise), so without this no test could drive
        // `execute_agentic_direct_with_outcome`. The router never issues real LLM
        // calls in tests — decisions come from `set_test_native_responses`.
        .with_operation_llm_router(Arc::new(
            crate::magician_v2::query_analysis::operation_llm_router::OperationLlmRouter::new(None),
        ))
        .initialize();

        let v3_service = Arc::new(
            crate::magician_v2::artifact_v2::ArtifactV2Service::with_orchestrator(
                durable_root,
                Arc::clone(&orchestrator),
                crate::magician_v2::gaui::MuijStorage::new(artifact_root.join("muij")),
            ),
        );
        orchestrator.set_artifact_v2_service(v3_service);

        // Mirror the production wiring in `MagicianV2Api::create_with_options`:
        // the pause store is the durable admission authority for stateless
        // pause/resume/cancel, and the tree paths refuse to run without it.
        // Without this an execution-capable test orchestrator fails closed on
        // "pause admission is unavailable" instead of exercising the path.
        orchestrator.set_full_pause_store(
            FullPauseStore::new_shared_with_scoped_v3_persistence_root(
                &orchestrator.pause_states_storage_path(),
            ),
        );

        Some((orchestrator, session_manager, store))
    }

    #[tokio::test]
    async fn mark_session_collecting_resets_session_state() {
        let Some((orchestrator, session_manager, store)) = build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        let mut session = ClarificationSession::new("wf-reset");
        let now = Utc::now();
        let answered_question = ClarifierQuestion {
            id: "q-answered".into(),
            blocker_type: BlockerType::LowConfidenceSlot,
            stage: StageContext::PlanningBootstrap,
            source_slot_id: Some("slot::a".into()),
            question_text: "What is the target?".into(),
            context_snippets: vec![],
            urgency: 0.5,
            channel: crate::magician_v2::ask_loop::budget::Channel::InApp,
            created_at: now,
            options: None,
            batch_id: None,
            batch_total: None,
            ..ClarifierQuestion::default()
        };
        session.enqueue_question(answered_question);
        session.update_question_status("q-answered", SessionQuestionStatus::Answered);
        session.record_slot_update(
            "q-answered",
            SlotRecord {
                id: "slot::a".into(),
                slot_type: crate::magician_v2::slot_graph::SlotType::Entity,
                value: serde_json::json!("Acme Corp"),
                confidence: 0.9,
                provenance: vec![],
                evidence_links: vec![],
                created_at: now,
                updated_at: now,
            },
        );
        session_manager.save(session).await.expect("session saved");

        orchestrator
            .mark_session_collecting("wf-reset")
            .await
            .expect("session should transition to collecting");

        let reloaded_session = session_manager
            .load("wf-reset")
            .await
            .expect("session load")
            .expect("session exists");
        assert!(
            reloaded_session.pending_questions.is_empty(),
            "answered questions should be pruned after collecting reset"
        );
        assert!(
            reloaded_session.slot_updates.is_empty(),
            "slot updates should be cleared after collecting reset"
        );

        let history_entries = store
            .clarification_history
            .lock()
            .await
            .get("wf-reset")
            .cloned()
            .unwrap_or_default();
        assert_eq!(history_entries.len(), 1);
        let entry = &history_entries[0];
        assert_eq!(entry.question_id, "q-answered");
        assert_eq!(entry.slot_updates.len(), 1);
    }

    #[tokio::test]
    async fn create_execution_with_id_persists_execution_scope_on_first_write() {
        let Some((orchestrator, _session_manager, _store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        let execution = orchestrator
            .create_execution_with_id(
                "principal",
                "workspace",
                Some("Execution".to_string()),
                "personal-assistant",
                "exec-root-1",
                Some("task-1".to_string()),
                Some("exec-root-1".to_string()),
            )
            .await
            .expect("create execution");

        assert_eq!(execution.id, "exec-root-1");
        assert_eq!(execution.task_id.as_deref(), Some("task-1"));
        assert_eq!(execution.root_execution_id.as_deref(), Some("exec-root-1"));

        let persisted = orchestrator
            .get_execution("exec-root-1")
            .await
            .expect("load persisted execution");
        assert_eq!(persisted.task_id.as_deref(), Some("task-1"));
        assert_eq!(persisted.root_execution_id.as_deref(), Some("exec-root-1"));
    }

