    #[tokio::test]
    async fn cancel_execution_tree_cascades_to_active_children() {
        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        let parent_id = "wf-cancel-parent";
        let active_child_id = "wf-cancel-child-active";
        let waiting_child_id = "wf-cancel-child-waiting";
        let linked_child_id = "wf-cancel-child-linked";
        let historical_child_id = "wf-cancel-child-historical";
        let now = Utc::now().timestamp_millis();

        store
            .insert_execution(ExecutionRun {
                id: parent_id.to_string(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                task_id: None,
                root_execution_id: None,
                title: Some("Parent".to_string()),
                waiting_state: WaitingState::WaitingChildren,
                created_at: now,
                updated_at: now,
                processing_correlation_id: None,
                current_stage: None,
                current_provider: None,
                escalation_trigger: None,
                parent_execution_id: None,
                child_execution_ids: vec![
                    active_child_id.to_string(),
                    waiting_child_id.to_string(),
                    linked_child_id.to_string(),
                    historical_child_id.to_string(),
                ],
                active_owner_agent_id: crate::magician_v2::chat::DEFAULT_AGENT_ID.to_string(),
                owner_stack: Vec::new(),
                active_delegation_group: vec![
                    active_child_id.to_string(),
                    waiting_child_id.to_string(),
                ],
                timeout_secs: None,
                delegation_chain: Vec::new(),
                work_authority: None,
                paused_from_state: None,
                entry_mode: ExecutionEntryMode::PlanningBacked,
            })
            .await;

        for (execution_id, waiting_state) in [
            (active_child_id, WaitingState::Executing),
            (waiting_child_id, WaitingState::WaitingUser),
            (linked_child_id, WaitingState::Runnable),
            (historical_child_id, WaitingState::Completed),
        ] {
            store
                .insert_execution(ExecutionRun {
                    id: execution_id.to_string(),
                    principal: "user".to_string(),
                    workspace: "workspace".to_string(),
                    task_id: None,
                    root_execution_id: None,
                    title: Some(execution_id.to_string()),
                    waiting_state,
                    created_at: now,
                    updated_at: now,
                    processing_correlation_id: None,
                    current_stage: None,
                    current_provider: None,
                    escalation_trigger: None,
                    parent_execution_id: Some(parent_id.to_string()),
                    child_execution_ids: Vec::new(),
                    active_owner_agent_id: crate::magician_v2::chat::DEFAULT_AGENT_ID.to_string(),
                    owner_stack: Vec::new(),
                    active_delegation_group: Vec::new(),
                    timeout_secs: None,
                    delegation_chain: Vec::new(),
                    work_authority: None,
                    paused_from_state: None,
                    entry_mode: ExecutionEntryMode::PlanningBacked,
                })
                .await;
        }

        let parent_token = tokio_util::sync::CancellationToken::new();
        let active_child_token = tokio_util::sync::CancellationToken::new();
        register_test_controls(&orchestrator, parent_id, parent_token.clone());
        register_test_controls(&orchestrator, active_child_id, active_child_token.clone());

        let cancelled = orchestrator
            .cancel_execution_tree(parent_id)
            .await
            .expect("tree cancellation should succeed");
        assert!(cancelled, "non-terminal parent should report cancellation");

        assert!(
            parent_token.is_cancelled(),
            "root execution token should be cancelled"
        );
        assert!(
            active_child_token.is_cancelled(),
            "active child execution token should be cancelled"
        );
        assert!(
            !orchestrator
                .active_execution_controls
                .contains_key(parent_id),
            "root token should be removed after cancellation"
        );
        assert!(
            !orchestrator
                .active_execution_controls
                .contains_key(active_child_id),
            "child token should be removed after cancellation"
        );

        assert_eq!(
            store
                .get_execution(parent_id)
                .await
                .expect("parent execution")
                .waiting_state,
            WaitingState::Cancelled
        );
        assert_eq!(
            store
                .get_execution(active_child_id)
                .await
                .expect("active child execution")
                .waiting_state,
            WaitingState::Cancelled
        );
        assert_eq!(
            store
                .get_execution(waiting_child_id)
                .await
                .expect("waiting child execution")
                .waiting_state,
            WaitingState::Cancelled
        );
        assert_eq!(
            store
                .get_execution(linked_child_id)
                .await
                .expect("linked child execution")
                .waiting_state,
            WaitingState::Cancelled,
            "linked non-terminal children must be cancelled even before they join the active delegation group"
        );
        assert_eq!(
            store
                .get_execution(historical_child_id)
                .await
                .expect("historical child execution")
                .waiting_state,
            WaitingState::Completed,
            "only currently active delegated children should be cancelled"
        );
        assert!(
            store
                .get_execution(parent_id)
                .await
                .expect("parent execution")
                .active_delegation_group
                .is_empty(),
            "parent cancellation should clear active delegation bookkeeping"
        );
    }

    #[tokio::test]
    async fn cancel_execution_tree_drains_pending_captured_session_tasks() {
        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        let execution_id = "wf-cancel-capture-drain";
        let now = Utc::now().timestamp_millis();
        store
            .insert_execution(ExecutionRun {
                id: execution_id.to_string(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                task_id: None,
                root_execution_id: None,
                title: Some("Capture Drain".to_string()),
                waiting_state: WaitingState::Executing,
                created_at: now,
                updated_at: now,
                processing_correlation_id: None,
                current_stage: None,
                current_provider: None,
                escalation_trigger: None,
                parent_execution_id: None,
                child_execution_ids: Vec::new(),
                active_owner_agent_id: crate::magician_v2::chat::DEFAULT_AGENT_ID.to_string(),
                owner_stack: Vec::new(),
                active_delegation_group: Vec::new(),
                timeout_secs: None,
                delegation_chain: Vec::new(),
                work_authority: None,
                paused_from_state: None,
                entry_mode: ExecutionEntryMode::PlanningBacked,
            })
            .await;

        let cancel_token = tokio_util::sync::CancellationToken::new();
        register_test_controls(&orchestrator, execution_id, cancel_token.clone());

        let secret_store = orchestrator
            .secret_store_resolver()
            .resolve_for_scope("user", "workspace")
            .expect("scoped secret store should resolve");
        let handle = tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(50)).await;
            secret_store
                .store_captured_browser_state_deferred(
                    "https://api.example.com",
                    vec![crate::magician_v2::secrets::CookieWithMetadata {
                        name: "session".to_string(),
                        value: "captured-after-cancel".to_string(),
                        domain: "api.example.com".to_string(),
                        path: "/".to_string(),
                        secure: true,
                        http_only: true,
                        same_site: crate::magician_v2::secrets::SameSite::Lax,
                        expires: None,
                    }],
                    Some(std::collections::HashMap::new()),
                    Some(std::collections::HashMap::new()),
                )
                .expect("store captured browser snapshot");
        });
        orchestrator
            .secret_store_resolver()
            .resolve_for_scope("user", "workspace")
            .expect("scoped secret store should resolve")
            .register_captured_task(Some(execution_id.to_string()), handle);

        let cancelled = orchestrator
            .cancel_execution_tree(execution_id)
            .await
            .expect("tree cancellation should succeed");
        assert!(cancelled);
        assert!(cancel_token.is_cancelled());

        let (session, _) = orchestrator
            .secret_store_resolver()
            .resolve_for_scope("user", "workspace")
            .expect("scoped secret store should resolve")
            .get_session("https://api.example.com", "https://api.example.com/pay")
            .expect("cancel should drain and flush in-flight captured session state");
        assert_eq!(
            session.cookies.get("session").map(String::as_str),
            Some("captured-after-cancel")
        );
    }

