    #[test]
    fn accepted_explicit_delegation_dispatches_the_sealed_child_inside_admission() {
        let source = include_str!("v2_orchestrator.rs");
        let explicit = source
            .split("pub async fn spawn_explicit_delegation")
            .nth(1)
            .and_then(|tail| {
                tail.split("/// Pause an execution-scoped execution tree")
                    .next()
            })
            .expect("explicit accepted delegation dispatch");
        let derived = explicit
            .find("delegation_idempotency_execution_id")
            .expect("defensive deterministic-id derivation");
        let exact = explicit
            .find("spawn_exact_child_on_execution_runtime")
            .expect("exact dispatcher path");
        let generic = explicit
            .find("spawn_children_on_execution_runtime")
            .expect("ordinary dispatcher fallback");
        let result_guard = explicit
            .find("accepted explicit delegation returned a different child")
            .expect("returned exact-child assertion");
        assert!(derived < exact && exact < generic && generic < result_guard);
        assert!(explicit.contains("expected_child_execution_id.to_owned()"));
    }

