        assert!(final_fence < nonce_claim && nonce_claim < execution_start);
        assert!(direct.contains("fresh launch status outcome is unreadable"));
        assert!(direct.contains("direct entry mode write had an ambiguous durable outcome"));
        assert!(direct.contains("rebind_after_metadata_write"));
        assert!(direct.contains("claim_stateless_preseed_recovery"));
