    #[test]
    fn detached_recovery_single_flight_is_released_by_drop() {
        let source = include_str!("v2_orchestrator.rs");
        let guard = source
            .split("struct InterruptedExecutionRecoveryLaunchGuard")
            .nth(1)
            .and_then(|tail| tail.split("struct InterruptedPlanRecoveryBinding").next())
            .expect("recovery drop guard");
        assert!(guard.contains("impl Drop for InterruptedExecutionRecoveryLaunchGuard"));
        assert!(guard.contains("remove(&self.key)"));
        assert!(guard.contains("self.changed.notify_one()"));

        let bounded = source
            .split("fn schedule_bounded_pipeline_reentry")
            .nth(1)
            .expect("bounded pipeline recovery scheduler");
        assert!(bounded.contains("InterruptedExecutionRecoveryLaunchGuard"));
        let guard = bounded
            .find("let launch_guard = InterruptedExecutionRecoveryLaunchGuard")
            .expect("guard constructed before registry handoff");
        let spawn = bounded
            .find("runtime_boundary::spawn_execution_job")
            .expect("shutdown-owned recovery job");
        assert!(guard < spawn);

        let plan = source
            .split("fn schedule_interrupted_plan_execution")
            .nth(1)
            .and_then(|tail| tail.split("fn derive_goal_for_plan_execution").next())
            .expect("shared PlanGraph recovery coordinator");
        assert!(source.contains("struct InterruptedPlanRecoveryQueue"));
        assert!(source.contains("BinaryHeap<Reverse"));
        assert!(plan.contains("try_acquire_owned"));
        assert!(plan.contains("interrupted_plan_recovery_wake.notified()"));
        assert!(plan.contains("runtime_boundary::spawn_execution_job"));
        assert!(plan.contains("fail_absent_nonrecoverable_stateless_execution"));
        let clear = plan
            .find(".store(false, Ordering::Release)")
            .expect("coordinator clears active bit before exit handoff");
        let recheck = plan[clear..]
            .find("let still_empty")
            .map(|offset| clear + offset)
            .expect("queue recheck after active-bit clear");
        let reacquire = plan[recheck..]
            .find(".compare_exchange(false, true")
            .map(|offset| recheck + offset)
            .expect("coordinator active-bit reacquisition");
        assert!(clear < recheck && recheck < reacquire);
        assert!(!plan.contains("for candidate in interrupted_plan_recovery_queue"));
    }

