    #[test]
    fn public_direct_entry_cannot_use_a_steer_uuid_as_active_runtime_authority() {
        let source = include_str!("v2_orchestrator.rs");
        let direct = source
            .split("async fn execute_agentic_direct_with_outcome_inner")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn execute_pipeline_single_context")
                    .next()
            })
            .expect("direct execution admission");
        let authority_gate = direct
            .find("stateless active execution requires server-owned exact recovery authority")
            .expect("active-runtime authority gate");
        let pause_clear = direct
            .rfind("prepare_fresh_execution_pause_state_with_lifecycle_held")
            .expect("state-aware fresh-launch pause admission");
        let final_lifecycle = direct
            .find("let direct_entry_lifecycle")
            .expect("fresh/recovery final lifecycle fence");
        let control_publish = direct
            .find("publish_stateless_control_generation")
            .expect("control publication boundary");
        assert!(authority_gate < final_lifecycle);
        assert!(final_lifecycle < pause_clear && pause_clear < control_publish);
        let steer_selection = &direct[..authority_gate];
        assert!(!steer_selection.contains("recoverable_control_generation"));
        assert!(direct.contains("exact_sleep_retry_recoverable_generation"));

        let public_trigger = source
            .split("pub async fn trigger_execution(")
            .nth(1)
            .and_then(|tail| tail.split("async fn trigger_execution_direct").next())
            .expect("public trigger admission");
        let public_gate = public_trigger
            .find("server-owned exact recovery authority")
            .expect("public active-runtime gate");
        let public_clear = public_trigger
            .find("prepare_fresh_execution_pause_state_with_lifecycle_held")
            .expect("state-aware public fresh cleanup");
        assert!(public_gate < public_clear);
        let runtime_recheck = direct
            .find("fresh direct runtime recheck failed")
            .expect("final fresh runtime generation read");
        let generation_match = direct
            .find("current.updated_at != persisted_execution.updated_at")
            .expect("fresh runtime generation match");
        assert!(final_lifecycle < runtime_recheck);
        assert!(runtime_recheck < generation_match && generation_match < pause_clear);
        let taskless_owner = direct
            .find("persisted_execution.active_owner_agent_id.trim().is_empty()")
            .expect("taskless durable owner requirement");
        let taskless_plan = direct
            .find("execution_has_durable_plan(execution_id)")
            .expect("taskless durable PlanGraph requirement");
        assert!(taskless_owner < taskless_plan && taskless_plan < final_lifecycle);

        let fresh = source
            .split("fn prepare_fresh_execution_pause_state_with_lifecycle_held")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub(crate) async fn internal_delegation_checkpoint_scoped")
                    .next()
            })
            .expect("fresh pause-state admission");
        assert!(fresh
            .contains("WaitingState::Completed | WaitingState::Cancelled | WaitingState::Failed"));
        assert!(fresh.contains("requires a new execution id for rerun"));
        assert!(!fresh.contains("clear_pending_pauses_for_execution_checked"));
        assert!(fresh.contains("get_internal_pending_for_execution"));
        assert!(fresh.contains("requires typed resume or cancellation"));
    }

    #[test]
    fn explicit_terminal_delegation_retires_only_its_exact_source_under_one_fence() {
        let source = include_str!("v2_orchestrator.rs");
        let helper = source
            .split("async fn retire_terminal_delegation_source_with_lifecycle_held")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub(crate) async fn settle_explicit_delegation_parent")
                    .next()
            })
            .expect("exact terminal Delegation cleanup");
        assert!(helper.contains("internal_delegation_checkpoint_scoped"));
        assert!(helper.contains("retire_terminal_delegation_checkpoint_on_execution_runtime"));
        assert!(!helper.contains("clear_pending_pauses_for_execution"));
        assert!(!helper.contains("acquire_stateless_execution_lifecycle_exclusion_scoped"));

        let settle = source
            .split("pub(crate) async fn settle_explicit_delegation_parent")
            .nth(1)
            .and_then(|tail| {
                tail.split("async fn enforce_delegation_no_progress_guard")
                    .next()
            })
            .expect("explicit Delegation terminal reducer");
        let lifecycle = settle
            .find("acquire_stateless_execution_lifecycle_exclusion_scoped")
            .expect("outer execution lifecycle fence");
        let status_commit = settle
            .find("settle_delegation_parent")
            .expect("terminal status commit");
        let cleanup = settle
            .find("retire_terminal_delegation_source_with_lifecycle_held")
            .expect("exact source cleanup");
        assert!(lifecycle < status_commit && lifecycle < cleanup);
        assert!(
            settle
                .matches("retire_terminal_delegation_source_with_lifecycle_held")
                .count()
                >= 3
        );
        assert!(!settle.contains("clear_pending_pauses_for_execution"));
    }

