    /// Only an **admitted** parent may acquire children, and admission is the
    /// existing two-edge ladder — never a shortcut from `Planning`.
    ///
    /// Every execution is born `Planning` (the constructor's default, meaning
    /// "created, nothing decided yet"), and an explicit `delegate_to_agent`
    /// skips the direct-execution path that would normally move it on. It
    /// therefore spawned children while still in `Planning`, where the
    /// invalid-edge fallback keeps the status and returns `Ok` — leaving a
    /// parent with a populated `active_delegation_group` that
    /// `settle_explicit_delegation_parent` (WaitingChildren/Runnable/Executing
    /// only) could never settle. Every explicit delegation became durable debt
    /// that retried forever.
    ///
    /// The fix is that the launch admits first, so this asserts both halves:
    /// `Planning` does **not** transition, and each admitted state does.
    #[tokio::test]
    async fn only_an_admitted_parent_transitions_into_waiting_children() {
        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        // Unadmitted: spawning children from here must not be expressible. If
        // this ever starts transitioning, a parent can acquire children before
        // anything decided it should run.
        store
            .insert_execution(test_execution_run(
                "wf-deleg-from-planning",
                WaitingState::Planning,
            ))
            .await;
        assert_eq!(
            orchestrator
                .transition_status(
                    "wf-deleg-from-planning",
                    WorkflowEvent::DelegationChildrenSpawned
                )
                .await,
            Ok(WaitingState::Planning),
            "an unadmitted parent must not reach WaitingChildren; the launch admits it first"
        );

        // The ladder the launch walks, and the states it can already be in.
        for (execution_id, from) in [
            (
                "wf-deleg-from-planning-complete",
                WaitingState::PlanningComplete,
            ),
            ("wf-deleg-from-executing", WaitingState::Executing),
            ("wf-deleg-from-runnable", WaitingState::Runnable),
        ] {
            store
                .insert_execution(test_execution_run(execution_id, from.clone()))
                .await;
            assert_eq!(
                orchestrator
                    .transition_status(execution_id, WorkflowEvent::DelegationChildrenSpawned)
                    .await,
                Ok(WaitingState::WaitingChildren),
                "an admitted parent must park in WaitingChildren, but {from:?} did not"
            );
            assert_eq!(
                store
                    .get_execution(execution_id)
                    .await
                    .expect("parent remains persisted")
                    .waiting_state,
                WaitingState::WaitingChildren,
                "the persisted row must agree; settlement reads it, not the return value"
            );
        }

        // And the ladder itself: Planning is reachable to WaitingChildren only
        // by being admitted, which is what the launch now does.
        assert_eq!(
            orchestrator
                .transition_status("wf-deleg-from-planning", WorkflowEvent::ReadyToExecute)
                .await,
            Ok(WaitingState::PlanningComplete)
        );
        assert_eq!(
            orchestrator
                .transition_status(
                    "wf-deleg-from-planning",
                    WorkflowEvent::DelegationChildrenSpawned
                )
                .await,
            Ok(WaitingState::WaitingChildren)
        );
    }

    #[tokio::test]
    async fn pause_revalidates_runtime_transition_under_the_shared_status_lock() {
        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        let execution_id = "wf-pause-runtime-transition-race";
        store
            .insert_execution(test_execution_run(
                execution_id,
                WaitingState::WaitingChildren,
            ))
            .await;

        let status_lock = orchestrator
            .execution_status_locks
            .entry(execution_id.to_string())
            .or_insert_with(|| Arc::new(tokio::sync::Mutex::new(())))
            .clone();
        let held = status_lock.clone().lock_owned().await;
        let transition_orchestrator = Arc::clone(&orchestrator);
        let transition = tokio::spawn(async move {
            transition_orchestrator
                .transition_status(execution_id, WorkflowEvent::ChildCompleted)
                .await
        });
        tokio::task::yield_now().await;
        let pause_orchestrator = Arc::clone(&orchestrator);
        let pause =
            tokio::spawn(
                async move { pause_orchestrator.pause_execution_tree(execution_id).await },
            );
        tokio::task::yield_now().await;
        drop(held);

        assert_eq!(
            transition.await.expect("transition task"),
            Ok(WaitingState::Runnable)
        );
        let error = pause
            .await
            .expect("pause task")
            .expect_err("pause must reject the stale WaitingChildren preflight");
        assert!(error.contains("changed from WaitingChildren to Runnable"));
        assert_eq!(
            store
                .get_execution(execution_id)
                .await
                .expect("execution remains persisted")
                .waiting_state,
            WaitingState::Runnable
        );
    }

