    // B14 harness: parents are task_id:None so reconcile_waiting_children_and_continue
    // runs the no-progress guard WITHOUT a live agent cycle (the task_id.is_some()
    // continuation block is skipped). Per round: re-park the parent on one
    // terminal child, then reconcile.
    async fn b14_seed_round(
        orchestrator: &MagicianV2Orchestrator,
        store: &TestStore,
        parent_id: &str,
        child_id: &str,
        agent: &str,
        artifacts: Vec<String>,
        now: i64,
    ) {
        // Default goal/title derives from the agent (preserves prior behavior:
        // same agent => same goal => no-progress).
        b14_seed_round_with_goal(
            orchestrator,
            store,
            parent_id,
            child_id,
            agent,
            &format!("{agent} stage"),
            artifacts,
            now,
        )
        .await
    }

