    fn b14_progress_record(root_execution_id: &str) -> DelegationRoundProgressRecord {
        DelegationRoundProgressRecord {
            schema_version: DELEGATION_PROGRESS_SCHEMA_VERSION,
            principal: "user".to_string(),
            workspace: "workspace".to_string(),
            root_execution_id: root_execution_id.to_string(),
            agent_signature_sha256: delegation_progress_digest(&["agent".to_string()]),
            goal_signature_sha256: delegation_progress_digest(&["goal".to_string()]),
            proposal_set_sha256: None,
            proposal_count: 0,
            proposal_guard_armed: false,
            no_progress_rounds: 0,
            no_new_proposal_rounds: 0,
            round_fingerprint_sha256: delegation_progress_digest(&["round".to_string()]),
            updated_at_ms: Utc::now().timestamp_millis(),
        }
    }

    #[test]
    fn b14_assignment_signature_preserves_pairing_and_multiplicity() {
        let original = vec![
            ("agent-a".to_string(), "goal-x".to_string()),
            ("agent-b".to_string(), "goal-y".to_string()),
        ];
        let swapped = vec![
            ("agent-a".to_string(), "goal-y".to_string()),
            ("agent-b".to_string(), "goal-x".to_string()),
        ];
        let duplicated = vec![original[0].clone(), original[0].clone()];
        let singleton = vec![original[0].clone()];
        let original_signatures = delegation_progress_assignment_signatures(&original);
        let swapped_signatures = delegation_progress_assignment_signatures(&swapped);
        assert_eq!(
            original_signatures.0, swapped_signatures.0,
            "agent multiset is deliberately stable"
        );
        assert_ne!(
            original_signatures.1, swapped_signatures.1,
            "agent/goal reassignment must be observable"
        );
        assert_ne!(
            delegation_progress_assignment_signatures(&duplicated),
            delegation_progress_assignment_signatures(&singleton),
            "repeated assignments must not be deduplicated"
        );
    }

