    /// B14 (positive): re-delegating the SAME agent with NO new artifacts for N
    /// consecutive resume rounds must ABORT the parent (Failed), not resume forever
    /// — the observed cross-execution runaway.
    #[tokio::test]
    async fn test_spine_b14_no_progress_rounds_abort_parent() {
        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let parent_id = "spine-b14-noprogress-parent";
        let now = Utc::now().timestamp_millis();

        // Round 1 sets the baseline (progress); the next N rounds repeat the same
        // agent with no new artifacts -> the counter reaches N and aborts.
        for round in 1..=(MAX_NO_PROGRESS_DELEGATION_ROUNDS + 1) {
            b14_seed_round(
                &orchestrator,
                &store,
                parent_id,
                &format!("spine-b14-child-{round}"),
                "web-researcher",
                Vec::new(),
                now,
            )
            .await;
            let _ = orchestrator
                .reconcile_waiting_children_and_continue(parent_id)
                .await
                .expect("reconcile should not error");
        }

        let parent = orchestrator
            .get_execution(parent_id)
            .await
            .expect("parent should be loadable");
        assert_eq!(
            parent.waiting_state,
            WaitingState::Failed,
            "same agent + no new output for N rounds must abort the parent"
        );
    }

