    #[tokio::test]
    async fn explicit_terminal_settlement_replay_clears_stale_delegation_checkpoint() {
        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let parent_id = "explicit-terminal-replay-parent";
        // Terminal delegation retirement is scoped by task identity, which every
        // delegation parent carries in production; `test_execution_run` leaves
        // `task_id` unset, so bind it here rather than for every row it builds.
        let mut parent = test_execution_run(parent_id, WaitingState::Completed);
        parent.task_id = Some("explicit-terminal-replay-task".to_string());
        store.insert_execution(parent).await;

        let pause_root = tempfile::TempDir::new().expect("temporary pause root");
        let pause_store = Arc::new(FullPauseStore::with_persistence(pause_root.path()));
        orchestrator.set_full_pause_store(Arc::clone(&pause_store));
        let pause_state = AgenticPauseState::new(
            1,
            "Wait for delegated result",
            "Publish the child result",
            EnvironmentState::Shell(ShellState::default()),
            "",
            8,
            5,
        )
        .with_observability(parent_id, "plan-explicit", "step-explicit")
        .with_scope("user", "workspace")
        // Terminal delegation retirement matches the stored envelope against the
        // execution's exact scope *and* task identity, so the pause has to carry
        // the same task the parent row is bound to.
        .with_task_execution_context(
            Some("explicit-terminal-replay-task".to_string()),
            Some(parent_id.to_string()),
            None,
        );
        let executors = orchestrator.build_action_executors_with_router_override(Some(Arc::new(
            OperationLlmRouter::new(None),
        )));
        pause_store
            .store_durable(
                FullPauseData::new(
                    pause_state,
                    UserInputType::Confirmation {
                        confirm_label: None,
                        deny_label: None,
                        destructive: false,
                    },
                    executors,
                    None,
                    None,
                )
                .with_pause_kind(ExecutionPauseKind::Delegation),
            )
            .expect("delegation checkpoint should persist");
        assert_eq!(
            pause_store
                .get_internal_pending_for_execution(parent_id)
                .len(),
            1
        );

        assert!(!orchestrator
            .settle_explicit_delegation_parent(parent_id, true)
            .await
            .expect("terminal settlement replay should succeed"));
        assert!(
            pause_store
                .get_internal_pending_for_execution(parent_id)
                .is_empty(),
            "idempotent terminal replay must release the exact checkpoint heap"
        );
    }

    /// Phase 2 (diff-approval delegation): a delegated child left SUSPENDED
    /// (`WaitingUser`, e.g. awaiting a diff approval) is non-terminal, so reconcile
    /// keeps the parent parked in `WaitingChildren` instead of finalizing/resuming
    /// it. This is the suspend-and-bubble behavior the runtime arm now relies on
    /// (it no longer force-fails such a child). When the child completes
    /// (apply+resume), reconcile then resumes the parent.
    #[tokio::test]
    async fn test_spine_paused_child_keeps_parent_waiting_children() {
        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };
        let parent_id = "spine-paused-child-parent";
        let child_id = "spine-paused-child";
        let now = Utc::now().timestamp_millis();
        let mk_child = |state: WaitingState| ExecutionRun {
            id: child_id.to_string(),
            principal: "user".to_string(),
            workspace: "workspace".to_string(),
            task_id: None,
            root_execution_id: None,
            title: Some("create SMOKE_TEST.md as a pending proposal".to_string()),
            waiting_state: state,
            created_at: now,
            updated_at: now,
            processing_correlation_id: None,
            current_stage: None,
            current_provider: None,
            escalation_trigger: None,
            parent_execution_id: Some(parent_id.to_string()),
            child_execution_ids: Vec::new(),
            active_owner_agent_id: "principal-software-engineer".to_string(),
            owner_stack: Vec::new(),
            active_delegation_group: Vec::new(),
            timeout_secs: None,
            delegation_chain: Vec::new(),
            work_authority: None,
            paused_from_state: None,
            entry_mode: ExecutionEntryMode::PlanningBacked,
        };
        store
            .insert_execution(ExecutionRun {
                id: parent_id.to_string(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                task_id: None,
                root_execution_id: Some(parent_id.to_string()),
                title: Some("paused-child parent".to_string()),
                waiting_state: WaitingState::WaitingChildren,
                created_at: now,
                updated_at: now,
                processing_correlation_id: None,
                current_stage: None,
                current_provider: None,
                escalation_trigger: None,
                parent_execution_id: None,
                child_execution_ids: vec![child_id.to_string()],
                active_owner_agent_id: crate::magician_v2::chat::DEFAULT_AGENT_ID.to_string(),
                owner_stack: Vec::new(),
                active_delegation_group: vec![child_id.to_string()],
                timeout_secs: None,
                delegation_chain: Vec::new(),
                work_authority: None,
                paused_from_state: None,
                entry_mode: ExecutionEntryMode::PlanningBacked,
            })
            .await;

        // Child suspended awaiting approval (non-terminal) → parent must NOT resume.
        store
            .insert_execution(mk_child(WaitingState::WaitingUser))
            .await;
        let resumed = orchestrator
            .reconcile_waiting_children(parent_id)
            .await
            .expect("reconcile should not error");
        assert!(
            !resumed,
            "a suspended (WaitingUser) child is non-terminal — the parent must stay WaitingChildren"
        );
        let parent = orchestrator
            .get_execution(parent_id)
            .await
            .expect("parent loadable");
        assert_eq!(parent.waiting_state, WaitingState::WaitingChildren);

        // Child completes (the apply+resume outcome) → reconcile resumes the parent.
        store
            .insert_execution(mk_child(WaitingState::Completed))
            .await;
        let resumed = orchestrator
            .reconcile_waiting_children(parent_id)
            .await
            .expect("reconcile should not error");
        assert!(resumed, "once the child completes, the parent resumes");
        let parent = orchestrator
            .get_execution(parent_id)
            .await
            .expect("parent loadable");
        assert_ne!(
            parent.waiting_state,
            WaitingState::WaitingChildren,
            "parent should leave WaitingChildren once its child is terminal"
        );
    }

    /// STEP 3 / Increment 0: prove the in-memory accumulator + `render_stage_goal`
    /// thread the multi-stage spine (research→ELI5→comic) WITHOUT reconcile/disk —
    /// stage N+1's goal carries stage N's deliverable, and the final aggregation
    /// carries every stage's output (incl. the comic script + headline media). The
    /// Increment-1 engine drives this exact accumulator behind a flag. Pure data
    /// flow; regression anchor: test_spine_child_deliverables_thread_into_resume_section.
    #[test]
    fn test_spine_single_context_pipeline_research_eli5_comic() {
        use crate::magician_v2::execution::{
            render_stage_goal, ChildDeliverableSummary, ChildMediaRef, PipelineStage,
        };

        let stages = vec![
            PipelineStage {
                agent_id: "web-researcher".to_string(),
                context: "Research the latest fund raise".to_string(),
                success_criteria: None,
                timeout_secs: None,
            },
            PipelineStage {
                agent_id: "eli5-explainer".to_string(),
                context: "Explain it like I'm 5".to_string(),
                success_criteria: None,
                timeout_secs: None,
            },
            PipelineStage {
                agent_id: "creative-mind".to_string(),
                context: "Draw an 8-panel comic".to_string(),
                success_criteria: None,
                timeout_secs: None,
            },
        ];

        // The per-stage deliverables the engine would accumulate (hand-built,
        // mirroring test_spine_child_deliverables_thread_into_resume_section).
        let stage_deliverables = vec![
            ChildDeliverableSummary {
                child_execution_id: "stage-0".to_string(),
                agent_id: "web-researcher".to_string(),
                context: "research".to_string(),
                primary_text: Some("Series H: $65B raised, $965B valuation.".to_string()),
                media: Vec::new(),
            },
            ChildDeliverableSummary {
                child_execution_id: "stage-1".to_string(),
                agent_id: "eli5-explainer".to_string(),
                context: "eli5".to_string(),
                primary_text: Some(
                    "Anthropic got a huge pile of money to build safer AI.".to_string(),
                ),
                media: Vec::new(),
            },
            ChildDeliverableSummary {
                child_execution_id: "stage-2".to_string(),
                agent_id: "creative-mind".to_string(),
                context: "comic".to_string(),
                primary_text: Some(
                    "Panel 1: news splash. ... an 8-panel Doraemon-style comic script."
                        .to_string(),
                ),
                media: vec![ChildMediaRef {
                    relative_path: "image-generation__run_0_creative-mind.jpg".to_string(),
                    media_type: "image/jpeg".to_string(),
                    serving_url:
                        "/api/magician/v3/tasks/task-1/outputs/image-generation__run_0_creative-mind.jpg?principal=anonymous&workspace=default"
                            .to_string(),
                    caption: None,
                }],
            },
        ];

        // Simulate the engine loop: each stage threads the PRIOR deliverables into
        // its goal, then its own deliverable is accumulated (cursor advance).
        let mut accumulated: Vec<ChildDeliverableSummary> = Vec::new();
        let mut comic_stage_goal = String::new();
        for (idx, stage) in stages.iter().enumerate() {
            let goal = render_stage_goal(&stage.context, &accumulated);
            if stage.agent_id == "creative-mind" {
                comic_stage_goal = goal;
            }
            accumulated.push(stage_deliverables[idx].clone());
        }

        // The comic stage's input threaded the prior ELI5 + research deliverables
        // IN MEMORY — no reconcile, no get_execution_summary of a child.
        assert!(
            comic_stage_goal.contains("Anthropic got a huge pile of money"),
            "comic stage goal must carry the prior ELI5 deliverable: {comic_stage_goal}"
        );
        assert!(
            comic_stage_goal.contains("Series H: $65B raised"),
            "comic stage goal must carry the research deliverable too"
        );

        // The final aggregation carries every stage's output incl. the comic
        // script + headline media serving URL — same strings as the reconcile
        // anchor, reached via the in-memory accumulator.
        let aggregated =
            crate::magician_v2::execution::execution_summary::render_child_deliverables_block(
                &accumulated,
            );
        assert!(aggregated.contains("8-panel Doraemon-style comic script"));
        assert!(aggregated.contains(
            "/api/magician/v3/tasks/task-1/outputs/image-generation__run_0_creative-mind.jpg"
        ));
    }

    // ── STEP 3 / Increment 1b — single-execution-context pipeline ENGINE locks ──
    //
    // These pin the engine's NOVEL pure logic deterministically (zero infra): the
    // per-stage text capture (C1 — from the in-hand outcome artifacts, binary
    // excluded), the final aggregation (R3 — every stage's agent/text/media flows
    // through `render_child_deliverables_block`), non-success propagation, and the
    // per-stage iteration budget. The stage-SWAP machinery is locked by 1a
    // (StageGuard + the trust-guard reload). The live end-to-end stage loop ("ONE
    // execution / no children") is structural — the engine never inserts an
    // ExecutionRun nor spawns a child per stage — and is exercised against REAL
    // agent loading in 1c (which wires the flag branch + agent fixtures + traverses
    // the full prologue), since no current test harness seeds loadable agents.

    /// C1: per-stage text is pulled from the in-hand outcome artifacts (the stage
    /// wrote them THIS run), and binary (image) bytes never leak into the text.
    #[test]
    fn test_pipeline_engine_primary_text_from_outcome_extracts_text_excludes_binary() {
        use crate::magician_v2::execution::{AgenticOutcome, Artifact, EnvironmentState};
        let outcome = AgenticOutcome::Success {
            completion: crate::magician_v2::execution::agentic::types::CompletionKind::Full,
            open: Vec::new(),
            final_state: EnvironmentState::Uninitialized,
            iterations_used: 3,
            artifacts: vec![
                Artifact {
                    name: "eli5.md".to_string(),
                    content_type: "text/markdown".to_string(),
                    data: b"# ELI5\nGravity pulls things down.".to_vec(),
                    artifact_type: None,
                    render_hints: None,
                    materialized_path: None,
                },
                Artifact {
                    name: "panel.png".to_string(),
                    content_type: "image/png".to_string(),
                    data: vec![0u8, 1, 2, 255],
                    artifact_type: None,
                    render_hints: None,
                    materialized_path: None,
                },
            ],
        };
        let text = MagicianV2Orchestrator::primary_text_from_outcome(&outcome)
            .expect("text artifact should yield primary text");
        assert!(
            text.contains("Gravity pulls things down"),
            "expected stage text, got: {text}"
        );
        assert!(
            !text.contains('\u{0}'),
            "binary image bytes must not leak into the captured text"
        );
    }

    /// C1: a stage that produced only non-text (media) artifacts yields no primary
    /// text (media is captured separately via the segregated index).
    #[test]
    fn test_pipeline_engine_primary_text_none_when_only_binary() {
        use crate::magician_v2::execution::{AgenticOutcome, Artifact, EnvironmentState};
        let outcome = AgenticOutcome::Success {
            completion: crate::magician_v2::execution::agentic::types::CompletionKind::Full,
            open: Vec::new(),
            final_state: EnvironmentState::Uninitialized,
            iterations_used: 1,
            artifacts: vec![Artifact {
                name: "panel.png".to_string(),
                content_type: "image/png".to_string(),
                data: vec![0u8, 1, 2, 3],
                artifact_type: None,
                render_hints: None,
                materialized_path: None,
            }],
        };
        assert!(MagicianV2Orchestrator::primary_text_from_outcome(&outcome).is_none());
    }

    /// The root artifact index is cumulative. Exact re-entry keeps the logical
    /// attempt's original baseline: output from the first scheduler invocation
    /// remains part of the same durable attempt instead of disappearing behind a
    /// newly minted retry cursor.
    #[test]
    fn test_pipeline_engine_deliverable_delta_keeps_same_attempt_pre_reentry_output() {
        use crate::magician_v2::execution::ChildMediaRef;

        let media = |name: &str| ChildMediaRef {
            relative_path: name.to_string(),
            media_type: "image/png".to_string(),
            serving_url: format!("/outputs/{name}"),
            caption: None,
        };
        // The first invocation materializes output and then loses the following
        // boundary. Exact re-entry finishes without hiding that earlier output.
        let logical_attempt_baseline = (
            Some("stage zero output".to_string()),
            vec![media("stage-zero.png")],
        );
        let after_exact_reentry = (
            Some(
                "stage zero output\n\neffect output before boundary loss\n\ncompletion after re-entry"
                    .to_string(),
            ),
            vec![
                media("stage-zero.png"),
                media("effect-before-boundary.png"),
                media("completion-after-reentry.png"),
            ],
        );

        let (text, promoted_media) = MagicianV2Orchestrator::pipeline_stage_deliverable_delta(
            &logical_attempt_baseline,
            after_exact_reentry,
        );
        assert_eq!(
            text.as_deref(),
            Some("effect output before boundary loss\n\ncompletion after re-entry")
        );
        assert_eq!(
            promoted_media,
            vec![
                media("effect-before-boundary.png"),
                media("completion-after-reentry.png")
            ]
        );
    }

    /// R3: the final aggregation carries EVERY stage's agent + text + media serving
    /// URL through the shared `render_child_deliverables_block` renderer, and keeps
    /// the last successful stage's iteration count.
    #[test]
    fn test_pipeline_engine_finalize_aggregates_all_stage_deliverables() {
        use crate::magician_v2::execution::{
            AgenticOutcome, ChildDeliverableSummary, ChildMediaRef, EnvironmentState,
        };
        let deliverables = vec![
            ChildDeliverableSummary {
                child_execution_id: "wf-root::stage0".to_string(),
                agent_id: "web-researcher".to_string(),
                context: "Research gravity".to_string(),
                primary_text: Some("Gravity is a force pulling masses together.".to_string()),
                media: vec![],
            },
            ChildDeliverableSummary {
                child_execution_id: "wf-root::stage1".to_string(),
                agent_id: "creative-mind".to_string(),
                context: "8-panel Doraemon-style comic".to_string(),
                primary_text: Some("Panel 1: Nobita drops an apple.".to_string()),
                media: vec![ChildMediaRef {
                    relative_path: "comic.png".to_string(),
                    media_type: "image/png".to_string(),
                    serving_url: "/api/magician/v3/tasks/task-1/outputs/comic.png".to_string(),
                    caption: None,
                }],
            },
        ];
        let last = Some(AgenticOutcome::Success {
            completion: crate::magician_v2::execution::agentic::types::CompletionKind::Full,
            open: Vec::new(),
            final_state: EnvironmentState::Uninitialized,
            iterations_used: 5,
            artifacts: vec![],
        });
        let outcome = MagicianV2Orchestrator::finalize_pipeline_outcome(last, &deliverables);
        match outcome {
            AgenticOutcome::Success {
                artifacts,
                iterations_used,
                ..
            } => {
                assert_eq!(
                    iterations_used, 5,
                    "should keep last successful stage's count"
                );
                let aggregate = artifacts
                    .iter()
                    .find(|artifact| artifact.name == "pipeline_deliverable")
                    .expect("aggregate deliverable artifact");
                let body = String::from_utf8(aggregate.data.clone()).expect("utf8 aggregate");
                assert!(
                    body.contains("web-researcher"),
                    "missing stage-0 agent: {body}"
                );
                assert!(
                    body.contains("creative-mind"),
                    "missing stage-1 agent: {body}"
                );
                assert!(body.contains("Gravity is a force"), "missing stage-0 text");
                assert!(body.contains("Panel 1: Nobita"), "missing stage-1 text");
                assert!(
                    body.contains("/api/magician/v3/tasks/task-1/outputs/comic.png"),
                    "missing stage-1 media serving url: {body}"
                );
            },
            other => panic!("expected aggregated Success, got {other:?}"),
        }
    }

    /// When the pipeline produced NO deliverable at all, a non-success terminal is
    /// propagated VERBATIM (the engine does not mask an empty failure as Success).
    #[test]
    fn test_pipeline_engine_finalize_propagates_non_success_when_empty() {
        use crate::magician_v2::execution::{
            AgenticOutcome, ChildDeliverableSummary, EnvironmentState,
        };
        let last = Some(AgenticOutcome::Failed {
            reason: "stage tool crashed".to_string(),
            last_state: EnvironmentState::Uninitialized,
            iterations_used: 2,
        });
        let empty_heading = ChildDeliverableSummary {
            child_execution_id: "wf-root::stage0".to_string(),
            agent_id: "researcher".to_string(),
            context: "No durable output".to_string(),
            primary_text: None,
            media: Vec::new(),
        };
        let outcome = MagicianV2Orchestrator::finalize_pipeline_outcome(last, &[empty_heading]);
        assert!(
            matches!(outcome, AgenticOutcome::Failed { .. }),
            "renderer headings without text/media are not a usable deliverable"
        );
    }

    /// A crash-recovery loss marker is failure metadata, not work product. The
    /// effect-over-method finalizer must not promote it to Success merely
    /// because the renderer turns the summary into non-empty markdown.
    #[test]
    fn test_pipeline_engine_finalize_does_not_promote_recovery_loss_marker() {
        use crate::magician_v2::execution::{
            AgenticOutcome, ChildDeliverableSummary, EnvironmentState,
        };
        let failed = AgenticOutcome::Failed {
            reason: "terminal stage lost its in-hand deliverable".to_string(),
            last_state: EnvironmentState::Uninitialized,
            iterations_used: 0,
        };
        let marker = ChildDeliverableSummary {
            child_execution_id: "wf-root::stage0".to_string(),
            agent_id: "researcher".to_string(),
            context: "Recovered stage".to_string(),
            primary_text: Some(format!(
                "{PIPELINE_RECOVERED_DELIVERABLE_LOSS_PREFIX}durable output was unavailable"
            )),
            media: Vec::new(),
        };

        let outcome = MagicianV2Orchestrator::finalize_pipeline_outcome(Some(failed), &[marker]);
        assert!(matches!(outcome, AgenticOutcome::Failed { .. }));
    }

    /// A continuation outcome is authoritative even when earlier stages already
    /// produced enough output to render a non-empty aggregate. It must never be
    /// converted to Success by final collation.
    #[test]
    fn test_pipeline_engine_finalize_never_masks_continuation_as_success() {
        use crate::magician_v2::execution::{
            agentic::AgenticPauseState, AgenticOutcome, ChildDeliverableSummary, EnvironmentState,
        };
        let pause_state = AgenticPauseState::new(
            4,
            "paused stage",
            "finish paused stage",
            EnvironmentState::Uninitialized,
            "checkpoint",
            4,
            3,
        );
        let paused = AgenticOutcome::MaxIterationsReached {
            last_state: EnvironmentState::Uninitialized,
            iterations_used: 4,
            pause_state: Some(pause_state),
        };
        let deliverables = vec![ChildDeliverableSummary {
            child_execution_id: "wf-root::stage0".to_string(),
            agent_id: "researcher".to_string(),
            context: "completed prior stage".to_string(),
            primary_text: Some("valuable prior output".to_string()),
            media: Vec::new(),
        }];

        let outcome =
            MagicianV2Orchestrator::finalize_pipeline_outcome(Some(paused), &deliverables);
        assert!(matches!(
            outcome,
            AgenticOutcome::MaxIterationsReached {
                pause_state: Some(_),
                ..
            }
        ));
    }

    /// A continuation boundary must be published unchanged only after the
    /// durable outer cursor records paused-stage ownership. This source lock
    /// prevents regression to the old fail-closed terminal conversion, which
    /// abandoned the remaining sealed roster.
    #[test]
    fn test_pipeline_engine_pause_commits_outer_owner_before_returning_checkpoint() {
        let source = include_str!("v2_orchestrator.rs");
        let engine = source
            .split("async fn execute_pipeline_single_context")
            .nth(1)
            .and_then(|tail| tail.split("fn wait_for_pipeline_stage_task").next())
            .expect("pipeline engine source window");
        let pause = engine
            .find("if outcome.requires_continuation()")
            .expect("continuation classification");
        let durable_owner = engine[pause..]
            .find("mark_pipeline_stage_paused")
            .map(|offset| pause + offset)
            .expect("durable paused-stage owner");
        let returned = engine[durable_owner..]
            .find("return Ok(outcome)")
            .map(|offset| durable_owner + offset)
            .expect("original checkpoint outcome returned");
        assert!(pause < durable_owner && durable_owner < returned);
        assert!(!engine.contains("pipeline_continuation_unsupported"));
    }

    /// Crash recovery must inspect the exact segment's authoritative terminal
    /// before creating a stage task. The outer CAS must also precede advancing
    /// to the next roster entry, so a crash in either window adopts work once.
    #[test]
    fn test_pipeline_engine_adopts_committed_terminal_before_redispatch() {
        let source = include_str!("v2_orchestrator.rs");
        let engine = source
            .split("async fn execute_pipeline_single_context")
            .nth(1)
            .and_then(|tail| tail.split("fn wait_for_pipeline_stage_task").next())
            .expect("pipeline engine source window");
        let terminal_probe = engine
            .find("committed_pipeline_segment_settlement")
            .expect("authoritative terminal probe");
        let terminal_commit = engine[terminal_probe..]
            .find("commit_pipeline_stage")
            .map(|offset| terminal_probe + offset)
            .expect("terminal adoption outer CAS");
        let dispatch = engine[terminal_commit..]
            .find("StageGuard::push")
            .map(|offset| terminal_commit + offset)
            .expect("stage dispatch boundary");
        let durable_output_guard = engine[terminal_probe..terminal_commit]
            .find("PIPELINE_RECOVERED_DELIVERABLE_LOSS_PREFIX")
            .expect("ambiguous empty terminal must converge as explicit loss");
        assert!(engine[terminal_probe..terminal_commit].contains("sealed_deliverable"));
        assert!(engine[terminal_probe..terminal_commit].contains("TerminalKind::Failed"));
        let next_stage = engine[terminal_commit..]
            .find("continue;")
            .map(|offset| terminal_commit + offset)
            .expect("next sealed stage");
        assert!(terminal_probe < terminal_commit);
        assert!(durable_output_guard > 0);
        assert!(terminal_commit < next_stage && next_stage < dispatch);
    }

    /// A live exact resume is reduced into the outer cursor before the normal
    /// root reducer can see it. Errors and successful adoption both return from
    /// the exact-resume owner; only a newly-produced pause reaches the ordinary
    /// pause persistence path.
    #[test]
    fn test_pipeline_exact_resume_is_fail_closed_before_root_settlement() {
        let source = include_str!("v2_orchestrator.rs");
        let resume = source
            .split("async fn spawn_exact_paused_resume")
            .nth(1)
            .and_then(|tail| tail.split("async fn restore_failed_exact_resume").next())
            .expect("exact resume source window");
        let pipeline = resume
            .find("continue_pipeline_after_exact_stage_outcome")
            .expect("outer pipeline reducer");
        let ordinary = resume
            .find("workflow_event_for_agentic_outcome")
            .expect("ordinary root reducer");
        let error_branch = &resume[pipeline..ordinary];
        assert!(error_branch.contains("Err(error)"));
        assert!(error_branch.contains("return;"));
        assert!(pipeline < ordinary);
    }

    /// The child-ready owner must perform the same outer reduction as the
    /// interactive exact-resume owner. Returning its raw inner outcome first
    /// lets Artifact mark the shared root terminal before the remaining sealed
    /// roster can re-enter.
    #[test]
    fn test_delegation_checkpoint_reduces_pipeline_before_returning_inner_outcome() {
        let source = include_str!("v2_orchestrator.rs");
        let resume = source
            .split("async fn resume_delegation_checkpoint")
            .nth(1)
            .and_then(|tail| tail.split("pub async fn spawn_explicit_delegation").next())
            .expect("delegation checkpoint source window");
        let pipeline = resume
            .find("continue_pipeline_after_exact_stage_outcome")
            .expect("outer pipeline reducer");
        let ordinary = resume
            .find("workflow_event_for_agentic_outcome")
            .expect("ordinary root reducer");
        assert!(pipeline < ordinary);
        assert!(resume[pipeline..ordinary].contains("DelegationCheckpointResume::PipelineOwned"));
        assert!(resume[pipeline..ordinary].contains("retire_checkpoint"));
    }

    #[test]
    fn delegation_checkpoint_refreshes_under_fence_and_cannot_resurrect_terminal_parent() {
        let source = include_str!("v2_orchestrator.rs");
        let resume = source
            .split("async fn resume_delegation_checkpoint")
            .nth(1)
            .and_then(|tail| tail.split("pub async fn spawn_explicit_delegation").next())
            .expect("delegation checkpoint source window");
        let fence = resume
            .find("acquire_stateless_execution_lifecycle_exclusion_scoped")
            .expect("exact execution lifecycle fence");
        let terminal = resume[fence..]
            .find("execution.waiting_state.is_terminal()")
            .map(|offset| fence + offset)
            .expect("terminal supersession check");
        let admitted_states = resume[terminal..]
            .find("WaitingState::Runnable | WaitingState::Executing")
            .map(|offset| terminal + offset)
            .expect("rolling-safe child-ready recovery states");
        let refresh = resume[admitted_states..]
            .find("refresh_internal_pause_metadata_scoped")
            .map(|offset| admitted_states + offset)
            .expect("bounded durable checkpoint refresh");
        let hydrate = resume[refresh..]
            .find("load_verified_delegation_on_execution_runtime")
            .map(|offset| refresh + offset)
            .expect("non-destructive exact checkpoint hydration");
        let claimed_deferred = resume[hydrate..]
            .find("protected_delegation_claim_deferred_until")
            .map(|offset| hydrate + offset)
            .expect("verified live protected claim deferral");
        let claimed_return = resume[claimed_deferred..]
            .find("return Ok(DelegationCheckpointResume::Deferred")
            .map(|offset| claimed_deferred + offset)
            .expect("live protected claim returns without runtime mutation");
        let foreign_owner = resume[claimed_return..]
            .find("initial_foreign_owner")
            .map(|offset| claimed_return + offset)
            .expect("exact successor foreign-owner check");
        let transition = resume[foreign_owner..]
            .find("WorkflowEvent::ExecutionStart")
            .map(|offset| foreign_owner + offset)
            .expect("Runnable to Executing transition");
        let release = resume[transition..]
            .find("drop(execution_lifecycle_guard)")
            .map(|offset| transition + offset)
            .expect("fence release before provider loop");
        assert!(fence < terminal && terminal < admitted_states && admitted_states < refresh);
        assert!(refresh < hydrate && hydrate < claimed_deferred);
        assert!(claimed_deferred < claimed_return && claimed_return < foreign_owner);
        assert!(foreign_owner < transition && transition < release);
        assert!(resume.contains("DelegationCheckpointResume::Superseded"));
        assert!(resume.contains("DelegationCheckpointResume::Deferred"));
        let provider = resume
            .find("execute_agentically_resume_exact")
            .expect("exact resume provider boundary");
        let retirement = resume[provider..]
            .find("retire_checkpoint")
            .map(|offset| provider + offset)
            .expect("post-success exact retirement");
        assert!(release < provider && provider < retirement);
    }

    #[test]
    fn direct_delegation_lease_refusal_defers_before_runtime_settlement() {
        let source = include_str!("v2_orchestrator.rs");
        let resume = source
            .split("async fn resume_delegation_checkpoint")
            .nth(1)
            .and_then(|tail| tail.split("pub async fn spawn_explicit_delegation").next())
            .expect("delegation checkpoint source window");
        let provider = resume
            .find("execute_agentically_resume_exact")
            .expect("exact provider boundary");
        let error_path = &resume[provider..];
        let direct_observation = error_path
            .find("delegation_successor_deferred_until(&error)")
            .expect("typed direct lease/pin deferral");
        let typed_return = error_path[direct_observation..]
            .find("return Ok(DelegationCheckpointResume::Deferred")
            .map(|offset| direct_observation + offset)
            .expect("direct observation returns typed Deferred");
        let lifecycle_reacquire = error_path
            .find("acquire_stateless_execution_lifecycle_exclusion_scoped")
            .expect("generic provider-error lifecycle settlement");
        let rollback = error_path
            .find("WorkflowEvent::DelegationChildrenSpawned")
            .expect("generic provider-error park transition");
        assert!(direct_observation < typed_return);
        assert!(typed_return < lifecycle_reacquire && typed_return < rollback);
    }

    #[test]
    fn every_hydrated_delegation_exit_has_release_or_retirement_cleanup() {
        let source = include_str!("v2_orchestrator.rs");
        let resume = source
            .split("async fn resume_delegation_checkpoint")
            .nth(1)
            .and_then(|tail| tail.split("pub async fn spawn_explicit_delegation").next())
            .expect("delegation checkpoint source window");
        let cleanup = resume
            .split("let release_checkpoint_for_retry")
            .nth(1)
            .and_then(|tail| tail.split("let resumed_from_segment").next())
            .expect("delegation cleanup closures");
        assert!(cleanup.contains("release_retained_delegation_claim_for_retry"));
        assert!(
            cleanup
                .matches("forget_exact_pause_process_authority")
                .count()
                >= 2
        );
        assert!(cleanup.contains("retire_verified_delegation_checkpoint"));

        for guarded_exit in [
            "delegation checkpoint entered {state:?}",
            "delegation checkpoint could not enter Executing ({error})",
            "execution was superseded into {current:?}",
            "delegation checkpoint outcome cannot settle from {current:?}",
            "delegation outcome did not publish a durable successor",
        ] {
            let occurrence = resume
                .find(guarded_exit)
                .unwrap_or_else(|| panic!("missing guarded exit {guarded_exit}"));
            let prefix = &resume[occurrence.saturating_sub(500)..occurrence];
            assert!(
                prefix.contains("release_checkpoint_for_retry"),
                "nonterminal exit {guarded_exit} must release its retained claim"
            );
        }
        assert!(resume.contains("retire_checkpoint(\"terminally superseded delegation claim\")"));
    }

    /// Once the source pause is consumed, live liveness belongs to a bounded
    /// same-execution retry owner; it must neither wait indefinitely for a
    /// process restart nor mint a fresh stage attempt.
    #[test]
    fn test_pipeline_outer_reentry_has_a_bounded_live_retry_owner() {
        let source = include_str!("v2_orchestrator.rs");
        let owner = source
            .split("fn schedule_bounded_pipeline_reentry")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub async fn continue_pipeline_after_exact_stage_outcome")
                    .next()
            })
            .expect("bounded recovery owner source window");
        assert!(owner.contains("Duration::from_millis(250)"));
        assert!(owner.contains("Duration::from_secs(1)"));
        assert!(owner.contains("Duration::from_secs(4)"));
        assert!(owner.contains("continue_committed_pipeline_execution"));
        assert!(owner.contains("catch_unwind"));
        assert!(!owner.contains("PIPELINE_STAGE_LOGICAL_ATTEMPT +"));

        let reducer = source
            .split("pub async fn continue_pipeline_after_exact_stage_outcome")
            .nth(1)
            .and_then(|tail| tail.split("fn stage_iteration_budget").next())
            .expect("outer reducer source window");
        assert!(reducer.matches("schedule_bounded_pipeline_reentry").count() >= 2);
    }

    /// Static ordering lock for the async cancellation boundary. The stage task's
    /// join result (including panic) is held opaque until `StageGuard::finish`
    /// restores the root owner; continuation classification also precedes artifact
    /// collection. This catches a tempting reintroduction of `join_next().await?`.
    #[test]
    fn test_pipeline_engine_source_restores_owner_before_decoding_join_and_stops_pause_before_capture(
    ) {
        let source = include_str!("v2_orchestrator.rs");
        let engine = source
            .split("async fn execute_pipeline_single_context")
            .nth(1)
            .and_then(|tail| tail.split("fn stage_iteration_budget").next())
            .expect("pipeline engine source window");
        let join = engine
            .find("let stage_wait_result")
            .expect("opaque bounded wait result");
        let cancel = engine
            .find("wait_for_pipeline_stage_task")
            .expect("deadline/cancellation wait");
        let restore = engine.find("let restore_result").expect("owner restore");
        let decode = engine
            .find("let stage_result = match stage_wait_result")
            .expect("join decode");
        assert!(join <= cancel && cancel < restore && restore < decode);

        let stop = engine
            .find("if outcome.requires_continuation()")
            .expect("continuation stop");
        let capture = engine
            .find("let cumulative_after_attempt")
            .expect("post-attempt artifact capture");
        assert!(stop < capture);
    }

    /// Persistent deadlines settle through the outer cursor and cannot poll a
    /// stage after expiry. This source-order lock covers both the already-past
    /// boot path and the expiry window during the async owner swap.
    #[test]
    fn test_pipeline_deadline_and_hard_error_settle_before_or_through_outer_cas() {
        let source = include_str!("v2_orchestrator.rs");
        let engine = source
            .split("async fn execute_pipeline_single_context")
            .nth(1)
            .and_then(|tail| tail.split("fn wait_for_pipeline_stage_task").next())
            .expect("pipeline engine source window");
        let preflight = engine
            .find("deadline_expired_before_dispatch")
            .expect("pre-dispatch deadline guard");
        let owner = engine[preflight..]
            .find("StageGuard::push")
            .map(|offset| preflight + offset)
            .expect("owner swap");
        let post_swap = engine[owner..]
            .find("active_stage_deadline_at_ms")
            .map(|offset| owner + offset)
            .expect("post-owner-swap deadline guard");
        let dispatch = engine
            .find("stage_jobs.spawn")
            .expect("stage task dispatch");
        let outer_cas = engine
            .rfind("commit_pipeline_stage")
            .expect("normal outer cursor commit");
        assert!(preflight < owner && owner < post_swap && post_swap < dispatch);
        assert!(engine[post_swap..dispatch].contains("break AgenticOutcome::Failed"));
        assert!(engine.contains("PipelineStageTaskWait::TimedOut => Ok(AgenticOutcome::Failed"));
        assert!(engine.contains("resume_invocations >= MAX_STAGE_RESUME_INVOCATIONS"));
        assert!(engine.contains("break AgenticOutcome::Failed"));
        assert!(dispatch < outer_cas);
    }

    #[test]
