    #[test]
    fn stateless_pause_and_resume_tree_share_sorted_terminal_execution_exclusions() {
        let source = include_str!("v2_orchestrator.rs");
        let pause = source
            .split("async fn pause_execution_tree_locked")
            .nth(1)
            .and_then(|tail| tail.split("pub async fn resume_execution_tree").next())
            .expect("pause-tree implementation");
        let pause_terminal_guard = pause
            .find("acquire_stateless_execution_lifecycle_exclusion_scoped")
            .expect("pause terminal execution guard");
        let pause_refresh = pause
            .find("refresh_stateless_terminal_pause_admission_scoped")
            .expect("pause durable staged refresh");
        let pause_manual_guard = pause
            .find("manual_resume_tx::acquire_execution_admission_exclusion")
            .expect("pause manual transaction guard");
        let pause_control_commit = pause
            .find("commit_manual_pause_tree")
            .expect("durable pause control publication");
        let pause_drop_manual = pause
            .find("drop(pause_admission_guards)")
            .expect("manual guard release");
        let pause_drop_terminal = pause
            .find("drop(terminal_execution_guards)")
            .expect("terminal guard release");
        let pause_wait = pause
            .find("wait_for_manual_pause_ready")
            .expect("worker checkpoint wait");
        assert!(pause_terminal_guard < pause_refresh);
        assert!(pause_refresh < pause_manual_guard);
        assert!(pause_manual_guard < pause_control_commit);
        assert!(pause_control_commit < pause_drop_manual);
        assert!(pause_drop_manual < pause_drop_terminal && pause_drop_terminal < pause_wait);

        let resume = source
            .split("async fn resume_execution_tree_locked")
            .nth(1)
            .and_then(|tail| {
                tail.split("pub fn register_active_execution_controls")
                    .next()
            })
            .expect("resume-tree implementation");
        let resume_terminal_guard = resume
            .find("acquire_stateless_execution_lifecycle_exclusion_scoped")
            .expect("resume terminal execution guard");
        let resume_refresh = resume
            .find("refresh_stateless_terminal_pause_admission_scoped")
            .expect("resume durable staged refresh");
        let resume_manual_guard = resume
            .find("manual_resume_tx::acquire_execution_admission_exclusion")
            .expect("resume manual transaction guard");
        let source_claim = resume
            .find("claim_stateless_manual_resume")
            .expect("exact pause source claim");
        let status_cas = resume
            .rfind("compare_exchange_execution_status_unlocked")
            .expect("last resume status CAS");
        let resume_drop_manual = resume
            .find("drop(execution_admission_guards)")
            .expect("resume manual guard release");
        let resume_drop_terminal = resume
            .find("drop(terminal_execution_guards)")
            .expect("resume terminal guard release");
        let launch = resume
            .rfind("exact_launch_gate.add_permits")
            .expect("exact launch publication");
        assert!(resume_terminal_guard < resume_refresh);
        assert!(resume_refresh < resume_manual_guard && resume_manual_guard < source_claim);
        assert!(source_claim < status_cas && status_cas < resume_drop_manual);
        assert!(resume_drop_manual < resume_drop_terminal && resume_drop_terminal < launch);
    }

