    /// Effect over method: when a stage produced a usable deliverable but its terminal
    /// outcome was non-success (the agent did the work but never emitted a clean
    /// `goal_reached`), the pipeline still surfaces the work as a SUCCESS rather than
    /// discarding it as a failure.
    #[test]
    fn test_pipeline_engine_finalize_surfaces_deliverable_despite_failed_last() {
        use crate::magician_v2::execution::{
            AgenticOutcome, ChildDeliverableSummary, EnvironmentState,
        };
        let deliverables = vec![ChildDeliverableSummary {
            child_execution_id: "wf-root::stage0".to_string(),
            agent_id: "web-researcher".to_string(),
            context: "Research the topic".to_string(),
            primary_text: Some("Hermes Agent is an open-source self-improving agent.".to_string()),
            media: vec![],
        }];
        let last = Some(AgenticOutcome::Failed {
            reason: "no-progress auto-conclude".to_string(),
            last_state: EnvironmentState::Uninitialized,
            iterations_used: 20,
        });
        let outcome = MagicianV2Orchestrator::finalize_pipeline_outcome(last, &deliverables);
        match outcome {
            AgenticOutcome::Success { artifacts, .. } => {
                let body = artifacts
                    .iter()
                    .find(|a| a.name == "pipeline_deliverable")
                    .map(|a| String::from_utf8_lossy(&a.data).into_owned())
                    .expect("aggregate deliverable artifact");
                assert!(
                    body.contains("Hermes Agent is an open-source"),
                    "the produced research must be surfaced, not discarded: {body}"
                );
            },
            other => panic!("a stage that produced output must surface as Success, got {other:?}"),
        }
    }

    /// The per-stage iteration budget derives from the declared timeout (clamped),
    /// defaulting to 60 when none is declared.
    #[test]
    fn test_pipeline_engine_stage_iteration_budget() {
        use crate::magician_v2::execution::PipelineStage;
        let stage = |timeout_secs: Option<u64>| PipelineStage {
            agent_id: "a".to_string(),
            context: "c".to_string(),
            success_criteria: None,
            timeout_secs,
        };
        assert_eq!(
            MagicianV2Orchestrator::stage_iteration_budget(&stage(None)),
            60
        );
        assert_eq!(
            MagicianV2Orchestrator::stage_iteration_budget(&stage(Some(0))),
            60
        );
        // 50/5 = 10 → clamped up to the floor (20)
        assert_eq!(
            MagicianV2Orchestrator::stage_iteration_budget(&stage(Some(50))),
            20
        );
        // 300/5 = 60 (mid-band)
        assert_eq!(
            MagicianV2Orchestrator::stage_iteration_budget(&stage(Some(300))),
            60
        );
        // huge timeout → clamped down to the ceiling (400)
        assert_eq!(
            MagicianV2Orchestrator::stage_iteration_budget(&stage(Some(100_000))),
            400
        );

        assert_eq!(
            MagicianV2Orchestrator::pipeline_stage_timeout_duration(&stage(None)),
            None
        );
        assert_eq!(
            MagicianV2Orchestrator::pipeline_stage_timeout_duration(&stage(Some(0))),
            None,
            "legacy zero timeout remains equivalent to no stage-local deadline"
        );
        assert_eq!(
            MagicianV2Orchestrator::pipeline_stage_timeout_duration(&stage(Some(37))),
            Some(std::time::Duration::from_secs(37))
        );
    }

    /// Scheduler re-entry must resolve to the exact same state/effect-ledger
    /// address. Different stages remain isolated from one another.
    #[test]
    fn test_pipeline_engine_reentry_reuses_logical_attempt_segment() {
        let first_invocation = MagicianV2Orchestrator::pipeline_stage_loop_state_segment(3);
        let resumed_invocation = MagicianV2Orchestrator::pipeline_stage_loop_state_segment(3);
        let next_stage = MagicianV2Orchestrator::pipeline_stage_loop_state_segment(4);

        assert_eq!(first_invocation, resumed_invocation);
        assert_eq!(first_invocation.attempt, PIPELINE_STAGE_LOGICAL_ATTEMPT);
        assert_ne!(first_invocation, next_stage);
    }

    /// A hard wall-clock deadline sends cooperative cancellation and returns only
    /// after the cancellation-aware task has had a bounded chance to clean up.
    #[tokio::test]
    async fn test_pipeline_engine_deadline_cancels_and_drains_stage_task() {
        let stage_cancel = CancellationToken::new();
        let task_cancel = stage_cancel.clone();
        let observed_cancel = Arc::new(AtomicBool::new(false));
        let task_observed_cancel = Arc::clone(&observed_cancel);
        let mut stage_jobs = tokio::task::JoinSet::new();
        stage_jobs.spawn(async move {
            task_cancel.cancelled().await;
            task_observed_cancel.store(true, Ordering::SeqCst);
            41usize
        });

        let result = MagicianV2Orchestrator::wait_for_pipeline_stage_task(
            &mut stage_jobs,
            &stage_cancel,
            Some(tokio::time::Instant::now() + std::time::Duration::from_millis(10)),
            std::time::Duration::from_millis(100),
            std::time::Duration::from_millis(20),
        )
        .await;

        assert!(matches!(result, PipelineStageTaskWait::TimedOut));
        assert!(stage_cancel.is_cancelled());
        assert!(observed_cancel.load(Ordering::SeqCst));
        assert!(stage_jobs.is_empty());
    }

    /// A stage that ignores cooperative cancellation is aborted after the grace
    /// period and drained; it cannot hold the pipeline owner forever.
    #[tokio::test]
    async fn test_pipeline_engine_deadline_aborts_uncooperative_stage() {
        let stage_cancel = CancellationToken::new();
        let mut stage_jobs = tokio::task::JoinSet::new();
        stage_jobs.spawn(std::future::pending::<usize>());

        let result = MagicianV2Orchestrator::wait_for_pipeline_stage_task(
            &mut stage_jobs,
            &stage_cancel,
            Some(tokio::time::Instant::now() + std::time::Duration::from_millis(5)),
            std::time::Duration::from_millis(5),
            std::time::Duration::from_millis(100),
        )
        .await;

        assert!(matches!(result, PipelineStageTaskWait::TimedOut));
        assert!(stage_cancel.is_cancelled());
        assert!(stage_jobs.is_empty());
    }

    /// Finishing before the deadline returns the task's value without spuriously
    /// cancelling the stage token.
    #[tokio::test]
    async fn test_pipeline_engine_deadline_preserves_completed_stage() {
        let stage_cancel = CancellationToken::new();
        let mut stage_jobs = tokio::task::JoinSet::new();
        stage_jobs.spawn(async { 73usize });

        let result = MagicianV2Orchestrator::wait_for_pipeline_stage_task(
            &mut stage_jobs,
            &stage_cancel,
            Some(tokio::time::Instant::now() + std::time::Duration::from_secs(1)),
            std::time::Duration::from_millis(20),
            std::time::Duration::from_millis(20),
        )
        .await;

        match result {
            PipelineStageTaskWait::Completed(Some(Ok(value))) => assert_eq!(value, 73),
            _ => panic!("stage completed before its deadline but was not returned"),
        }
        assert!(!stage_cancel.is_cancelled());
        assert!(stage_jobs.is_empty());
    }

    /// Startup recovery can complete after a waiter constructs `Notified` but
    /// before it first polls it. `notify_one` retains a permit for that window;
    /// changing either recovery owner back to `notify_waiters` can hang the
    /// ordered startup sweep forever on the final job.
    #[tokio::test]
    async fn interrupted_recovery_completion_uses_a_stored_notify_permit() {
        let notify = tokio::sync::Notify::new();
        let completion = notify.notified();
        notify.notify_one();
        tokio::time::timeout(std::time::Duration::from_millis(20), completion)
            .await
            .expect("notify_one must retain the final completion permit");

        let orchestrator_source = include_str!("v2_orchestrator.rs");
        assert!(orchestrator_source.contains("struct InterruptedExecutionRecoveryLaunchGuard"));
        assert!(orchestrator_source.contains("self.changed.notify_one()"));
        let artifact_source = include_str!("../artifact_v2/service.rs");
        assert!(artifact_source.contains("interrupted_runtime_recoveries_changed.notify_one()"));
    }

    // ── STEP 3 / Increment 1c — up-front decomposer (pure-logic locks) ──
    //
    // These pin the decomposer's deterministic logic with zero infra: parsing the
    // structured LLM output into `PipelineStage`s, validating each against the real
    // delegation roster, and the "<2 valid stages → defer to the dynamic path"
    // self-gate. The LLM call + roster gathering is a thin I/O shell mirroring the
    // proven `learning/reflection` pattern; the FULL live decomposition is exercised
    // by the chat orchestrate_pipeline path under the flag.

    fn dtarget(
        agent_id: &str,
        name: &str,
        tools: &[&str],
    ) -> crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget {
        crate::magician_v2::execution::agentic::delegation_dispatch::DelegationTarget {
            agent_id: agent_id.to_string(),
            name: name.to_string(),
            aliases: Vec::new(),
            description: format!("{name} description"),
            tools: tools.iter().map(|t| t.to_string()).collect(),
            allowed_invocation_surfaces: vec![
                crate::magician_v2::agents::InvocationSurface::Delegation,
                crate::magician_v2::agents::InvocationSurface::Handover,
            ],
        }
    }

    fn ids(slice: &[&str]) -> std::collections::HashSet<String> {
        slice.iter().map(|s| s.to_string()).collect()
    }

    /// Valid multi-stage output parses into ordered PipelineStages, optional fields included.
    #[test]
    fn test_decompose_parse_valid_two_stages() {
        let content = r#"{"stages":[
            {"agent_id":"web-researcher","context":"Research gravity","success_criteria":"key facts found","timeout_secs":120},
            {"agent_id":"creative-mind","context":"Draw an 8-panel comic"}
        ]}"#;
        let stages = MagicianV2Orchestrator::parse_and_validate_decomposed_stages(
            content,
            &ids(&["web-researcher", "creative-mind"]),
        );
        assert_eq!(stages.len(), 2);
        assert_eq!(stages[0].agent_id, "web-researcher");
        assert_eq!(stages[0].context, "Research gravity");
        assert_eq!(
            stages[0].success_criteria.as_deref(),
            Some("key facts found")
        );
        assert_eq!(stages[0].timeout_secs, Some(120));
        assert_eq!(stages[1].agent_id, "creative-mind");
        assert_eq!(stages[1].success_criteria, None);
        assert_eq!(stages[1].timeout_secs, None);
    }

    /// A stage assigned to an agent NOT in the roster is dropped; the rest survive.
    #[test]
    fn test_decompose_parse_drops_unknown_agent_keeps_valid() {
        let content = r#"{"stages":[
            {"agent_id":"web-researcher","context":"research"},
            {"agent_id":"ghost-agent","context":"hallucinated stage"},
            {"agent_id":"creative-mind","context":"draw"}
        ]}"#;
        let stages = MagicianV2Orchestrator::parse_and_validate_decomposed_stages(
            content,
            &ids(&["web-researcher", "creative-mind"]),
        );
        assert_eq!(stages.len(), 2, "unknown agent dropped, two valid survive");
        assert!(stages.iter().all(|s| s.agent_id != "ghost-agent"));
        let (_, contract_valid) =
            MagicianV2Orchestrator::parse_and_validate_decomposed_stages_with_status(
                content,
                &ids(&["web-researcher", "creative-mind"]),
            );
        assert!(
            !contract_valid,
            "unauthorized stage must be visible to telemetry"
        );
    }

    /// Fewer than two VALID stages → empty (caller defers to the dynamic path).
    #[test]
    fn test_decompose_parse_under_two_valid_defers() {
        let content = r#"{"stages":[
            {"agent_id":"web-researcher","context":"just research, single capability"},
            {"agent_id":"ghost-agent","context":"dropped"}
        ]}"#;
        let stages = MagicianV2Orchestrator::parse_and_validate_decomposed_stages(
            content,
            &ids(&["web-researcher", "creative-mind"]),
        );
        assert!(stages.is_empty(), "1 valid stage is not a pipeline → defer");
        let (_, contract_valid) =
            MagicianV2Orchestrator::parse_and_validate_decomposed_stages_with_status(
                r#"{"stages":[{"agent_id":"web-researcher","context":"research"}]}"#,
                &ids(&["web-researcher"]),
            );
        assert!(
            contract_valid,
            "a valid one-stage answer is a product fallback, not malformed output"
        );
    }

    /// A stage with empty context is dropped.
    #[test]
    fn test_decompose_parse_drops_empty_context() {
        let content = r#"{"stages":[
            {"agent_id":"web-researcher","context":"   "},
            {"agent_id":"creative-mind","context":"draw"},
            {"agent_id":"web-researcher","context":"research properly"}
        ]}"#;
        let stages = MagicianV2Orchestrator::parse_and_validate_decomposed_stages(
            content,
            &ids(&["web-researcher", "creative-mind"]),
        );
        assert_eq!(stages.len(), 2);
        assert!(stages.iter().all(|s| !s.context.trim().is_empty()));
    }

    /// Malformed / non-JSON output → empty (defer, never panic).
