    /// 1c-iv integration: `pipeline_stages` routes `execute_agentic_direct_with_outcome`
    /// to the single-context engine, and a stage whose agent is NOT loadable fails
    /// LOUD (never a silent degrade to Ok) WITHOUT spawning a child `ExecutionRun` —
    /// proving the param → branch → engine → `StageGuard::push` error-propagation
    /// chain end to end, plus the structural "one execution, never a child per stage"
    /// guarantee + the Failed-status transition in the tail. (The happy-path full-loop
    /// e2e additionally needs an orchestrator-loop native-response harness, which no
    /// test has yet; the engine's stage loop is otherwise locked by the 1b engine
    /// tests and the 1a swap/trust tests.)
    async fn seed_pipeline_v3_shell(
        orchestrator: &Arc<MagicianV2Orchestrator>,
        base: &std::path::Path,
        title: &str,
        stages: &[crate::magician_v2::execution::PipelineStage],
    ) -> (String, String) {
        let service = Arc::new(
            crate::magician_v2::artifact_v2::ArtifactV2Service::with_orchestrator(
                base.join("magician_data_v3"),
                Arc::clone(orchestrator),
                crate::magician_v2::gaui::MuijStorage::new(base.join("muij")),
            ),
        );
        orchestrator.set_artifact_v2_service(Arc::clone(&service));
        let (task, execution) = service
            .create_task_with_execution_shell(crate::magician_v2::artifact_v2::CreateTaskInput {
                principal: "anonymous".to_owned(),
                workspace: "default".to_owned(),
                title: title.to_owned(),
                description: title.to_owned(),
                agent_id: "root-agent".to_owned(),
                goal_id: None,
                ui_thread_id: crate::magician_v2::storage::task_models::default_ui_thread_id(),
                priority: None,
                due_date: None,
                tags: Vec::new(),
                created_by: "user".to_owned(),
                depends_on: Vec::new(),
                approved: true,
                schedule: None,
                output_mode: crate::magician_v2::artifact_v2::models::TaskOutputMode::Accumulate,
                chat_session_id: None,
                lifecycle: crate::magician_v2::artifact_v2::models::TaskLifecycle::default(),
                sync_mode: crate::magician_v2::artifact_v2::models::TaskSyncMode::default(),
            })
            .await
            .expect("create pipeline V3 shell");
        let scope = crate::magician_v2::artifact_v2::ScopeRef::system_internal_unauthenticated(
            &task.manifest.principal,
            &task.manifest.workspace,
        );
        service
            .activate_execution(
                &scope,
                &task.manifest.task_id,
                &execution.state.execution_id,
            )
            .await
            .expect("activate pipeline V3 shell");
        service
            .persist_execution_pipeline_roster(
                &scope,
                &task.manifest.task_id,
                &execution.state.execution_id,
                stages,
            )
            .await
            .expect("persist pipeline roster");
        (task.manifest.task_id, execution.state.execution_id)
    }

    #[tokio::test]
    async fn test_pipeline_single_context_unloadable_stage_fails_loud_no_child() {
        test_pipeline_single_context_unloadable_stage_fails_loud_no_child_inner().await;
    }

    async fn test_pipeline_single_context_unloadable_stage_fails_loud_no_child_inner() {
        let Some((orchestrator, _session_manager, _store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        // Configure a definition store (empty of the stage agent) so the failure is a
        // genuine "agent not found", not merely "no store configured".
        let tmp = tempfile::tempdir().unwrap();
        let definition_store =
            crate::magician_v2::agents::definition_store::AgentDefinitionStore::with_workspace_root(
                tmp.path(),
            );
        orchestrator.set_definition_store(Arc::new(definition_store));

        let pipeline_stages = vec![crate::magician_v2::execution::PipelineStage {
            agent_id: "missing-specialist".to_string(),
            context: "first stage whose agent cannot be loaded".to_string(),
            success_criteria: None,
            timeout_secs: None,
        }];
        let (task_id, execution_id) = seed_pipeline_v3_shell(
            &orchestrator,
            tmp.path(),
            "Pipeline 1c fail-loud",
            &pipeline_stages,
        )
        .await;
        orchestrator
            .create_execution_with_id(
                "anonymous",
                "default",
                Some("Pipeline 1c fail-loud".to_string()),
                "root-agent",
                &execution_id,
                Some(task_id.clone()),
                Some(execution_id.clone()),
            )
            .await
            .expect("create root execution");

        let overrides = crate::magician_v2::execution::AgenticContextOverrides {
            plane_attenuation: None,
            principal: Some("anonymous".to_string()),
            workspace: Some("default".to_string()),
            task_id: Some(task_id),
            execution_id: Some(execution_id.clone()),
            agent_id: Some("root-agent".to_string()),
            active_owner_agent_id: Some("root-agent".to_string()),
            owner_stack: Vec::new(),
            pipeline_stages: Some(pipeline_stages),
            ..Default::default()
        };

        let result = orchestrator
            .execute_agentic_direct_with_outcome(
                &execution_id,
                "run a one-stage pipeline whose agent is missing",
                None,
                None,
                Some(overrides),
            )
            .await;

        // (1) Loud failure — NOT a silent degrade to Ok.
        assert!(
            result.is_err(),
            "an unloadable stage agent must fail loud, got: {result:?}"
        );

        // (2) NO child ExecutionRun was created for the stage. The human-facing
        // stage label is never installed as routing, artifact, or persisted run
        // identity.
        assert!(
            orchestrator
                .conversation_store
                .get_execution(&format!("{execution_id}::stage0"))
                .await
                .is_err(),
            "the single-context engine must NOT spawn a child ExecutionRun per stage"
        );

        // (3) The execution ended Failed (the direct-execution tail transitioned it),
        // confirming the engine error flowed through the real failure path rather than
        // erroring out earlier in the prologue.
        let status = orchestrator.get_execution_status(&execution_id).await;
        assert!(
            matches!(status, Ok(WaitingState::Failed)),
            "execution should be Failed after a loud pipeline error, got: {status:?}"
        );
    }

    /// Seed a scope-loadable agent definition (template + scoped file with explicit
    /// principal/workspace) so `load_owner_execution_profile` succeeds for it — the
    /// proven pattern from `load_owner_execution_profile_uses_current_scope_for_handover`.
    async fn seed_scoped_agent(
        definition_store: &crate::magician_v2::agents::definition_store::AgentDefinitionStore,
        agent_id: &str,
        principal: &str,
        workspace: &str,
        delegation_targets: &[&str],
    ) {
        let mut definition = sample_worker_definition(agent_id, &format!("{agent_id} template"));
        definition.delegation_targets = delegation_targets
            .iter()
            .map(|target| (*target).to_string())
            .collect();
        definition_store
            .create_definition(definition.clone())
            .await
            .unwrap();
        let scoped_store = definition_store.for_scope(principal, workspace);
        let scoped_path = scoped_store
            .storage()
            .agent_definition_path(agent_id)
            .unwrap();
        tokio::fs::create_dir_all(scoped_path.parent().unwrap())
            .await
            .unwrap();
        definition.principal = Some(principal.to_string());
        definition.workspace = Some(workspace.to_string());
        tokio::fs::write(
            &scoped_path,
            serde_yaml::to_string(&definition).expect("serialize scoped test agent"),
        )
        .await
        .unwrap();
    }

    /// A scripted `goal_reached` decision (carries `evidence` → lowers to a Done
    /// yield → Success). Mirrors the executor test module's `native_response`,
    /// including the benign `task_state_action: none`.
    fn native_goal_reached(
        evidence: &str,
    ) -> crate::magician_v2::execution::agentic::native_types::ExecutionNativeResponse {
        use crate::magician_v2::execution::agentic::native_types::{
            ExecutionNativeResponse, ExecutionToolCall,
        };
        let mut response = ExecutionNativeResponse::unadmitted(vec![ExecutionToolCall {
            id: "test-tool-call".to_string(),
            name: "goal_reached".to_string(),
            // Task-backed runs reject self-attested success without proof; the
            // `COMPLETED:` + `BLOCKED:` partial-success markers are the accepted
            // evidence form when a stage produces no material artifact.
            arguments: serde_json::json!({
                "evidence": format!("COMPLETED: {evidence}\nBLOCKED: none"),
                "task_state_action": { "action": "none", "reason": "test stage complete" }
            }),
        }]);
        response.finish_reason = Some("tool_calls".to_string());
        response
    }

    /// 1c-iv happy-path e2e: a 2-stage `pipeline_stages` roster runs to SUCCESS within
    /// ONE `ExecutionRun` — each stage swaps to its (seeded, loadable) agent, runs a
    /// real `execute_agentically` to `goal_reached`, and the engine threads/aggregates
    /// — with NO child `ExecutionRun` spawned per stage. Success here ⟹ BOTH stages'
    /// agents loaded and ran (a missing/unloadable stage agent would fail the run).
    #[test]
    fn test_pipeline_single_context_two_stages_succeed_one_execution() {
        std::thread::Builder::new()
            .name("pipeline-single-context-e2e".to_string())
            .stack_size(16 * 1024 * 1024)
            .spawn(|| {
                tokio::runtime::Builder::new_current_thread()
                    .enable_all()
                    .build()
                    .expect("pipeline test runtime")
                    .block_on(
                        test_pipeline_single_context_two_stages_succeed_one_execution_inner(),
                    );
            })
            .expect("spawn pipeline test thread")
            .join()
            .expect("pipeline test thread");
    }

    async fn test_pipeline_single_context_two_stages_succeed_one_execution_inner() {
        let Some((orchestrator, _session_manager, _store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        let tmp = tempfile::tempdir().unwrap();
        let definition_store =
            crate::magician_v2::agents::definition_store::AgentDefinitionStore::with_workspace_root(
                tmp.path(),
            );
        // Root (swapped back to after each stage) + two stage specialists, all loadable.
        seed_scoped_agent(
            &definition_store,
            "root-agent",
            "anonymous",
            "default",
            &["stage-one-agent", "stage-two-agent"],
        )
        .await;
        seed_scoped_agent(
            &definition_store,
            "stage-one-agent",
            "anonymous",
            "default",
            &["root-agent"],
        )
        .await;
        seed_scoped_agent(
            &definition_store,
            "stage-two-agent",
            "anonymous",
            "default",
            &["root-agent"],
        )
        .await;
        orchestrator.set_definition_store(Arc::new(definition_store));

        let pipeline_stages = vec![
            crate::magician_v2::execution::PipelineStage {
                agent_id: "stage-one-agent".to_string(),
                context: "Research the topic".to_string(),
                success_criteria: None,
                timeout_secs: None,
            },
            crate::magician_v2::execution::PipelineStage {
                agent_id: "stage-two-agent".to_string(),
                context: "Produce the final deliverable".to_string(),
                success_criteria: None,
                timeout_secs: None,
            },
        ];
        let (task_id, execution_id) = seed_pipeline_v3_shell(
            &orchestrator,
            tmp.path(),
            "Pipeline 1c happy",
            &pipeline_stages,
        )
        .await;
        orchestrator
            .create_execution_with_id(
                "anonymous",
                "default",
                Some("Pipeline 1c happy".to_string()),
                "root-agent",
                &execution_id,
                Some(task_id.clone()),
                Some(execution_id.clone()),
            )
            .await
            .expect("create root execution");

        // Increment 2 / event routing: register a ROOT canonical scope (in production
        // the V3 service registers this at task start). We assert below that the
        // engine registered a scope for each stage's re-stamped execution_id pointing
        // at the ROOT task — the fix that keeps the chat card live across stages.
        orchestrator.register_runtime_canonical_event_scope(
            crate::magician_v2::artifact_v2::events::CanonicalEventScope {
                principal: "anonymous".to_string(),
                workspace: "default".to_string(),
                task_id: task_id.clone(),
                execution_id: execution_id.clone(),
                ui_thread_id: "thread-pipeline-1c".to_string(),
            },
        );

        // Shared FIFO across both stages; re-emits the last when drained, so each
        // stage's loop terminates at `goal_reached` regardless of iteration count.
        orchestrator.set_test_native_responses(vec![
            native_goal_reached("stage one researched the topic"),
            native_goal_reached("stage two produced the deliverable"),
        ]);

        let overrides = crate::magician_v2::execution::AgenticContextOverrides {
            plane_attenuation: None,
            principal: Some("anonymous".to_string()),
            workspace: Some("default".to_string()),
            task_id: Some(task_id),
            execution_id: Some(execution_id.clone()),
            agent_id: Some("root-agent".to_string()),
            active_owner_agent_id: Some("root-agent".to_string()),
            owner_stack: Vec::new(),
            pipeline_stages: Some(pipeline_stages),
            ..Default::default()
        };

        let outcome = orchestrator
            .execute_agentic_direct_with_outcome(
                &execution_id,
                "Research the topic, then produce the deliverable",
                None,
                None,
                Some(overrides),
            )
            .await
            .expect("two-stage pipeline should run to a terminal outcome");

        // (1) Ran to Success — and since a missing stage agent would have failed the
        // run, Success implies BOTH stages' agents loaded + ran in-context.
        assert!(
            matches!(
                outcome,
                crate::magician_v2::execution::AgenticOutcome::Success { .. }
            ),
            "two-stage pipeline should succeed, got: {outcome:?}"
        );

        // (2) NO child ExecutionRun per stage. The engine retains the root id;
        // its stage/attempt loop-state segment is runtime-only.
        for n in 0..2 {
            assert!(
                orchestrator
                    .conversation_store
                    .get_execution(&format!("{execution_id}::stage{n}"))
                    .await
                    .is_err(),
                "stage {n} must NOT have a child ExecutionRun row"
            );
        }

        // (2b) Stages run under the ROOT execution id (not a synthetic
        // `{root}::stage{n}`), so they write to the real registered execution and
        // their events route via the root's canonical scope — NO synthetic per-stage
        // scope is ever registered. (Re-stamping the execution_id to a synthetic id
        // was the prod bug: it has no on-disk execution dir, so every decision-record/
        // screenshot/artifact write failed `missing_v3_execution_scope` and the task
        // finished with no deliverable.)
        for n in 0..2 {
            assert!(
                orchestrator
                    .runtime_canonical_event_scope_for_execution(&format!("{execution_id}::stage{n}"))
                    .is_none(),
                "stage {n} must NOT register a synthetic per-stage canonical scope; it runs under the root execution id"
            );
        }

        // (3) The single root execution remains the only execution and reached a
        // terminal (non-Executing, non-WaitingChildren) state.
        let status = orchestrator
            .get_execution_status(&execution_id)
            .await
            .expect("root execution status");
        assert!(
            !matches!(
                status,
                WaitingState::Executing | WaitingState::WaitingChildren
            ),
            "root execution should be terminal after the pipeline, got: {status:?}"
        );
    }

    #[tokio::test]
    async fn reconcile_waiting_children_keeps_parent_blocked_when_active_child_running() {
        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        let parent_id = "wf-reconcile-parent-blocked";
        let completed_child_id = "wf-reconcile-child-completed";
        let running_child_id = "wf-reconcile-child-running";
        let now = Utc::now().timestamp_millis();

        store
            .insert_execution(ExecutionRun {
                id: parent_id.to_string(),
                principal: "user".to_string(),
                workspace: "workspace".to_string(),
                task_id: None,
                root_execution_id: None,
                title: Some("Parent".to_string()),
                waiting_state: WaitingState::WaitingChildren,
                created_at: now,
                updated_at: now,
                processing_correlation_id: None,
                current_stage: None,
                current_provider: None,
                escalation_trigger: None,
                parent_execution_id: None,
                child_execution_ids: vec![
                    completed_child_id.to_string(),
                    running_child_id.to_string(),
                ],
                active_owner_agent_id: crate::magician_v2::chat::DEFAULT_AGENT_ID.to_string(),
                owner_stack: Vec::new(),
                active_delegation_group: vec![
                    completed_child_id.to_string(),
                    running_child_id.to_string(),
                ],
                timeout_secs: None,
                delegation_chain: Vec::new(),
                work_authority: None,
                paused_from_state: None,
                entry_mode: ExecutionEntryMode::PlanningBacked,
            })
            .await;

        for (execution_id, waiting_state) in [
            (completed_child_id, WaitingState::Completed),
            (running_child_id, WaitingState::Executing),
        ] {
            store
                .insert_execution(ExecutionRun {
                    id: execution_id.to_string(),
                    principal: "user".to_string(),
                    workspace: "workspace".to_string(),
                    task_id: None,
                    root_execution_id: None,
                    title: Some(execution_id.to_string()),
                    waiting_state,
                    created_at: now,
                    updated_at: now,
                    processing_correlation_id: None,
                    current_stage: None,
                    current_provider: None,
                    escalation_trigger: None,
                    parent_execution_id: Some(parent_id.to_string()),
                    child_execution_ids: Vec::new(),
                    active_owner_agent_id: crate::magician_v2::chat::DEFAULT_AGENT_ID.to_string(),
                    owner_stack: Vec::new(),
                    active_delegation_group: Vec::new(),
                    timeout_secs: None,
                    delegation_chain: Vec::new(),
                    work_authority: None,
                    paused_from_state: None,
                    entry_mode: ExecutionEntryMode::PlanningBacked,
                })
                .await;
        }

        let resumed = orchestrator
            .reconcile_waiting_children(parent_id)
            .await
            .expect("reconciliation should not error");
        assert!(!resumed, "running child should keep the parent blocked");

        let parent_execution = store
            .get_execution(parent_id)
            .await
            .expect("parent execution");
        assert_eq!(
            parent_execution.waiting_state,
            WaitingState::WaitingChildren
        );
        assert_eq!(
            parent_execution.active_delegation_group,
            vec![completed_child_id.to_string(), running_child_id.to_string(),],
            "active group should stay intact while a child is still running"
        );
    }

