    #[tokio::test]
    async fn take_manual_pause_for_thread_recovers_stored_exact_snapshot() {
        let Some((orchestrator, _session_manager, _store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        let pause_root = tempfile::TempDir::new().expect("temporary pause root");
        let pause_store = Arc::new(
            crate::magician_v2::execution::agentic::FullPauseStore::with_persistence(
                pause_root.path(),
            ),
        );
        orchestrator.set_full_pause_store(pause_store.clone());

        let pause_state = crate::magician_v2::execution::agentic::AgenticPauseState::new(
            2,
            "Resume exact work",
            "The delegated work completes",
            crate::magician_v2::execution::EnvironmentState::Shell(
                crate::magician_v2::execution::ShellState::default(),
            ),
            "Completed two iterations before manual pause",
            8,
            5,
        )
        .with_observability(
            "execution-manual-recover",
            "plan-manual-recover",
            "step-manual-recover",
        )
        .with_scope("user", "workspace");

        let executors = orchestrator.build_action_executors_with_router_override(Some(Arc::new(
            OperationLlmRouter::new(None),
        )));
        let pause_key = pause_store
            .store_durable(
                crate::magician_v2::execution::agentic::FullPauseData::new(
                    pause_state,
                    crate::magician_v2::execution::agentic::UserInputType::Confirmation {
                        confirm_label: Some("Resume".to_string()),
                        deny_label: Some("Cancel".to_string()),
                        destructive: false,
                    },
                    executors,
                    Some("Execution paused by user".to_string()),
                    Some("Resume to continue from the same point.".to_string()),
                )
                .with_pause_kind(
                    crate::magician_v2::execution::agentic::ExecutionPauseKind::Manual,
                ),
            )
            .expect("manual pause should be durable");

        let recovered = orchestrator
            .take_manual_pause_for_execution_with_recovery(
                "execution-manual-recover",
                "user",
                "workspace",
                // This exercises the resident-loop recovery path. A stateless
                // run reaches its snapshot through a sealed tree transaction
                // instead, which `claim_stateless_manual_resume` owns.
                crate::magician_v2::execution::agentic::run_loop::ExecutionDriver::Inprocess,
            )
            .await
            .expect("manual pause recovery should succeed")
            .expect("manual pause snapshot should exist");

        assert_eq!(
            recovered.pause_data.pause_kind,
            Some(crate::magician_v2::execution::agentic::ExecutionPauseKind::Manual)
        );
        assert_eq!(
            recovered.pause_data.pause_state.execution_id.as_deref(),
            Some("execution-manual-recover")
        );
        assert!(
            pause_store.take(&pause_key).is_none(),
            "manual pause recovery should consume the stored snapshot"
        );
    }

