    #[tokio::test]
    async fn concurrent_resume_and_cancel_settle_the_execution_as_cancelled() {
        let Some((orchestrator, _session_manager, store)) =
            build_orchestrator_with_ask_loop().await
        else {
            eprintln!("Skipping test: MagicutorClient native TLS unavailable");
            return;
        };

        let execution_id = "wf-concurrent-resume-cancel";
        let mut execution = test_execution_run(execution_id, WaitingState::Paused);
        execution.paused_from_state = Some(WaitingState::WaitingUser);
        store.insert_execution(execution).await;

        let barrier = Arc::new(tokio::sync::Barrier::new(3));
        let resume_orchestrator = Arc::clone(&orchestrator);
        let resume_barrier = Arc::clone(&barrier);
        let resume = tokio::spawn(async move {
            resume_barrier.wait().await;
            MagicianV2Orchestrator::resume_execution_tree(&resume_orchestrator, execution_id).await
        });
        let cancel_orchestrator = Arc::clone(&orchestrator);
        let cancel_barrier = Arc::clone(&barrier);
        let cancel = tokio::spawn(async move {
            cancel_barrier.wait().await;
            cancel_orchestrator
                .cancel_execution_tree(execution_id)
                .await
        });
        barrier.wait().await;

        let resume_result = resume.await.expect("resume task should not panic");
        let cancel_result = cancel.await.expect("cancel task should not panic");
        assert!(
            resume_result.is_ok(),
            "resume request failed: {resume_result:?}"
        );
        assert_eq!(cancel_result, Ok(true));
        assert_eq!(
            store
                .get_execution(execution_id)
                .await
                .expect("execution should remain persisted")
                .waiting_state,
            WaitingState::Cancelled
        );
        assert!(!orchestrator
            .active_execution_controls
            .contains_key(execution_id));
    }

